@import '../../styles/table.css';
@import '../../styles/control-elevation.css';
@import '../../utils/chrome-header.css';
@import '../../utils/control-density.css';
@import '../../utils/text-decoration.css';

:host {
  display: block;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  container-type: inline-size;
  container-name: ds-table;
}

:host(.table-host--bounded) {
  min-block-size: 0;
}

:host(.table-host--fixed-height) {
  block-size: var(--_table-fixed-block-size);
}

:host(.table-host--viewport-fit) {
  block-size: var(--_table-viewport-fit-reserved-block-size, auto);
  min-block-size: var(--_table-viewport-fit-reserved-block-size, auto);
}

::slotted([slot='header']) {
  inline-size: 100%;
  min-inline-size: 0;
}

/*
 * The public table recipe stays at zero specificity for product-owned native
 * markup. Inside the component, these classes sit on ds-text hosts whose reset
 * intentionally owns display, padding, and border with higher specificity.
 * Reassert only those collided properties so component geometry cannot depend
 * on whether ds-text or ds-table happens to hydrate first.
 */
ds-text.ds-table__header-label-box {
  padding-inline: var(--dimension-space-025);
}

ds-text.ds-table__cell-track {
  display: flex;
}

.ds-table__cell--text-wrap ds-text.ds-table__cell-track--text,
.ds-table__cell--icon-text-wrap ds-text.ds-table__cell-track--text {
  display: block;
}

ds-text.ds-table__cell-track--text {
  padding-inline: var(--_table-cell-track-padding-inline);
}

ds-text.ds-table__cell-primary,
.ds-table__cell--empty ds-text.ds-table__cell-track {
  padding-block: var(--dimension-space-025);
}

/*
 * The public :where() wrap recipe has zero specificity, so ds-text's
 * variant line-height would win inside the component. Reassert on wrapping
 * cell layout classes so extra primary and secondary lines occupy later tracks.
 */
.ds-table__cell--text-wrap.ds-table__cell--text-single .ds-table__cell-primary,
.ds-table__cell--text-wrap.ds-table__cell--text-multi .ds-table__cell-primary,
.ds-table__cell--icon-text-wrap.ds-table__cell--icon-text-single .ds-table__cell-primary,
.ds-table__cell--icon-text-wrap.ds-table__cell--icon-text-multi .ds-table__cell-primary {
  line-height: var(--_table-wrap-primary-line-height);
  padding-block: var(--_table-wrap-primary-padding-block);
}

.ds-table__cell--text-wrap.ds-table__cell--text-multi .ds-table__cell-copy,
.ds-table__cell--icon-text-wrap.ds-table__cell--icon-text-multi .ds-table__cell-copy {
  gap: 0;
}

.ds-table__cell--text-wrap.ds-table__cell--text-multi .ds-table__cell-secondary,
.ds-table__cell--icon-text-wrap.ds-table__cell--icon-text-multi .ds-table__cell-secondary {
  line-height: var(--_table-wrap-secondary-line-height);
  padding-block: var(--_table-wrap-secondary-padding-block);
}

ds-text.ds-table__cell-secondary,
ds-text.ds-table__cell-tertiary {
  padding-block: var(--dimension-space-025);
}

.ds-table__cell--text-multi ds-text.ds-table__cell-secondary,
.ds-table__cell--text-triple ds-text.ds-table__cell-secondary,
.ds-table__cell--text-triple ds-text.ds-table__cell-tertiary,
.ds-table__cell--icon-text-multi ds-text.ds-table__cell-secondary,
.ds-table__cell--icon-text-triple ds-text.ds-table__cell-secondary,
.ds-table__cell--icon-text-triple ds-text.ds-table__cell-tertiary,
.ds-table__cell--primary-text ds-text.ds-table__cell-secondary {
  min-block-size: var(--_table-cell-track-min-block-size);
}

ds-text.ds-table__cell-run,
ds-text.ds-table__cell-run-separator {
  display: flex;
}

.ds-table__cell-tag-stack--tag-with-text ds-text.ds-table__cell-tag-text,
.ds-table__cell-tag-stack--text-with-tag ds-text.ds-table__cell-tag-text {
  padding-inline: var(--_table-cell-track-padding-inline);
  padding-block: var(--dimension-space-025);
  min-block-size: var(--_table-cell-track-min-block-size);
}

ds-text.ds-table__load-content {
  display: inline-flex;
}

ds-text.ds-table__bar-text {
  display: inline-flex;
  width: auto;
  max-width: 100%;
  padding-inline: var(--ds-control-label-inset, var(--dimension-space-025));
}

ds-text.ds-table__footer-summary {
  margin-inline-start: auto;
}

.ds-table__bar-trailing ds-pagination {
  max-inline-size: 100%;
}

.ds-table__bar-status slot::slotted(*) {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

ds-skeleton.ds-table__skeleton-image-shape {
  display: flex;
  width: 100%;
  height: 100%;
  --ds-control-height: 100%;
}

ds-skeleton.ds-table__skeleton-checkbox {
  --ds-control-height: var(--dimension-iconography-sm);
}

.ds-table__skeleton-checkbox-canvas {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--dimension-size-300);
  block-size: var(--dimension-size-300);
}

.ds-table__caption-customizer {
  position: relative;
  display: flex;
  align-items: center;
  min-inline-size: 0;
}

.ds-table__caption-mode-switcher {
  display: flex;
  align-items: center;
}

.ds-table__caption-customizer--loading > ds-tooltip ds-button-unfilled {
  visibility: hidden;
}

.ds-table__caption-customizer > ds-skeleton {
  position: absolute;
  inset: 0;
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import {
  deriveTableSelectionState,
  formatTableResultSummary,
  formatTableTotalSummary,
  hasOwnedTableFooterSlot,
  isTableCellAction,
  nextTableSortState,
  tableColumnSize,
  tableModelIssues,
  tableRows,
  toggleAllLoadedTableRows,
  toggleTableGroupCollapsed,
  toggleTableGroupSelection,
  nextTableGroupsCollapsed,
  toggleTableRowSelection,
} from './table-model';
import { createTableRenderModel, type TableRenderModel } from './table-render-model';
import {
  isRenderableTableActionMenu,
  nextTableActionMenuElementId,
  tableActionMenuSections,
  tableActionTriggerId,
} from './table-action-menu';
import {
  nextTableColumnCustomizerElementId,
  resolveTableColumnOrder,
  resolveTableHiddenColumnIds,
  resolveTableVisibleColumns,
  tableColumnCustomizerMenuItems,
  toggleTableColumnHidden,
} from './table-column-customizer';
import {
  nextTableDataModeSwitcherElementId,
  tableDataModeFromMenuItem,
  tableDataModeMenuItems,
} from './table-data-mode-switcher';
import { resolveTableTruncateTrack, tableTruncateLabel } from './table-truncate';
import { renderTableRow as renderTableRowView } from './table-row-view';
import { TableBodyRenderer } from './table-body-renderer';
import { renderTableSkeletonBody } from './table-skeleton-view';
import { renderTableLoadContent } from './table-load-view';
import { TableLayoutController } from './table-layout-controller';
import { TableLoadController } from './table-load-controller';
import { TableGroupLoadController } from './table-group-load-controller';
import {
  estimateTableRowBlockSize,
  flattenTableVirtualItems,
  resolveTableVirtualPlan,
  TABLE_VIRTUAL_TOTAL_SUMMARY_LABEL,
  TABLE_VIRTUAL_VIEWPORT_REQUIRED_BODY,
  TABLE_VIRTUAL_VIEWPORT_REQUIRED_HEADING,
  type TableVirtualItem,
  type TableVirtualPlan,
} from './table-virtual-model';
import { TableVirtualController } from './table-virtual-controller';
import type { PaginationChangeDetail } from '../Pagination/pagination-types';
import type { MenuItemData, MenuReorderDetail } from '../Menu/menu-types';
import { resolvePaginationState } from '../Pagination/pagination-model';
import { resolveCssLengthPx } from '../../utils/resolve-css-length-px';
import { isElementTruncated } from '../../utils/is-element-truncated';
import { observeTableCaptionCompact } from '../../utils/table-caption-compact';
import { resolveTableFitPageSize } from './table-pagination-fit';
import { createTableHighlightMatcher, type TableHighlightMatcher } from './table-highlight';
import {
  paginationShortcutBlockedByPath,
  shouldHandleContainingPagePaginationShortcut,
} from './table-pagination-shortcut';
import {
  TableViewportFitController,
  type TableViewportFitMetrics,
} from './table-viewport-fit-controller';
import type {
  TableCaptionVisibility,
  TableCellActionDetail,
  TableColumn,
  TableColumnsConfigChangeDetail,
  TableDataMode,
  TableDataModeChangeDetail,
  TableGroup,
  TableGroupCollapseChangeDetail,
  TableGroupLoadMoreDetail,
  TableGroupingState,
  TableLoadMoreDetail,
  TableLoadMoreMode,
  TablePaginationState,
  TableRow,
  TableRowActivateDetail,
  TableSelectionChangeDetail,
  TableSelectionMode,
  TableSortChangeDetail,
  TableSortState,
} from './table-types';

const TABLE_FOOTER_SLOT_LEADING = 1;
const TABLE_FOOTER_SLOT_COPY = 2;
const TABLE_FOOTER_SLOT_TRAILING = 4;
const TABLE_NON_VIRTUAL_WINDOW_THRESHOLD = 50;

@Component({
  tag: 'ds-table',
  styleUrls: ['../../utils/focus-ring.css', '../../utils/interaction-fill.css', 'Table.css'],
  scoped: true,
})
export class Table {
  @Element() el!: HTMLElement;
  /** Stable column definitions. Assign through JavaScript. */
  @Prop() columns: TableColumn[] = [];
  /** Ungrouped row data. Ignored while grouping is active. Assign through JavaScript. */
  @Prop() rows: TableRow[] = [];
  /** One level of application-owned grouped data. Assign through JavaScript. */
  @Prop() groups: TableGroup[] = [];
  /** Controlled grouping column. Applications supply groups in their final fixed order. */
  @Prop() grouping: TableGroupingState | null = null;
  /** Controlled member-row sort state. */
  @Prop() sort: TableSortState | null = null;
  /** Controlled collapsed group identities. Groups not listed remain expanded. */
  @Prop() collapsedGroupIds: string[] = [];
  /** Literal terms to highlight in table-owned text cells. Applications still own filtering. */
  @Prop() highlightTerms: string[] = [];
  /** Optional TableSearch field identities that restrict which data-point tracks are highlighted. */
  @Prop() highlightFieldIds: string[] = [];

  /** Required accessible table name, retained as a native caption. */
  @Prop() caption!: string;
  /** Shows a matching presentational title bar above the native table frame. */
  @Prop() captionVisibility: TableCaptionVisibility = 'hidden';
  /**
   * Opt in to the table-owned column customizer. The `columns` prop remains the
   * catalog; hidden and ordered columns are controlled separately. The trigger
   * opens the shared Menu of live show/hide switch rows.
   */
  @Prop() columnCustomizer: boolean = false;
  /** Controlled hidden data-column identities. Action ids are ignored. */
  @Prop() hiddenColumnIds: string[] = [];
  /** Controlled data-column identities in display order. Omitted ids append in catalog order. */
  @Prop() columnOrder: string[] = [];
  /**
   * Optional result summary footer. When both `displayedCount` and `totalCount`
   * are finite numbers, infinite mode shows “Displaying {displayed} of {total}”.
   * Virtual mode ignores `displayedCount` and derives its total from the
   * complete supplied rows; a mismatched `totalCount` emits a warning.
   */
  @Prop() displayedCount: number | undefined;
  @Prop() totalCount: number | undefined;
  /** Supports {displayed} and {total} placeholders. */
  @Prop() resultSummaryLabel: string = 'Displaying {displayed} of {total}';
  /** Supports the {total} placeholder. Used when dataMode is virtual. */
  @Prop() resultTotalSummaryLabel: string = TABLE_VIRTUAL_TOTAL_SUMMARY_LABEL;
  @Prop() stickyHeader: boolean = false;
  /** Maximum scroll-region height. Numbers resolve to CSS pixels. */
  @Prop() maxHeight: string | number | undefined;
  /** Fixed height for the complete header, table frame, and footer composition. */
  @Prop() height: string | number | undefined;
  /** Fit the complete table composition to its nearest vertical scrollport. */
  @Prop() fitViewport: boolean = false;
  /** Reserved space above a viewport-fitted table once surrounding chrome is compact. */
  @Prop() viewportInsetBlockStart: string | number = 0;
  /** Reserved space below a viewport-fitted table. */
  @Prop() viewportInsetBlockEnd: string | number = 0;
  /** Optional explicit label for the horizontal/vertical scroll region. */
  @Prop() scrollLabel: string | undefined;

  @Prop() selectionMode: TableSelectionMode = 'none';
  /** Controlled selected row identities. IDs outside the loaded rows are preserved. */
  @Prop() selectedRowIds: string[] = [];

  /** Initial loading state. Existing rows stay visible; incremental loading uses loadingMore. */
  @Prop() loading: boolean = false;
  /** Replace opted-in table-owned caption controls with same-size visual skeletons. */
  @Prop() chromeLoading: boolean = false;
  /** Initial-loading rows. Defaults to ten so bounded tables retain a useful filled viewport. */
  @Prop() skeletonRows: number = 10;
  @Prop() emptyHeading: string = 'No results';
  @Prop() emptyBody: string = 'No data is available.';
  /** Initial error state. Existing rows stay visible; incremental failures use loadMoreError. */
  @Prop() error: boolean = false;
  @Prop() errorHeading: string = 'Unable to load data';
  @Prop() errorBody: string = 'The data could not be loaded.';
  @Prop() emptyCellLabel: string = 'Not available';

  /** Top-level data-window strategy. Virtual mode recycles row DOM only. */
  @Prop() dataMode: TableDataMode = 'infinite';
  /** Opt in to the table-owned control for choosing between supported data modes. */
  @Prop() dataModeSwitcher: boolean = false;
  @Prop() dataModeSwitcherLabel: string = 'Change table variation';
  @Prop() dataModeMenuLabel: string = 'Table variation';
  @Prop() infiniteModeLabel: string = 'Infinite scroll';
  @Prop() paginationModeLabel: string = 'Pagination + Infinite groups';
  @Prop() virtualModeLabel: string = 'Virtual scroll';
  /** Controlled top-level pagination state. Required when dataMode is pagination. */
  @Prop() pagination: TablePaginationState | null = null;
  @Prop() loadMoreMode: TableLoadMoreMode = 'auto';
  @Prop() hasMore: boolean = false;
  @Prop() loadingMore: boolean = false;
  @Prop() loadMoreError: string | undefined;
  /** Reset key for a new query/group/sort dataset. */
  @Prop() loadIdentity: string | number = 'default';
  /** IntersectionObserver root margin in CSS pixels. */
  @Prop() loadMoreThreshold: number = 0;
  @Prop() loadMoreLabel: string = 'Load more';
  @Prop() retryLabel: string = 'Retry';
  @Prop() loadingMoreLabel: string = 'Loading more items';
  @Prop() endOfResultsLabel: string = 'All results loaded';
  /** Supports {count} and {total} placeholders. */
  @Prop() rowsLoadedLabel: string = '{count} more rows loaded. {total} rows loaded.';
  @Prop() groupLoadMoreLabel: string = 'Load more';
  /** Supports the {group} placeholder. */
  @Prop() groupLoadMoreAriaLabel: string = 'Load more {group} results';
  /** Supports the {group} placeholder. */
  @Prop() groupRetryLabel: string = 'Retry loading {group} results';
  /** Supports the {group} placeholder. */
  @Prop() groupLoadingMoreLabel: string = 'Loading more items';
  /** Supports the {group} placeholder. */
  @Prop() groupEndOfResultsLabel: string = 'All {group} results loaded';
  /** Supports {group}, {count}, {loaded}, and {total} placeholders. */
  @Prop() groupRowsLoadedLabel: string =
    '{count} more rows loaded in {group}. {loaded} of {total} rows loaded.';

  @Event() dsSortChange!: EventEmitter<TableSortChangeDetail>;
  @Event() dsGroupCollapseChange!: EventEmitter<TableGroupCollapseChangeDetail>;
  @Event() dsSelectionChange!: EventEmitter<TableSelectionChangeDetail>;
  @Event() dsLoadMore!: EventEmitter<TableLoadMoreDetail>;
  @Event() dsGroupLoadMore!: EventEmitter<TableGroupLoadMoreDetail>;
  @Event() dsPaginationChange!: EventEmitter<PaginationChangeDetail>;
  @Event() dsCellAction!: EventEmitter<TableCellActionDetail>;
  @Event() dsRowActivate!: EventEmitter<TableRowActivateDetail>;
  @Event() dsColumnsConfigChange!: EventEmitter<TableColumnsConfigChangeDetail>;
  @Event() dsDataModeChange!: EventEmitter<TableDataModeChangeDetail>;

  @State() private overflowStart = false;
  @State() private overflowEnd = false;
  @State() private scrollable = false;
  @State() private announcement = '';
  @State() private activeStickyGroupId: string | null = null;
  @State() private viewportFitSettled = false;
  @State() private headerPresent = false;
  @State() private headerUsesToolbar = false;
  @State() private footerSlotPresence = 0;
  @State() private fitPageSize: number | undefined;
  @State() private actionMenu: { rowId: string; columnId: string } | null = null;
  @State() private actionMenuInitialFocusVisible = false;
  @State() private truncateTooltipLabel = '';
  @State() private captionCompact = false;
  @State() private columnCustomizerOpen = false;
  @State() private columnCustomizerInitialFocusVisible = false;
  @State() private dataModeSwitcherOpen = false;
  @State() private dataModeSwitcherInitialFocusVisible = false;
  @State() private virtualWindow: TableVirtualPlan | null = null;

  private readonly actionMenuElementId = nextTableActionMenuElementId();
  private readonly columnCustomizerElementId = nextTableColumnCustomizerElementId();
  private readonly dataModeSwitcherElementId = nextTableDataModeSwitcherElementId();
  private truncateTooltipEl?: HTMLDsTooltipElement;
  private truncateAnchor: HTMLElement | null = null;
  private truncateTooltipBound = false;
  private focusedRowId: string | null = null;
  private virtualItems: TableVirtualItem[] = [];
  private visibleColumnsCache: {
    columns: TableColumn[];
    columnCustomizer: boolean;
    hiddenColumnIds: string[];
    columnOrder: string[];
    value: TableColumn[];
  } | null = null;
  private renderModelCache: {
    columns: TableColumn[];
    rows: TableRow[];
    groups: TableGroup[];
    grouped: boolean;
    selectionMode: TableSelectionMode;
    selectedRowIds: string[];
    collapsedGroupIds: string[];
    virtualCounts: boolean;
    value: TableRenderModel;
  } | null = null;
  private highlightMatcherCache: {
    terms: string[];
    value: TableHighlightMatcher;
  } | null = null;
  private virtualItemsCache: {
    columns: TableColumn[];
    rows: TableRow[];
    groups: TableGroup[];
    grouped: boolean;
    collapsedGroupIds: string[];
  } | null = null;
  private rootEl: HTMLElement | null = null;
  private viewportEl: HTMLElement | null = null;
  private frameEl: HTMLElement | null = null;
  private interactiveHeadEl: HTMLTableSectionElement | null = null;
  private collapseAllOverlayEl: HTMLElement | null = null;
  private stickyHeaderTableEl: HTMLTableElement | null = null;
  private tableEl: HTMLTableElement | null = null;
  private sentinelEl: HTMLElement | null = null;
  private incrementalWindowActive = false;
  private readonly groupSentinelEls = new Map<string, HTMLElement>();
  private previousModelWarning = '';
  private modelWarningQueued = false;
  private initialModelWarningFrame: number | undefined;
  private hasLoaded = false;
  private renderedModel: TableRenderModel | null = null;
  private stickyGroupConnected = false;
  private headerSlotObserver: MutationObserver | null = null;
  private footerSlotObserver: MutationObserver | null = null;
  private captionCompactDisconnect: (() => void) | undefined;
  private fitResizeObserver: ResizeObserver | null = null;
  private fitObservedViewport: HTMLElement | null = null;
  private fitObservedTable: HTMLTableElement | null = null;
  private fitMeasurementPending = false;
  private readonly bodyRenderer = new TableBodyRenderer();
  private readonly layoutController = new TableLayoutController({
    elements: () => ({
      viewport: this.viewportEl,
      contentTable: this.tableEl,
      stickyHeaderTable: this.stickyHeaderTableEl,
      collapseAllOverlay: this.collapseAllOverlayEl,
      frame: this.frameEl,
      interactiveHead: this.interactiveHeadEl,
    }),
    mode: () => ({
      documentStickyHeader: this.documentStickyHeader,
      floatingCollapseAll: this.renderedModel?.collapseAllHost?.mode === 'floating',
      clampVerticalOverscroll: this.fitViewport && this.viewportFitSettled,
    }),
    verticalEdgeWheel: deltaY => this.viewportFitController.scrollOuterBy(deltaY),
    overflowChanged: state => {
      if (state.start !== this.overflowStart) this.overflowStart = state.start;
      if (state.end !== this.overflowEnd) this.overflowEnd = state.end;
      if (state.scrollable !== this.scrollable) this.scrollable = state.scrollable;
    },
  });
  private readonly loadController = new TableLoadController({
    state: () => ({
      lazyLoading: this.dataMode === 'infinite' && !this.grouped,
      loadMoreMode: this.loadMoreMode,
      hasMore: this.hasMore,
      loadingMore: this.loadingMore,
      loadMoreError: this.loadMoreError,
      loadIdentity: this.loadIdentity,
      loadMoreThreshold: this.loadMoreThreshold,
      containedScroll: this.containedScroll,
      loadingMoreLabel: this.loadingMoreLabel,
      endOfResultsLabel: this.endOfResultsLabel,
      rowsLoadedLabel: this.rowsLoadedLabel,
      loadedRowCount: this.currentLoadedRowCount(),
      viewport: this.viewportEl,
      sentinel: this.sentinelEl,
    }),
    announce: message => {
      this.announcement = message;
    },
    request: detail => {
      this.dsLoadMore.emit(detail);
    },
  });
  private readonly groupLoadController = new TableGroupLoadController({
    state: () => ({
      enabled: this.grouped && this.dataMode !== 'virtual',
      loadMoreMode: this.loadMoreMode,
      loadMoreThreshold: this.loadMoreThreshold,
      containedScroll: this.containedScroll,
      groups: this.groups,
      viewport: this.viewportEl,
      sentinels: this.groupSentinelEls,
      loadingMoreLabel: this.groupLoadingMoreLabel,
      endOfResultsLabel: this.groupEndOfResultsLabel,
      rowsLoadedLabel: this.groupRowsLoadedLabel,
    }),
    announce: message => {
      this.announcement = message;
    },
    request: detail => {
      this.dsGroupLoadMore.emit(detail);
    },
  });
  private readonly virtualController = new TableVirtualController({
    state: () => ({
      enabled: this.rowWindowingEnabled,
      items: this.virtualItems,
      pinnedRowIds: this.virtualPinnedRowIds(),
      viewport: this.viewportEl,
      viewportSize: this.estimateVirtualViewportSize(),
    }),
    windowChanged: plan => {
      this.virtualWindow = plan;
    },
  });
  private readonly viewportFitController = new TableViewportFitController({
    enabled: () => this.fitViewport,
    elements: () => ({ host: this.el, surface: this.rootEl }),
    insets: () => ({
      blockStart: this.viewportInsetBlockStart,
      blockEnd: this.viewportInsetBlockEnd,
    }),
    fitChanged: (metrics: TableViewportFitMetrics | null) => {
      const settled = metrics?.settled ?? false;
      if (settled !== this.viewportFitSettled) this.viewportFitSettled = settled;
    },
  });

  componentWillLoad(): void {
    // Reserve the final viewport-fit height before the first paint. The fitted
    // surface is connected after render, but the host can already resolve its
    // owning scrollport and prevent an initial auto-height frame.
    this.viewportFitController.connect();
    this.incrementalWindowActive = this.hasIncrementalState;
    this.syncHeaderSlotPresence();
    this.syncFooterSlotPresence();
    this.loadController.initialize();
    this.groupLoadController.initialize();
  }

  componentDidLoad(): void {
    this.hasLoaded = true;
    this.layoutController.connect();
    this.loadController.connect();
    this.groupLoadController.connect();
    this.virtualController.connect();
    this.viewportFitController.connect();
    this.syncStickyGroupConnection();
    this.connectHeaderSlotObserver();
    this.connectFooterSlotObserver();
    this.connectFitObserver();
    this.connectCaptionCompactObserver();
    this.syncFitPageSize();
    this.connectTruncateTooltip();
    this.scheduleInitialModelIssueWarning();
  }

  componentDidRender(): void {
    this.layoutController.refresh(false);
    this.loadController.refresh();
    this.groupLoadController.refresh();
    this.virtualController.refresh();
    this.virtualController.collectMeasurements(this.tableEl);
    if (
      this.rowWindowingEnabled &&
      this.truncateAnchor &&
      this.tableEl &&
      !this.tableEl.contains(this.truncateAnchor)
    ) {
      this.dismissTruncateTooltip();
    }
    this.viewportFitController.refresh(false);
    this.syncStickyGroupConnection();
    this.connectFitObserver();
    this.connectCaptionCompactObserver();
    this.syncFitPageSize();
    if (this.stickyGroupConnected) this.updateStickyGroup();
  }

  connectedCallback(): void {
    if (!this.hasLoaded) return;
    this.layoutController.connect();
    this.loadController.connect();
    this.groupLoadController.connect();
    this.virtualController.connect();
    this.viewportFitController.connect();
    this.syncStickyGroupConnection();
    this.connectHeaderSlotObserver();
    this.connectFooterSlotObserver();
    this.connectFitObserver();
    this.connectCaptionCompactObserver();
    this.connectTruncateTooltip();
  }

  disconnectedCallback(): void {
    this.layoutController.disconnect();
    this.loadController.disconnect();
    this.groupLoadController.disconnect();
    this.virtualController.disconnect();
    this.viewportFitController.disconnect();
    this.disconnectStickyGroup();
    this.headerSlotObserver?.disconnect();
    this.headerSlotObserver = null;
    this.footerSlotObserver?.disconnect();
    this.footerSlotObserver = null;
    this.disconnectFitObserver();
    this.disconnectCaptionCompactObserver();
    this.disconnectTruncateTooltip();
    this.closeColumnCustomizer();
    if (this.initialModelWarningFrame !== undefined) {
      cancelAnimationFrame(this.initialModelWarningFrame);
      this.initialModelWarningFrame = undefined;
    }
  }

  private syncHeaderSlotPresence = () => {
    const header = this.el.querySelector<HTMLElement>('[slot="header"]');
    this.headerPresent = !!header;
    this.headerUsesToolbar = header?.tagName === 'DS-TABLE-TOOLBAR';
  };

  private connectHeaderSlotObserver(): void {
    if (this.headerSlotObserver || typeof MutationObserver === 'undefined') return;
    this.headerSlotObserver = new MutationObserver(this.syncHeaderSlotPresence);
    this.headerSlotObserver.observe(this.el, { childList: true });
    this.syncHeaderSlotPresence();
  }

  private syncFooterSlotPresence = () => {
    let presence = 0;
    if (hasOwnedTableFooterSlot(this.el, 'footer-leading')) presence |= TABLE_FOOTER_SLOT_LEADING;
    if (hasOwnedTableFooterSlot(this.el, 'footer')) presence |= TABLE_FOOTER_SLOT_COPY;
    if (hasOwnedTableFooterSlot(this.el, 'footer-trailing')) presence |= TABLE_FOOTER_SLOT_TRAILING;
    if (presence !== this.footerSlotPresence) this.footerSlotPresence = presence;
  };

  private connectFooterSlotObserver(): void {
    if (this.footerSlotObserver || typeof MutationObserver === 'undefined') return;
    this.footerSlotObserver = new MutationObserver(this.syncFooterSlotPresence);
    this.footerSlotObserver.observe(this.el, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['slot'],
    });
    this.syncFooterSlotPresence();
  }

  private connectStickyGroup(): void {
    if (this.stickyGroupConnected || typeof window === 'undefined') return;
    this.stickyGroupConnected = true;
    document.addEventListener('scroll', this.updateStickyGroup, {
      capture: true,
      passive: true,
    });
    window.addEventListener('resize', this.updateStickyGroup, { passive: true });
    this.updateStickyGroup();
  }

  private syncStickyGroupConnection(): void {
    if (this.documentStickyHeader && this.grouped) {
      this.connectStickyGroup();
      return;
    }

    this.disconnectStickyGroup();
    this.frameEl?.style.removeProperty('--_table-sticky-group-top');
    if (this.activeStickyGroupId !== null) {
      this.activeStickyGroupId = null;
    }
  }

  private disconnectStickyGroup(): void {
    if (!this.stickyGroupConnected || typeof window === 'undefined') return;
    this.stickyGroupConnected = false;
    document.removeEventListener('scroll', this.updateStickyGroup, true);
    window.removeEventListener('resize', this.updateStickyGroup);
  }

  private readonly updateStickyGroup = (): void => {
    if (!this.documentStickyHeader || !this.grouped || !this.frameEl || !this.tableEl) {
      if (this.activeStickyGroupId !== null) this.activeStickyGroupId = null;
      return;
    }

    const stickyHeader = this.frameEl.querySelector<HTMLElement>(
      '.ds-table__document-sticky-header'
    );
    if (!stickyHeader) return;
    const threshold = stickyHeader.getBoundingClientRect().bottom;
    let activeGroupId: string | null = null;
    let activeGroupTop = threshold;
    for (const body of this.tableEl.querySelectorAll<HTMLElement>('tbody[data-group-id]')) {
      const source = body.querySelector<HTMLElement>('.ds-table__group-cell');
      if (!source) continue;
      const sourceRect = source.getBoundingClientRect();
      const bodyRect = body.getBoundingClientRect();
      if (sourceRect.top <= threshold && bodyRect.bottom > threshold) {
        activeGroupId = body.dataset.groupId ?? null;
        // A sticky section is bounded by its own row group. As that boundary
        // approaches the sticky lane, move the outgoing section bar with it so
        // the incoming source bar pushes it away instead of rendering beneath it.
        activeGroupTop = Math.min(threshold, bodyRect.bottom - sourceRect.height);
      }
    }

    const frameRect = this.frameEl.getBoundingClientRect();
    this.frameEl.style.setProperty(
      '--_table-sticky-group-top',
      `${activeGroupTop - frameRect.top}px`
    );

    if (activeGroupId !== this.activeStickyGroupId) {
      this.activeStickyGroupId = activeGroupId;
      return;
    }
  };

  @Watch('columns')
  @Watch('grouping')
  @Watch('hiddenColumnIds')
  @Watch('columnOrder')
  @Watch('columnCustomizer')
  handleStructureChange(): void {
    this.scheduleModelIssueWarning();
    this.loadController.structureChanged();
    this.groupLoadController.structureChanged();
    this.virtualController.invalidateMeasures();
  }

  @Watch('rows')
  @Watch('groups')
  handleDataChange(): void {
    if (this.grouped) this.groupLoadController.dataChanged();
    else this.loadController.dataChanged();
    this.scheduleModelIssueWarning();
    this.syncActionMenu();
    this.virtualController.invalidateMeasures();
  }

  @Watch('totalCount')
  handleTotalCountChange(): void {
    this.scheduleModelIssueWarning();
  }

  @Watch('caption')
  handleCaptionChange(): void {
    this.scheduleModelIssueWarning();
  }

  @Watch('loadIdentity')
  handleLoadIdentityChange(): void {
    this.incrementalWindowActive = this.hasIncrementalState;
    this.loadController.identityChanged();
    this.virtualController.resetToTop();
  }

  @Watch('sort')
  @Watch('grouping')
  handleVirtualIndexReset(): void {
    this.virtualController.resetToTop();
  }

  @Watch('loadMoreMode')
  @Watch('loadMoreThreshold')
  handleLazyConfigurationChange(): void {
    this.loadController.configurationChanged();
    this.groupLoadController.configurationChanged();
  }

  @Watch('dataMode')
  handleDataModeChange(): void {
    this.incrementalWindowActive = this.hasIncrementalState;
    this.scheduleModelIssueWarning();
    this.handleLazyConfigurationChange();
    this.virtualController.resetToTop();
  }

  @Watch('pagination')
  handlePaginationChange(
    pagination: TablePaginationState | null,
    previous: TablePaginationState | null
  ): void {
    if (pagination?.pageSizeMode === 'fit' && pagination.fitIdentity !== previous?.fitIdentity) {
      this.fitMeasurementPending = true;
    }
  }

  @Watch('loadingMore')
  handleLoadingMoreChange(loading: boolean): void {
    if (loading) this.incrementalWindowActive = true;
    if (!this.grouped) this.loadController.loadingChanged(loading);
  }

  @Watch('loadMoreError')
  handleLoadMoreErrorChange(error: string | undefined): void {
    if (error?.trim()) this.incrementalWindowActive = true;
    if (!this.grouped) this.loadController.errorChanged(error);
  }

  @Watch('hasMore')
  handleHasMoreChange(hasMore: boolean, hadMore: boolean): void {
    if (hasMore) this.incrementalWindowActive = true;
    if (!this.grouped) this.loadController.hasMoreChanged(hasMore, hadMore);
  }

  @Watch('columnCustomizer')
  @Watch('captionVisibility')
  handleColumnCustomizerAvailability(): void {
    if (!this.showsColumnCustomizer) this.closeColumnCustomizer();
  }

  @Watch('dataModeSwitcher')
  @Watch('captionVisibility')
  handleDataModeSwitcherAvailability(): void {
    if (!this.showsDataModeSwitcher) this.closeDataModeSwitcher();
  }

  @Watch('chromeLoading')
  handleChromeLoadingChange(loading: boolean): void {
    if (!loading) return;
    this.closeColumnCustomizer();
    this.closeDataModeSwitcher();
  }

  private get grouped(): boolean {
    return this.grouping !== null;
  }

  private get hasIncrementalState(): boolean {
    return (
      this.dataMode === 'infinite' &&
      (this.hasMore || this.loadingMore || !!this.loadMoreError?.trim())
    );
  }

  private get selectable(): boolean {
    return this.selectionMode === 'multiple';
  }

  private get visibleColumns(): TableColumn[] {
    const cached = this.visibleColumnsCache;
    if (
      cached &&
      cached.columns === this.columns &&
      cached.columnCustomizer === this.columnCustomizer &&
      cached.hiddenColumnIds === this.hiddenColumnIds &&
      cached.columnOrder === this.columnOrder
    ) {
      return cached.value;
    }
    const value = resolveTableVisibleColumns(this.columns, {
      columnCustomizer: this.columnCustomizer,
      hiddenColumnIds: this.hiddenColumnIds,
      columnOrder: this.columnOrder,
    });
    this.visibleColumnsCache = {
      columns: this.columns,
      columnCustomizer: this.columnCustomizer,
      hiddenColumnIds: this.hiddenColumnIds,
      columnOrder: this.columnOrder,
      value,
    };
    return value;
  }

  private get showsColumnCustomizer(): boolean {
    return this.columnCustomizer && this.captionVisibility === 'visible';
  }

  private get showsDataModeSwitcher(): boolean {
    return this.dataModeSwitcher && this.captionVisibility === 'visible';
  }

  private get showsCaptionTrailing(): boolean {
    return this.showsDataModeSwitcher || this.showsColumnCustomizer;
  }

  private get documentStickyHeader(): boolean {
    return this.stickyHeader && !this.containedScroll;
  }

  private get fixedHeight(): boolean {
    return !this.fitViewport && this.resolvedHeight !== undefined;
  }

  private get boundedComposition(): boolean {
    return this.fitViewport || this.fixedHeight;
  }

  private get containedScroll(): boolean {
    return this.boundedComposition || this.resolvedMaxHeight !== undefined;
  }

  private connectFitObserver(): void {
    if (typeof ResizeObserver === 'undefined') return;
    if (this.fitObservedViewport === this.viewportEl && this.fitObservedTable === this.tableEl) {
      return;
    }
    this.disconnectFitObserver();
    this.fitObservedViewport = this.viewportEl;
    this.fitObservedTable = this.tableEl;
    this.fitResizeObserver = new ResizeObserver(this.syncFitPageSize);
    if (this.fitObservedViewport) this.fitResizeObserver.observe(this.fitObservedViewport);
    if (this.fitObservedTable) this.fitResizeObserver.observe(this.fitObservedTable);
  }

  private disconnectFitObserver(): void {
    this.fitResizeObserver?.disconnect();
    this.fitResizeObserver = null;
    this.fitObservedViewport = null;
    this.fitObservedTable = null;
  }

  private connectCaptionCompactObserver(): void {
    if (this.captionCompactDisconnect) return;
    this.captionCompactDisconnect = observeTableCaptionCompact(this.el, compact => {
      if (this.captionCompact !== compact) this.captionCompact = compact;
    });
  }

  private disconnectCaptionCompactObserver(): void {
    this.captionCompactDisconnect?.();
    this.captionCompactDisconnect = undefined;
  }

  private readonly syncFitPageSize = (): void => {
    const pagination = this.dataMode === 'pagination' ? this.pagination : null;
    if (
      !pagination?.fitToPage ||
      pagination.fitToPageInactive ||
      !this.containedScroll ||
      !this.viewportEl ||
      !this.tableEl
    ) {
      if (this.fitPageSize !== undefined) this.fitPageSize = undefined;
      this.fitMeasurementPending = false;
      return;
    }
    const header = this.tableEl.querySelector<HTMLElement>('.ds-table__head .ds-table__header-row');
    const item = this.tableEl.querySelector<HTMLElement>(
      this.grouped ? '.ds-table__group-row' : '.ds-table__body .ds-table__row'
    );
    const itemBlockSize =
      item?.getBoundingClientRect().height ||
      resolveCssLengthPx(
        'var(--ds-table-row-min-block-size, var(--dimension-size-500))',
        0,
        this.rootEl ?? this.el
      );
    const next = resolveTableFitPageSize({
      viewportBlockSize: this.viewportEl.clientHeight,
      headerBlockSize: header?.getBoundingClientRect().height ?? 0,
      itemBlockSize,
    });
    if (next !== this.fitPageSize) this.fitPageSize = next;
    if (!this.fitMeasurementPending || pagination.pageSizeMode !== 'fit' || next === undefined) {
      return;
    }
    this.fitMeasurementPending = false;
    if (next === pagination.pageSize && pagination.pageIndex === 0) return;
    this.dsPaginationChange.emit({
      pageIndex: 0,
      pageSize: next,
      pageSizeMode: 'fit',
      totalItems: pagination.totalItems,
      pageSizeOptions: pagination.pageSizeOptions ?? [25, 50, 100, 200],
      fitToPage: true,
      fitToPageInactive: false,
      fitPageSize: next,
      fitPageSizeLabel: pagination.fitPageSizeLabel ?? 'Fit to page',
      fitPageSizeTriggerLabel: pagination.fitPageSizeTriggerLabel ?? 'Fit',
      itemLabel: pagination.itemLabel ?? 'items',
      pageSizeLabel: pagination.pageSizeLabel ?? 'Items',
      ariaLabel: pagination.ariaLabel ?? `${this.caption} pagination`,
      showFirstLastButtons: pagination.showFirstLastButtons ?? false,
      previousPageIndex: pagination.pageIndex,
      previousPageSize: pagination.pageSize,
      previousPageSizeMode: 'fit',
      reason: 'fit',
    });
  };

  @Listen('keydown', { target: 'window' })
  handleWindowPaginationKeyDown(event: KeyboardEvent): void {
    this.handlePaginationKeyDown(event, true);
  }

  private handlePaginationKeyDown(event: KeyboardEvent, fromWindow = false): void {
    const pagination = this.dataMode === 'pagination' ? this.pagination : null;
    if (
      !pagination ||
      this.loading ||
      event.defaultPrevented ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey ||
      (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight')
    ) {
      return;
    }

    if (paginationShortcutBlockedByPath(event.composedPath())) return;

    if (fromWindow) {
      const origin = event.composedPath()[0];
      const originNode = origin instanceof Text ? origin.parentNode : origin;
      if (
        !shouldHandleContainingPagePaginationShortcut({
          origin: originNode,
          table: this.el,
          eventPath: event.composedPath(),
        })
      ) {
        return;
      }
    }

    const state = resolvePaginationState(pagination);
    const pageIndex = event.key === 'ArrowLeft' ? state.pageIndex - 1 : state.pageIndex + 1;
    if (pageIndex < 0 || pageIndex >= state.totalPages) return;

    event.preventDefault();
    this.dsPaginationChange.emit({
      pageIndex,
      pageSize: state.pageSize,
      pageSizeMode: state.pageSizeMode,
      totalItems: state.totalItems,
      pageSizeOptions: state.pageSizeOptions,
      fitToPage: pagination.fitToPage ?? false,
      fitToPageInactive: pagination.fitToPageInactive ?? false,
      fitPageSize: this.fitPageSize ?? pagination.fitPageSize,
      fitPageSizeLabel: pagination.fitPageSizeLabel ?? 'Fit to page',
      fitPageSizeTriggerLabel: pagination.fitPageSizeTriggerLabel ?? 'Fit',
      itemLabel: pagination.itemLabel ?? 'items',
      pageSizeLabel: pagination.pageSizeLabel ?? 'Items',
      ariaLabel: pagination.ariaLabel ?? `${this.caption} pagination`,
      showFirstLastButtons: pagination.showFirstLastButtons ?? false,
      previousPageIndex: state.pageIndex,
      previousPageSize: state.pageSize,
      previousPageSizeMode: state.pageSizeMode,
      reason: 'page',
    });
  }

  private currentLoadedRows(): TableRow[] {
    return tableRows(this.rows, this.groups, this.grouped);
  }

  private currentLoadedRowCount(): number {
    return this.grouped
      ? this.groups.reduce((count, group) => count + group.rows.length, 0)
      : this.rows.length;
  }

  private createRenderModel(): TableRenderModel {
    const columns = this.visibleColumns;
    const grouped = this.grouped;
    const virtualCounts = this.dataMode === 'virtual';
    const cached = this.renderModelCache;
    if (
      cached &&
      cached.columns === columns &&
      cached.rows === this.rows &&
      cached.groups === this.groups &&
      cached.grouped === grouped &&
      cached.selectionMode === this.selectionMode &&
      cached.selectedRowIds === this.selectedRowIds &&
      cached.collapsedGroupIds === this.collapsedGroupIds &&
      cached.virtualCounts === virtualCounts
    ) {
      return cached.value;
    }
    const value = createTableRenderModel({
      columns,
      rows: this.rows,
      groups: this.groups,
      grouped,
      selectionMode: this.selectionMode,
      selectedRowIds: this.selectedRowIds,
      collapsedGroupIds: this.collapsedGroupIds,
      groupCountPresentation: virtualCounts ? 'total' : 'loaded-progress',
    });
    this.renderModelCache = {
      columns,
      rows: this.rows,
      groups: this.groups,
      grouped,
      selectionMode: this.selectionMode,
      selectedRowIds: this.selectedRowIds,
      collapsedGroupIds: this.collapsedGroupIds,
      virtualCounts,
      value,
    };
    return value;
  }

  private get highlightMatcher(): TableHighlightMatcher {
    if (this.highlightMatcherCache?.terms === this.highlightTerms) {
      return this.highlightMatcherCache.value;
    }
    const value = createTableHighlightMatcher(this.highlightTerms);
    this.highlightMatcherCache = { terms: this.highlightTerms, value };
    return value;
  }

  private get rowWindowingEnabled(): boolean {
    if (!this.hasVirtualViewportBounds) return false;
    if (this.dataMode === 'virtual') return true;
    return !this.grouped && this.currentLoadedRowCount() > TABLE_NON_VIRTUAL_WINDOW_THRESHOLD;
  }

  private get virtualViewportMissing(): boolean {
    return this.dataMode === 'virtual' && !this.hasVirtualViewportBounds;
  }

  private get hasVirtualViewportBounds(): boolean {
    return this.containedScroll && this.estimateVirtualViewportSize() > 0;
  }

  private estimateVirtualViewportSize(): number {
    const measured =
      this.virtualController.currentViewportSize() || this.viewportEl?.clientHeight || 0;
    const chrome =
      (this.captionVisibility === 'visible' ? 48 : 0) + (this.hasResultFooter ? 48 : 0);
    if (this.fixedHeight && this.resolvedHeight) {
      if (measured > 0) return measured;
      return Math.max(
        0,
        resolveCssLengthPx(this.resolvedHeight, 0, this.rootEl ?? this.el) - chrome
      );
    }
    if (this.fitViewport) return Math.max(0, measured);
    if (this.resolvedMaxHeight) {
      if (this.resolvedMaxHeight.trim().toLowerCase() === 'none') return 0;
      return resolveCssLengthPx(this.resolvedMaxHeight, 0, this.rootEl ?? this.el);
    }
    return 0;
  }

  private virtualPinnedRowIds(): Set<string> {
    const pinned = new Set<string>();
    if (this.focusedRowId) pinned.add(this.focusedRowId);
    if (this.actionMenu?.rowId) pinned.add(this.actionMenu.rowId);
    return pinned;
  }

  private syncVirtualItems(model: TableRenderModel): void {
    if (!this.rowWindowingEnabled) {
      this.virtualItems = [];
      this.virtualItemsCache = null;
      this.bodyRenderer.resetVirtualState();
      return;
    }
    const columns = this.visibleColumns;
    const cached = this.virtualItemsCache;
    if (
      cached &&
      cached.columns === columns &&
      cached.rows === this.rows &&
      cached.groups === this.groups &&
      cached.grouped === model.grouped &&
      cached.collapsedGroupIds === this.collapsedGroupIds
    ) {
      return;
    }
    this.virtualItems = flattenTableVirtualItems({
      grouped: model.grouped,
      rows: this.rows,
      groups: this.groups,
      collapsedGroupIds: this.collapsedGroupIds,
      columns,
    });
    this.virtualItemsCache = {
      columns,
      rows: this.rows,
      groups: this.groups,
      grouped: model.grouped,
      collapsedGroupIds: this.collapsedGroupIds,
    };
  }

  private shouldWindowRows(model: TableRenderModel): boolean {
    return (
      this.rowWindowingEnabled && (model.hasData || (model.grouped && model.groups.length > 0))
    );
  }

  private get resolvedMaxHeight(): string | undefined {
    if (this.maxHeight == null || this.maxHeight === '') return undefined;
    return typeof this.maxHeight === 'number' ? `${Math.max(0, this.maxHeight)}px` : this.maxHeight;
  }

  private get resolvedHeight(): string | undefined {
    if (this.height == null || this.height === '') return undefined;
    return typeof this.height === 'number' ? `${Math.max(0, this.height)}px` : this.height;
  }

  private warnModelIssues(): void {
    const issues = tableModelIssues(this.columns, this.rows, this.groups, this.grouped);
    const visibleColumns = this.visibleColumns;
    if (!this.caption?.trim()) issues.unshift('A non-empty caption is required.');
    if (this.grouping) {
      const groupingColumn = this.columns.find(column => column.id === this.grouping!.columnId);
      if (!groupingColumn) {
        issues.push(`Grouping references unknown column id: ${this.grouping.columnId}`);
      } else if (!visibleColumns.some(column => column.id === groupingColumn.id)) {
        issues.push(`Grouping references hidden column id: ${this.grouping.columnId}`);
      }
    }
    if (this.sort) {
      const sortColumn = this.columns.find(
        column =>
          column.id === this.sort!.columnId ||
          column.headerSegments?.some(segment => segment.sortKey === this.sort!.columnId)
      );
      if (!sortColumn) {
        issues.push(`Sorting references unknown column id: ${this.sort.columnId}`);
      } else if (!visibleColumns.some(column => column.id === sortColumn.id)) {
        issues.push(`Sorting references hidden column id: ${this.sort.columnId}`);
      }
    }
    if (
      this.dataMode === 'virtual' &&
      Number.isFinite(this.totalCount) &&
      Math.max(0, Math.trunc(this.totalCount!)) !== this.currentLoadedRowCount()
    ) {
      issues.push('Virtual mode requires totalCount to match the complete supplied row count.');
    }
    const stickyStart = visibleColumns.filter(column => column.sticky === 'start');
    const stickyEnd = visibleColumns.filter(column => column.sticky === 'end');
    if (stickyStart.length > 1 || (this.selectable && stickyStart.length > 0)) {
      issues.push(
        'Only one sticky start column is supported, and row selection already owns that lane.'
      );
    }
    if (stickyEnd.length > 1) issues.push('Only one sticky end column is supported.');
    for (const column of [...stickyStart, ...stickyEnd]) {
      if (!tableColumnSize(column))
        issues.push(`Sticky column ${column.id} requires an explicit size.`);
    }
    const message = issues.join(' ');
    if (!message) {
      this.previousModelWarning = '';
      return;
    }
    if (message === this.previousModelWarning) return;
    this.previousModelWarning = message;
    console.warn(`[ds-table] ${message}`);
  }

  private scheduleModelIssueWarning(): void {
    if (this.modelWarningQueued) return;
    this.modelWarningQueued = true;
    queueMicrotask(() => {
      this.modelWarningQueued = false;
      this.warnModelIssues();
    });
  }

  private scheduleInitialModelIssueWarning(): void {
    if (this.initialModelWarningFrame !== undefined) {
      cancelAnimationFrame(this.initialModelWarningFrame);
    }
    this.initialModelWarningFrame = requestAnimationFrame(() => {
      this.initialModelWarningFrame = undefined;
      this.warnModelIssues();
    });
  }

  private emitSort(column: TableColumn, sortKey = column.id): void {
    if (!column.sortable) return;
    this.dsSortChange.emit({ sort: nextTableSortState(this.sort, sortKey) });
  }

  private sortButtonLabel(column: TableColumn, sortKey = column.id, label = column.header): string {
    if (this.sort?.columnId !== sortKey) return `Sort ${label} ascending`;
    if (this.sort.direction === 'asc') return `Sort ${label} descending. Currently ascending.`;
    return `Sort ${label} ascending. Currently descending.`;
  }

  private emitRowSelection(row: TableRow): void {
    const next = toggleTableRowSelection(this.selectedRowIds, row);
    const selected = next.includes(row.id);
    this.dsSelectionChange.emit({
      selectedRowIds: next,
      scope: 'row',
      changedRowId: row.id,
      selected,
    });
  }

  private emitAllSelection(): void {
    const loadedRows = this.currentLoadedRows();
    const selection = deriveTableSelectionState(loadedRows, this.selectedRowIds);
    this.dsSelectionChange.emit({
      selectedRowIds: toggleAllLoadedTableRows(this.selectedRowIds, loadedRows),
      scope: 'all-loaded',
      selected: !selection.allSelected,
    });
  }

  private emitGroupSelection(group: TableGroup): void {
    const state = deriveTableSelectionState(group.rows, this.selectedRowIds);
    this.dsSelectionChange.emit({
      selectedRowIds: toggleTableGroupSelection(this.selectedRowIds, group.rows),
      scope: 'group',
      groupId: group.id,
      selected: !state.allSelected,
    });
  }

  private rowEventOwnsActivation(event: Event): boolean {
    const currentTarget = event.currentTarget;
    return !event.composedPath().some(target => {
      if (!(target instanceof HTMLElement) || target === currentTarget) return false;
      return target.matches(
        'button, a, input, select, textarea, [role="button"], [role="checkbox"], [popover], ds-button-unfilled, ds-menu'
      );
    });
  }

  private groupRowEventOwnsCollapse(event: Event): boolean {
    const currentTarget = event.currentTarget;
    return !event.composedPath().some(target => {
      if (!(target instanceof HTMLElement) || target === currentTarget) return false;
      return target.matches(
        'input, select, textarea, [role="checkbox"], .ds-table__selection-control, .ds-table__group-selection'
      );
    });
  }

  private handleGroupRowClick(group: TableGroup, event: Event): void {
    if (!this.groupRowEventOwnsCollapse(event)) return;
    this.emitGroupCollapse(group);
  }

  private emitRowActivation(row: TableRow, event: Event): void {
    if (!row.interactive || row.disabled || !this.rowEventOwnsActivation(event)) return;
    this.dsRowActivate.emit({ rowId: row.id });
  }

  private syncActionMenu(): void {
    if (!this.actionMenu) return;
    const row = tableRows(this.rows, this.groups, this.grouped).find(
      candidate => candidate.id === this.actionMenu?.rowId
    );
    const value = row && !row.disabled ? row.cells[this.actionMenu.columnId] : undefined;
    if (!isTableCellAction(value) || !isRenderableTableActionMenu(value)) {
      this.actionMenu = null;
    }
  }

  private closeActionMenu(): void {
    this.actionMenu = null;
  }

  private handleActionMenuSelect(item: MenuItemData): void {
    const open = this.actionMenu;
    const actionId = item.value;
    if (!open || !actionId || item.isInactive) return;
    this.dsCellAction.emit({
      actionId,
      rowId: open.rowId,
      columnId: open.columnId,
    });
    const triggerId = tableActionTriggerId(this.actionMenuElementId, open.rowId, open.columnId);
    this.closeActionMenu();
    requestAnimationFrame(() => {
      const trigger = this.el.querySelector<HTMLElement & { setFocus?: () => void }>(
        `#${CSS.escape(triggerId)}`
      );
      trigger?.setFocus?.();
    });
  }

  private toggleActionMenu(row: TableRow, column: TableColumn, event: MouseEvent): void {
    if (row.disabled) return;
    const open = this.actionMenu?.rowId === row.id && this.actionMenu?.columnId === column.id;
    this.actionMenuInitialFocusVisible = event.detail === 0;
    this.actionMenu = open ? null : { rowId: row.id, columnId: column.id };
  }

  private renderOverflowActionMenu() {
    const open = this.actionMenu;
    const row = open
      ? tableRows(this.rows, this.groups, this.grouped).find(
          candidate => candidate.id === open.rowId
        )
      : undefined;
    const value = row && open ? row.cells[open.columnId] : undefined;
    const menu = isTableCellAction(value) && isRenderableTableActionMenu(value) ? value : undefined;
    const sections = menu ? tableActionMenuSections(menu.items) : [];
    const triggerId = open
      ? tableActionTriggerId(this.actionMenuElementId, open.rowId, open.columnId)
      : undefined;

    return (
      <ds-menu
        id={this.actionMenuElementId}
        open={Boolean(open && sections.length)}
        anchorId={triggerId}
        align="end"
        side="bottom"
        menuLabel={menu?.ariaLabel ?? 'More actions'}
        initialFocusVisible={this.actionMenuInitialFocusVisible}
        sections={sections}
        onDsClose={() => this.closeActionMenu()}
        onDsSelect={event => this.handleActionMenuSelect(event.detail)}
      />
    );
  }

  private connectTruncateTooltip(): void {
    if (this.truncateTooltipBound) return;
    this.el.addEventListener('pointerover', this.onTruncatePointerOver);
    this.el.addEventListener('pointerout', this.onTruncatePointerOut);
    this.el.addEventListener('focusin', this.onTruncateFocusIn);
    this.el.addEventListener('focusout', this.onTruncateFocusOut);
    this.truncateTooltipBound = true;
  }

  private disconnectTruncateTooltip(): void {
    if (!this.truncateTooltipBound) return;
    this.el.removeEventListener('pointerover', this.onTruncatePointerOver);
    this.el.removeEventListener('pointerout', this.onTruncatePointerOut);
    this.el.removeEventListener('focusin', this.onTruncateFocusIn);
    this.el.removeEventListener('focusout', this.onTruncateFocusOut);
    this.truncateTooltipBound = false;
    this.dismissTruncateTooltip();
  }

  private onTruncatePointerOver = (event: PointerEvent) => {
    if (event.pointerType === 'touch') return;
    const track = resolveTableTruncateTrack(event.target);
    if (!track) return;
    this.presentOrDismissTruncateTrack(track);
  };

  private onTruncatePointerOut = (event: PointerEvent) => {
    if (event.pointerType === 'touch') return;
    if (resolveTableTruncateTrack(event.relatedTarget)) return;
    const next = event.relatedTarget;
    const cell = this.truncateAnchor?.closest('.ds-table__cell');
    if (cell && next instanceof Node && cell.contains(next)) return;
    this.dismissTruncateTooltip();
  };

  private onTruncateFocusIn = (event: FocusEvent) => {
    const track = resolveTableTruncateTrack(event.target);
    if (!track) {
      this.dismissTruncateTooltip();
      return;
    }
    this.presentOrDismissTruncateTrack(track);
  };

  private onTruncateFocusOut = (event: FocusEvent) => {
    if (resolveTableTruncateTrack(event.relatedTarget)) return;
    this.dismissTruncateTooltip();
  };

  private presentOrDismissTruncateTrack(track: HTMLElement): void {
    if (!isElementTruncated(track)) {
      this.dismissTruncateTooltip();
      return;
    }
    const label = tableTruncateLabel(track);
    if (!label) {
      this.dismissTruncateTooltip();
      return;
    }
    this.truncateAnchor = track;
    this.truncateTooltipLabel = label;
    void this.truncateTooltipEl?.presentFrom(track, label);
  }

  private dismissTruncateTooltip(): void {
    this.truncateAnchor = null;
    if (!this.truncateTooltipLabel && !this.truncateTooltipEl) return;
    this.truncateTooltipLabel = '';
    void this.truncateTooltipEl?.dismiss();
  }

  private renderTruncateTooltip() {
    return (
      <ds-tooltip
        ref={element => {
          this.truncateTooltipEl = element;
        }}
        label={this.truncateTooltipLabel}
        describedBy={false}
        wrapLabel={true}
        size="sm"
        delay={0}
        side="top"
      />
    );
  }

  private handleRowKeydown(row: TableRow, event: KeyboardEvent): void {
    if (event.target !== event.currentTarget || (event.key !== 'Enter' && event.key !== ' '))
      return;
    event.preventDefault();
    this.emitRowActivation(row, event);
  }

  private onVirtualFocusIn = (event: FocusEvent): void => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) return;
    const row = target.closest('[data-row-id]');
    const id = row?.getAttribute('data-row-id') ?? null;
    if (id === this.focusedRowId) return;
    this.focusedRowId = id;
    if (this.rowWindowingEnabled) this.virtualController.schedule();
  };

  private renderSelectionControl(
    label: string,
    checked: boolean,
    indeterminate: boolean,
    disabled: boolean,
    onActivate: () => void
  ) {
    return (
      <button
        class="ds-table__selection-control ds-focus-ring ds-interaction-fill__content"
        type="button"
        role="checkbox"
        aria-label={label}
        aria-checked={indeterminate ? 'mixed' : String(checked)}
        disabled={disabled}
        onClick={onActivate}
      >
        <ds-checkbox
          label=""
          size="md"
          checked={checked}
          indeterminate={indeterminate}
          presentation={true}
        />
      </button>
    );
  }

  private renderStickyEdge(sticky: TableColumn['sticky']) {
    if (!sticky) return null;
    return (
      <span class={`ds-table__sticky-edge ds-table__sticky-edge--${sticky}`} aria-hidden="true" />
    );
  }

  private renderCollapseAllButton() {
    return (
      <ds-button-unfilled
        class="ds-table__collapse-all"
        variant="icon"
        icon="ChevronDownUp"
        size="xs"
        style={{ width: 'var(--dimension-size-300)' }}
        aria-label="Collapse all groups"
        hasBorder={false}
        activeFill={false}
        pressScale={false}
        onDsClick={event => {
          event.stopPropagation();
          this.emitAllGroupsCollapse();
        }}
      />
    );
  }

  private renderFloatingCollapseAll(model: TableRenderModel) {
    if (model.collapseAllHost?.mode !== 'floating') return null;
    return (
      <span
        class="ds-table__collapse-all-overlay"
        ref={element => {
          this.collapseAllOverlayEl = element ?? null;
        }}
      >
        <span class="ds-table__collapse-all-surface ds-control-elevation ds-control-elevation--md">
          {this.renderCollapseAllButton()}
        </span>
      </span>
    );
  }

  private renderColumnHeader(
    column: TableColumn,
    model: TableRenderModel,
    interactive = true,
    presentational = false
  ) {
    const groupedColumn = this.grouping?.columnId === column.id;
    const headerSegments = column.headerSegments?.length
      ? column.headerSegments
      : [{ label: column.header, sortKey: column.id }];
    const activeMemberSegment = headerSegments.find(
      segment => segment.sortKey === this.sort?.columnId
    );
    const activeMemberSort = !!activeMemberSegment;
    const activeSort = activeMemberSort;
    const align = column.align ?? 'start';
    const direction = activeMemberSort ? this.sort!.direction : undefined;
    const memberAriaSort = activeMemberSort
      ? this.sort!.direction === 'asc'
        ? 'ascending'
        : 'descending'
      : undefined;

    const help = column.help?.trim();
    const labels = (
      <span
        class="ds-table__header-labels"
        tabIndex={interactive && help && !column.sortable ? 0 : undefined}
        data-header-help={help ? '' : undefined}
      >
        {headerSegments.map((segment, index) => {
          const segmentActive = activeMemberSegment?.sortKey === segment.sortKey;
          const segmentInteractive = interactive && !!column.sortable;
          const label = (
            <ds-text
              class="ds-table__header-label-box ds-control-label-box"
              as="span"
              variant="text-caption"
              emphasis={segmentActive}
              color="inherit"
              decoration={help ? 'dotted-underline' : undefined}
              lineTruncation={1}
            >
              {segment.label}
            </ds-text>
          );
          const control = segmentInteractive ? (
            <button
              class="ds-table__header-label ds-table__header-label--interactive ds-focus-ring"
              type="button"
              aria-label={this.sortButtonLabel(
                column,
                segment.sortKey,
                segment.dataLabel?.trim() || segment.label
              )}
              data-sort-control="label"
              data-sort-key={segment.sortKey}
              data-sort-active={segmentActive ? 'true' : undefined}
              onClick={() => this.emitSort(column, segment.sortKey)}
            >
              {label}
            </button>
          ) : (
            <span class="ds-table__header-label ds-table__header-static">{label}</span>
          );

          return (
            <span class="ds-table__header-segment" key={segment.sortKey}>
              {control}
              {index < headerSegments.length - 1 && (
                <ds-text
                  class="ds-table__header-separator"
                  as="span"
                  variant="text-caption"
                  color="tertiary"
                  aria-hidden="true"
                >
                  {segment.separator ?? '/'}
                </ds-text>
              )}
            </span>
          );
        })}
      </span>
    );
    const labelControl =
      interactive && help ? (
        <ds-tooltip label={help} side="top" size="sm" wrapLabel={true}>
          {labels}
        </ds-tooltip>
      ) : (
        labels
      );
    const sortControl = interactive ? (
      <span class="ds-table__sort-slot">
        {activeSort && (
          <ds-button-unfilled
            class="ds-table__sort-direction"
            variant="icon"
            icon={direction === 'asc' ? 'ArrowUp' : 'ArrowDown'}
            size="xs"
            aria-label={this.sortButtonLabel(
              column,
              activeMemberSegment?.sortKey ?? column.id,
              activeMemberSegment?.label ?? column.header
            )}
            hasBorder={false}
            activeFill={false}
            isActive={true}
            pressScale={false}
            data-sort-control="direction"
            onDsClick={() => this.emitSort(column, activeMemberSegment?.sortKey ?? column.id)}
          />
        )}
      </span>
    ) : null;
    const collapseHost = model.collapseAllHost;
    const actionCollapseHost =
      collapseHost?.mode === 'action' && collapseHost.columnId === column.id;
    const blankActionCollapseHost =
      actionCollapseHost && !column.header.trim() && !column.headerSegments?.length;
    const collapseControl =
      interactive && actionCollapseHost ? (
        <span class="ds-table__collapse-slot">{this.renderCollapseAllButton()}</span>
      ) : null;

    return (
      <th
        key={column.id}
        class={{
          'ds-table__header-cell': true,
          [`ds-table__cell--align-${align}`]: true,
          'ds-table__cell--sticky-start': column.sticky === 'start',
          'ds-table__cell--sticky-end': column.sticky === 'end',
          'ds-table__header-cell--collapse-all': actionCollapseHost,
        }}
        scope={presentational ? undefined : 'col'}
        aria-sort={presentational ? undefined : memberAriaSort}
        data-column-id={column.id}
        data-grouped={groupedColumn ? 'true' : undefined}
        data-sort-active={activeSort ? 'true' : undefined}
      >
        {!column.header.trim() && column.headerLabel?.trim() && (
          <span class="ds-visually-hidden">{column.headerLabel}</span>
        )}
        {blankActionCollapseHost ? (
          <span class="ds-table__header-content ds-table__header-content--collapse-all">
            {collapseControl}
          </span>
        ) : (
          <span class="ds-table__header-content">
            {align === 'end' && sortControl}
            {align === 'center' && (
              <span
                class="ds-table__sort-slot ds-table__sort-slot--balance"
                data-sort-balance="true"
                aria-hidden="true"
              />
            )}
            {labelControl}
            {align !== 'end' && sortControl}
            {collapseControl}
          </span>
        )}
        {this.renderStickyEdge(column.sticky)}
      </th>
    );
  }

  private renderColgroup(model: TableRenderModel) {
    const beforeSpacer =
      model.elasticSpacerIndex == null
        ? this.visibleColumns
        : this.visibleColumns.slice(0, model.elasticSpacerIndex);
    const afterSpacer =
      model.elasticSpacerIndex == null ? [] : this.visibleColumns.slice(model.elasticSpacerIndex);
    const renderColumn = (column: TableColumn) => {
      const width = tableColumnSize(column);
      return (
        <col
          key={column.id}
          class={{ 'ds-table__action-column': column.kind === 'action' }}
          style={width ? { width } : undefined}
        />
      );
    };
    return (
      <colgroup>
        {model.selectable && <col class="ds-table__selection-column" />}
        {beforeSpacer.map(renderColumn)}
        {model.elasticSpacerIndex != null && <col class="ds-table__elastic-spacer-column" />}
        {afterSpacer.map(renderColumn)}
      </colgroup>
    );
  }

  private renderHeader(
    model: TableRenderModel,
    interactive = true,
    presentational = false,
    ariaRowIndex?: number
  ) {
    const selection = model.selection;
    const beforeSpacer =
      model.elasticSpacerIndex == null
        ? this.visibleColumns
        : this.visibleColumns.slice(0, model.elasticSpacerIndex);
    const afterSpacer =
      model.elasticSpacerIndex == null ? [] : this.visibleColumns.slice(model.elasticSpacerIndex);
    return (
      <thead
        class={{
          'ds-table__head': true,
          'ds-table__head--semantic-copy': !interactive,
        }}
        ref={element => {
          if (interactive) this.interactiveHeadEl = element ?? null;
        }}
      >
        <tr class="ds-table__header-row" aria-rowindex={ariaRowIndex}>
          {model.selectable && (
            <th
              class="ds-table__header-cell ds-table__selection-cell ds-table__cell--sticky-start"
              scope={presentational ? undefined : 'col'}
            >
              {interactive ? (
                this.renderSelectionControl(
                  selection.allSelected ? 'Deselect all loaded rows' : 'Select all loaded rows',
                  selection.allSelected,
                  selection.indeterminate,
                  selection.selectableRowIds.length === 0,
                  () => this.emitAllSelection()
                )
              ) : (
                <span class="ds-visually-hidden">Select rows</span>
              )}
              {this.renderStickyEdge('start')}
            </th>
          )}
          {beforeSpacer.map(column =>
            this.renderColumnHeader(column, model, interactive, presentational)
          )}
          {model.elasticSpacerIndex != null && (
            <th
              class="ds-table__header-cell ds-table__elastic-spacer-cell"
              aria-hidden="true"
              role="presentation"
              data-elastic-spacer="true"
            />
          )}
          {afterSpacer.map(column =>
            this.renderColumnHeader(column, model, interactive, presentational)
          )}
        </tr>
      </thead>
    );
  }

  private renderRow(
    row: TableRow,
    model: TableRenderModel,
    ariaRowIndex?: number,
    variableVirtualSize = false,
    rowKey = row.id
  ) {
    return renderTableRowView({
      row,
      model,
      visibleColumns: this.visibleColumns,
      emptyCellLabel: this.emptyCellLabel,
      actionMenuElementId: this.actionMenuElementId,
      actionMenu: this.actionMenu,
      highlightMatcher: this.highlightMatcher,
      highlightFieldIds: this.highlightFieldIds,
      ariaRowIndex,
      variableVirtualSize,
      intrinsicBlockSize:
        this.dataMode !== 'virtual'
          ? estimateTableRowBlockSize(row, this.visibleColumns)
          : undefined,
      rowKey,
      renderSelectionControl: (label, checked, indeterminate, disabled, onActivate) =>
        this.renderSelectionControl(label, checked, indeterminate, disabled, onActivate),
      renderStickyEdge: sticky => this.renderStickyEdge(sticky),
      onRowActivate: (targetRow, event) => this.emitRowActivation(targetRow, event),
      onRowKeyDown: (targetRow, event) => this.handleRowKeydown(targetRow, event),
      onRowSelection: targetRow => this.emitRowSelection(targetRow),
      onCellAction: detail => this.dsCellAction.emit(detail),
      onActionMenuToggle: (targetRow, column, event) =>
        this.toggleActionMenu(targetRow, column, event),
    });
  }

  private emitGroupCollapse(group: TableGroup) {
    const collapsedGroupIds = toggleTableGroupCollapsed(this.collapsedGroupIds, group.id);
    this.dsGroupCollapseChange.emit({
      scope: 'group',
      groupId: group.id,
      collapsed: collapsedGroupIds.includes(group.id),
      collapsedGroupIds,
    });
  }

  private emitAllGroupsCollapse() {
    const groupIds = this.groups.map(group => group.id);
    const collapsedGroupIds = nextTableGroupsCollapsed(this.collapsedGroupIds, groupIds);
    this.dsGroupCollapseChange.emit({
      scope: 'all',
      collapsed: collapsedGroupIds.length > 0,
      collapsedGroupIds,
    });
  }

  private renderGroupContent(groupModel: TableRenderModel['groups'][number]) {
    const {
      group,
      countLabel,
      collapsed: isCollapsed,
      labelColor,
      selection: groupSelection,
    } = groupModel;
    return (
      <span
        class="ds-table__group-content"
        onClick={event => this.handleGroupRowClick(group, event)}
      >
        {groupSelection && (
          <span class="ds-table__group-selection">
            {this.renderSelectionControl(
              groupSelection.allSelected
                ? `Deselect loaded rows in ${group.label} group`
                : `Select loaded rows in ${group.label} group`,
              groupSelection.allSelected,
              groupSelection.indeterminate,
              groupSelection.selectableRowIds.length === 0,
              () => this.emitGroupSelection(group)
            )}
          </span>
        )}
        <span class="ds-table__group-copy">
          <ds-text
            class="ds-table__group-label"
            as="span"
            variant="text-body-medium"
            emphasis={true}
            color={labelColor}
          >
            {group.label}
          </ds-text>
          <ds-text
            class="ds-table__group-separator"
            as="span"
            variant="text-body-medium"
            color="secondary"
            aria-hidden="true"
          >
            ·
          </ds-text>
          <ds-text
            class="ds-table__group-count"
            as="span"
            variant="text-body-medium"
            color="secondary"
            aria-hidden="true"
          >
            {groupModel.visibleCountText}
          </ds-text>
          <span class="ds-visually-hidden">{countLabel}</span>
        </span>
        <ds-button-unfilled
          class="ds-table__group-toggle"
          variant="icon"
          size="md"
          isInset={true}
          insetDepth="double"
          icon={isCollapsed ? 'ChevronDown' : 'ChevronUp'}
          expanded={!isCollapsed}
          aria-label={isCollapsed ? `Expand ${group.label} group` : `Collapse ${group.label} group`}
          hasBorder={false}
          pressScale={false}
        />
      </span>
    );
  }

  private formatGroupLoadLabel(template: string, group: TableGroup): string {
    return template.split('{group}').join(group.label);
  }

  private renderGroupLoadRow(group: TableGroup, totalColumns: number) {
    const error = group.loadMoreError?.trim();
    if (!error && !group.loadingMore && !group.hasMore) return null;
    const manualFallback =
      this.loadMoreMode === 'manual' || !this.groupLoadController.intersectionSupported;

    return (
      <tr
        class="ds-table__load-row ds-table__group-load-row"
        data-group-id={group.id}
        ref={element => {
          if (element) this.groupSentinelEls.set(group.id, element);
          else this.groupSentinelEls.delete(group.id);
        }}
      >
        <td class="ds-table__load-cell" colSpan={totalColumns}>
          <div class="ds-table__viewport-band ds-table__load-band">
            {renderTableLoadContent({
              error,
              loading: !!group.loadingMore,
              hasMore: !!group.hasMore,
              manualFallback,
              retryLabel: this.formatGroupLoadLabel(this.groupRetryLabel, group),
              loadingLabel: this.formatGroupLoadLabel(this.groupLoadingMoreLabel, group),
              loadMoreLabel: this.groupLoadMoreLabel,
              loadMoreAriaLabel: this.formatGroupLoadLabel(this.groupLoadMoreAriaLabel, group),
              onRetry: () => this.groupLoadController.request(group.id, 'retry'),
              onLoadMore: () => this.groupLoadController.request(group.id, 'manual'),
            })}
          </div>
        </td>
      </tr>
    );
  }

  private renderStickyGroup(model: TableRenderModel) {
    if (!this.documentStickyHeader || !this.activeStickyGroupId) return null;
    const groupModel = model.groups.find(item => item.group.id === this.activeStickyGroupId);
    if (!groupModel) return null;
    return (
      <div
        class={{
          'ds-table__sticky-group': true,
          'ds-table__sticky-group--selectable': model.selectable,
          [groupModel.intentClass ?? '']: !!groupModel.intentClass,
        }}
        data-group-id={groupModel.group.id}
        data-group-intent={groupModel.intent}
      >
        {this.renderGroupContent(groupModel)}
      </div>
    );
  }

  private renderDataBodies(model: TableRenderModel, plan: TableVirtualPlan | null) {
    return this.bodyRenderer.render({
      model,
      plan,
      rows: this.rows,
      stickyHeader: this.stickyHeader,
      documentStickyHeader: this.documentStickyHeader,
      activeStickyGroupId: this.activeStickyGroupId,
      renderRow: (row, renderModel, ariaRowIndex, variableVirtualSize, rowKey) =>
        this.renderRow(row, renderModel, ariaRowIndex, variableVirtualSize, rowKey),
      renderGroupContent: groupModel => this.renderGroupContent(groupModel),
      renderGroupLoadRow: (group, totalColumns) => this.renderGroupLoadRow(group, totalColumns),
    });
  }

  private renderSkeletonBody(model: TableRenderModel) {
    return renderTableSkeletonBody({
      model,
      visibleColumns: this.visibleColumns,
      skeletonRows: this.skeletonRows,
      renderStickyEdge: sticky => this.renderStickyEdge(sticky),
    });
  }

  private renderStateBody(kind: 'empty' | 'error' | 'virtual-viewport', totalColumns: number) {
    const error = kind !== 'empty';
    const heading =
      kind === 'virtual-viewport'
        ? TABLE_VIRTUAL_VIEWPORT_REQUIRED_HEADING
        : error
          ? this.errorHeading
          : this.emptyHeading;
    const body =
      kind === 'virtual-viewport'
        ? TABLE_VIRTUAL_VIEWPORT_REQUIRED_BODY
        : error
          ? this.errorBody
          : this.emptyBody;
    return (
      <tbody class="ds-table__body ds-table__state-body">
        <tr class="ds-table__state-row">
          <td class="ds-table__state-cell" colSpan={totalColumns}>
            <div class="ds-table__viewport-band ds-table__state-band">
              <ds-empty-state
                icon={error ? 'ErrorTriangle' : 'Inbox'}
                heading={heading}
                body={body}
              />
            </div>
          </td>
        </tr>
      </tbody>
    );
  }

  private renderLazyBody(model: TableRenderModel) {
    if (
      this.dataMode !== 'infinite' ||
      !this.incrementalWindowActive ||
      !model.hasData ||
      model.grouped
    )
      return null;
    const error = this.loadMoreError?.trim();
    const manualFallback =
      this.loadMoreMode === 'manual' || !this.loadController.intersectionSupported;

    return (
      <tbody class="ds-table__body ds-table__load-body">
        <tr
          class="ds-table__load-row"
          ref={element => {
            this.sentinelEl = element ?? null;
          }}
        >
          <td class="ds-table__load-cell" colSpan={model.totalColumns}>
            <div class="ds-table__viewport-band ds-table__load-band">
              {renderTableLoadContent({
                error,
                loading: this.loadingMore,
                hasMore: this.hasMore,
                manualFallback,
                retryLabel: this.retryLabel,
                loadingLabel: this.loadingMoreLabel,
                loadMoreLabel: this.loadMoreLabel,
                endOfResultsLabel: this.endOfResultsLabel,
                onRetry: () => this.loadController.request('retry'),
                onLoadMore: () => this.loadController.request('manual'),
              })}
            </div>
          </td>
        </tr>
      </tbody>
    );
  }

  private renderDocumentStickyHeader(model: TableRenderModel) {
    if (!this.documentStickyHeader) return null;
    return (
      <div class="ds-table__document-sticky-header">
        <table
          class={{
            'ds-table__table': true,
            'ds-table__sticky-header-table': true,
            'ds-table__table--selectable': model.selectable,
            'ds-table__table--grouped': model.grouped,
          }}
          style={model.tableStyle}
          role="presentation"
          ref={element => {
            this.stickyHeaderTableEl = element ?? null;
          }}
        >
          {this.renderColgroup(model)}
          {this.renderHeader(model, true, true)}
        </table>
        {this.renderFloatingCollapseAll(model)}
      </div>
    );
  }

  private get resultSummary(): string | null {
    if (this.dataMode === 'pagination') return null;
    if (this.dataMode === 'virtual') {
      return formatTableTotalSummary(this.currentLoadedRowCount(), this.resultTotalSummaryLabel);
    }
    return formatTableResultSummary(this.displayedCount, this.totalCount, this.resultSummaryLabel);
  }

  private get hasResultFooter(): boolean {
    return (
      (this.dataMode === 'pagination' && !!this.pagination) ||
      !!this.resultSummary ||
      this.footerSlotPresence !== 0
    );
  }

  private renderResultFooter() {
    const summary = this.resultSummary;
    const hasLeading = (this.footerSlotPresence & TABLE_FOOTER_SLOT_LEADING) !== 0;
    const hasCopy = (this.footerSlotPresence & TABLE_FOOTER_SLOT_COPY) !== 0;
    const hasTrailing = (this.footerSlotPresence & TABLE_FOOTER_SLOT_TRAILING) !== 0;
    const pagination = this.dataMode === 'pagination' ? this.pagination : null;
    if (!this.hasResultFooter) return null;
    return (
      <div class="ds-table__footer ds-table__bar ds-chrome-header ds-control--md">
        <div class="ds-table__bar-copy ds-chrome-header__copy ds-control--md">
          {hasLeading && (
            <div class="ds-table__bar-status ds-chrome-header__heading">
              <slot name="footer-leading" onSlotchange={this.syncFooterSlotPresence} />
            </div>
          )}
          {hasCopy ? (
            <slot name="footer" onSlotchange={this.syncFooterSlotPresence} />
          ) : summary ? (
            <ds-text
              class="ds-table__footer-summary ds-table__bar-text"
              as="span"
              variant="text-body-medium"
              color="secondary"
              lineTruncation={1}
            >
              {summary}
            </ds-text>
          ) : null}
        </div>
        {(pagination || hasTrailing) && (
          <div class="ds-table__bar-trailing ds-chrome-header__trailing">
            {pagination && (
              <ds-pagination
                pageIndex={pagination.pageIndex}
                pageSize={pagination.pageSize}
                pageSizeMode={pagination.pageSizeMode ?? 'fixed'}
                totalItems={pagination.totalItems}
                pageSizeOptions={pagination.pageSizeOptions ?? [25, 50, 100, 200]}
                fitToPage={pagination.fitToPage ?? false}
                {...{ fitToPageInactive: pagination.fitToPageInactive ?? false }}
                fitPageSize={this.fitPageSize ?? pagination.fitPageSize}
                fitPageSizeLabel={pagination.fitPageSizeLabel ?? 'Fit to page'}
                fitPageSizeTriggerLabel={pagination.fitPageSizeTriggerLabel ?? 'Fit'}
                itemLabel={pagination.itemLabel ?? 'items'}
                pageSizeLabel={pagination.pageSizeLabel ?? 'Items'}
                label={pagination.ariaLabel ?? `${this.caption} pagination`}
                showFirstLastButtons={pagination.showFirstLastButtons ?? false}
                loading={this.loading}
                onDsChange={(event: CustomEvent<PaginationChangeDetail>) =>
                  this.dsPaginationChange.emit(event.detail)
                }
              />
            )}
            <slot name="footer-trailing" onSlotchange={this.syncFooterSlotPresence} />
          </div>
        )}
      </div>
    );
  }

  private renderCaptionBar() {
    if (this.captionVisibility !== 'visible') return null;
    return (
      <div class="ds-table__caption-bar ds-table__bar ds-control--md">
        <div
          class={{
            'ds-table__caption-content': true,
            'ds-table__caption-content--trailing': this.showsCaptionTrailing,
          }}
        >
          <div
            class={{
              'ds-table__caption-leading': true,
              'ds-table__caption-leading--toolbar': this.headerUsesToolbar,
            }}
          >
            <slot name="header" onSlotchange={this.syncHeaderSlotPresence} />
            {!this.headerPresent ? (
              <ds-text
                class="ds-table__caption-title ds-table__bar-text"
                as="div"
                variant="text-title-small"
                emphasis={true}
                color="primary"
                aria-hidden="true"
              >
                {this.caption}
              </ds-text>
            ) : null}
          </div>
          {this.renderCaptionTrailing()}
        </div>
      </div>
    );
  }

  private renderCaptionTrailing() {
    if (!this.showsCaptionTrailing) return null;
    return (
      <div class="ds-table__caption-trailing">
        {this.renderColumnCustomizerTrigger()}
        {this.showsColumnCustomizer && this.showsDataModeSwitcher ? (
          <ds-divider orientation="vertical" length="32px" />
        ) : null}
        {this.renderDataModeSwitcherTrigger()}
      </div>
    );
  }

  private renderDataModeSwitcherTrigger() {
    if (!this.showsDataModeSwitcher) return null;
    if (this.chromeLoading) {
      return <ds-skeleton variant="control" controlSize="md" width="var(--dimension-size-400)" />;
    }
    return (
      <span class="ds-table__caption-mode-switcher">
        <ds-tooltip label={this.dataModeSwitcherLabel} side="top" size="sm">
          <ds-button-unfilled
            id={`${this.dataModeSwitcherElementId}-trigger`}
            variant="icon"
            size="md"
            icon="Ellipses"
            aria-label={this.dataModeSwitcherLabel}
            hasMenu={true}
            expanded={this.dataModeSwitcherOpen}
            controls={this.dataModeSwitcherElementId}
            activeFill={false}
            pressScale={false}
            onDsClick={(event: CustomEvent<MouseEvent>) => {
              this.toggleDataModeSwitcher(event.detail.detail === 0);
            }}
          />
        </ds-tooltip>
      </span>
    );
  }

  private renderDataModeSwitcherMenu() {
    if (!this.showsDataModeSwitcher || this.chromeLoading) return null;
    return (
      <ds-menu
        id={this.dataModeSwitcherElementId}
        open={this.dataModeSwitcherOpen}
        anchorId={`${this.dataModeSwitcherElementId}-trigger`}
        align="end"
        side="bottom"
        menuLabel={this.dataModeMenuLabel}
        initialFocusVisible={this.dataModeSwitcherInitialFocusVisible}
        items={tableDataModeMenuItems(this.dataMode, {
          infinite: this.infiniteModeLabel,
          pagination: this.paginationModeLabel,
          virtual: this.virtualModeLabel,
        })}
        onDsClose={() => this.closeDataModeSwitcher()}
        onDsSelect={event => this.handleDataModeSwitcherSelect(event.detail)}
      />
    );
  }

  private toggleDataModeSwitcher(fromKeyboard = false): void {
    if (this.dataModeSwitcherOpen) this.closeDataModeSwitcher();
    else this.openDataModeSwitcher(fromKeyboard);
  }

  private openDataModeSwitcher(fromKeyboard = false): void {
    if (!this.showsDataModeSwitcher || this.dataModeSwitcherOpen) return;
    this.closeColumnCustomizer();
    this.dataModeSwitcherInitialFocusVisible = fromKeyboard;
    this.dataModeSwitcherOpen = true;
  }

  private closeDataModeSwitcher(): void {
    this.dataModeSwitcherOpen = false;
  }

  private handleDataModeSwitcherSelect(item: MenuItemData): void {
    const dataMode = tableDataModeFromMenuItem(item);
    if (!dataMode) return;
    this.closeDataModeSwitcher();
    if (dataMode !== this.dataMode) this.dsDataModeChange.emit({ dataMode });
    requestAnimationFrame(() => {
      this.el
        .querySelector<
          HTMLElement & { setFocus?: () => void }
        >(`#${CSS.escape(`${this.dataModeSwitcherElementId}-trigger`)}`)
        ?.setFocus?.();
    });
  }

  private renderColumnCustomizerTrigger() {
    if (!this.showsColumnCustomizer) return null;
    return (
      <div
        class={{
          'ds-table__caption-customizer': true,
          'ds-table__caption-customizer--loading': this.chromeLoading,
        }}
        aria-hidden={this.chromeLoading ? 'true' : undefined}
      >
        <ds-tooltip label={this.captionCompact ? 'Customize' : ''} side="top" size="sm">
          <ds-button-unfilled
            id={`${this.columnCustomizerElementId}-trigger`}
            variant={this.captionCompact ? 'icon' : 'icon-label'}
            size="md"
            icon="Table"
            label="Customize"
            labelEmphasis={false}
            pressScale={false}
            aria-label="Customize table"
            hasMenu={true}
            expanded={this.columnCustomizerOpen}
            controls={this.columnCustomizerElementId}
            onDsClick={(event: CustomEvent<MouseEvent>) => {
              if (this.chromeLoading) return;
              this.toggleColumnCustomizer(event.detail.detail === 0);
            }}
          />
        </ds-tooltip>
        {this.chromeLoading ? (
          <ds-skeleton variant="control" controlSize="md" width="100%" />
        ) : null}
      </div>
    );
  }

  private renderColumnCustomizerMenu() {
    if (!this.showsColumnCustomizer || this.chromeLoading) return null;
    return (
      <ds-menu
        id={this.columnCustomizerElementId}
        open={this.columnCustomizerOpen}
        anchorId={`${this.columnCustomizerElementId}-trigger`}
        align="end"
        side="bottom"
        menuLabel="Customize table"
        initialFocusVisible={this.columnCustomizerInitialFocusVisible}
        items={tableColumnCustomizerMenuItems(this.columns, this.hiddenColumnIds, this.columnOrder)}
        onDsClose={() => this.closeColumnCustomizer()}
        onDsSelect={event => this.handleColumnCustomizerSelect(event.detail)}
        onDsReorder={event => this.handleColumnCustomizerReorder(event.detail)}
      />
    );
  }

  private toggleColumnCustomizer(fromKeyboard = false): void {
    if (this.columnCustomizerOpen) this.closeColumnCustomizer();
    else this.openColumnCustomizer(fromKeyboard);
  }

  private openColumnCustomizer(fromKeyboard = false): void {
    if (!this.showsColumnCustomizer || this.columnCustomizerOpen) return;
    this.closeDataModeSwitcher();
    this.columnCustomizerInitialFocusVisible = fromKeyboard;
    this.columnCustomizerOpen = true;
  }

  private closeColumnCustomizer(): void {
    this.columnCustomizerOpen = false;
  }

  private emitColumnsConfigChange(hiddenColumnIds: string[], columnOrder: string[]): void {
    this.dsColumnsConfigChange.emit({
      hiddenColumnIds: resolveTableHiddenColumnIds(this.columns, hiddenColumnIds),
      columnOrder: resolveTableColumnOrder(this.columns, columnOrder),
    });
  }

  private handleColumnCustomizerReorder(detail: MenuReorderDetail): void {
    const order = detail.items
      .filter(item => item.reorderable)
      .map(item => item.value)
      .filter((id): id is string => !!id);
    this.emitColumnsConfigChange(this.hiddenColumnIds, order);
  }

  private handleColumnCustomizerSelect(item: MenuItemData): void {
    const columnId = item.value;
    if (!columnId || item.isInactive) return;
    this.emitColumnsConfigChange(
      toggleTableColumnHidden(this.columns, this.hiddenColumnIds, columnId),
      resolveTableColumnOrder(this.columns, this.columnOrder)
    );
  }

  render() {
    this.groupSentinelEls.clear();
    const model = this.createRenderModel();
    this.syncVirtualItems(model);
    this.renderedModel = model;
    const regionLabel = this.scrollLabel?.trim() || `${this.caption} scroll area`;
    const initialLoading = this.loading && !model.hasData;
    const initialError = !model.hasData && this.error;
    const hasGroupedStructure = model.grouped && model.groups.length > 0;
    const windowRows = this.shouldWindowRows(model);
    const virtualViewportMissing =
      this.virtualViewportMissing && !initialLoading && (model.hasData || hasGroupedStructure);
    const virtualPlan = windowRows
      ? (this.virtualWindow ??
        resolveTableVirtualPlan({
          items: this.virtualItems,
          sizes: this.virtualItems.map(item => this.virtualController.sizeFor(item)),
          scrollOffset: this.viewportEl?.scrollTop ?? 0,
          viewportSize: this.estimateVirtualViewportSize(),
          pinnedRowIds: this.virtualPinnedRowIds(),
        }))
      : null;
    const groupLoadingMore = hasGroupedStructure && this.groups.some(group => group.loadingMore);
    const viewportStyle =
      !this.boundedComposition && this.resolvedMaxHeight
        ? { '--ds-table-max-block-size': this.resolvedMaxHeight }
        : undefined;
    const hostStyle = this.fixedHeight
      ? { '--_table-fixed-block-size': this.resolvedHeight }
      : undefined;

    return (
      <Host
        class={{
          'table-host': true,
          'table-host--bounded': this.boundedComposition,
          'table-host--fixed-height': this.fixedHeight,
          'table-host--viewport-fit': this.fitViewport,
        }}
        style={hostStyle}
        onKeyDown={(event: KeyboardEvent) => this.handlePaginationKeyDown(event)}
        onFocusin={this.onVirtualFocusIn}
      >
        <div
          class={{
            'ds-table': true,
            'ds-table--bounded': this.boundedComposition,
            'ds-table--contained-scroll': this.containedScroll,
            'ds-table--fixed-height': this.fixedHeight,
            'ds-table--viewport-fit': this.fitViewport,
            'ds-table--viewport-fit-pending': this.fitViewport && !this.viewportFitSettled,
            'ds-table--viewport-fit-settled': this.fitViewport && this.viewportFitSettled,
            'ds-table--sticky-header': this.stickyHeader,
            'ds-table--document-sticky-header': this.documentStickyHeader,
            'ds-table--contained-sticky-header': this.stickyHeader && !this.documentStickyHeader,
            'ds-table--caption-visible': this.captionVisibility === 'visible',
            'ds-table--footer-visible': this.hasResultFooter,
            'ds-table--state-fill':
              !initialLoading &&
              (initialError || virtualViewportMissing || !(model.hasData || hasGroupedStructure)),
          }}
          ref={element => {
            this.rootEl = element ?? null;
          }}
        >
          {this.renderCaptionBar()}
          <div
            class={{
              'ds-table__frame': true,
              'ds-table__frame--overflow-start': this.overflowStart,
              'ds-table__frame--overflow-end': this.overflowEnd,
            }}
            ref={element => {
              this.frameEl = element ?? null;
            }}
          >
            {this.renderDocumentStickyHeader(model)}
            {this.renderStickyGroup(model)}
            {!this.documentStickyHeader && this.renderFloatingCollapseAll(model)}
            <div
              class={{
                'ds-table__viewport': true,
                'ds-focus-ring': this.scrollable,
              }}
              style={viewportStyle}
              ref={element => {
                this.viewportEl = element ?? null;
              }}
              role={this.scrollable ? 'region' : undefined}
              aria-label={this.scrollable ? regionLabel : undefined}
              tabIndex={this.scrollable ? 0 : undefined}
            >
              <table
                class={{
                  'ds-table__table': true,
                  'ds-table__table--selectable': model.selectable,
                  'ds-table__table--grouped': model.grouped,
                  'ds-table__table--deferred-rows': this.dataMode !== 'virtual',
                  'ds-table__table--windowed': windowRows,
                  'ds-table__table--virtual': this.dataMode === 'virtual' && windowRows,
                  'ds-table__table--native-group-sticky':
                    (model.grouped && this.stickyHeader && !this.documentStickyHeader) ||
                    windowRows,
                }}
                style={model.tableStyle}
                aria-rowcount={windowRows ? 1 + this.virtualItems.length : undefined}
                aria-busy={
                  initialLoading ||
                  (this.dataMode === 'infinite' && (this.loadingMore || groupLoadingMore))
                    ? 'true'
                    : undefined
                }
                ref={element => {
                  this.tableEl = element ?? null;
                }}
              >
                <caption class="ds-table__caption ds-visually-hidden">
                  <ds-text as="span" variant="text-title-small" emphasis={true} color="primary">
                    {this.caption}
                  </ds-text>
                </caption>
                {this.renderColgroup(model)}
                {this.renderHeader(
                  model,
                  !this.documentStickyHeader,
                  false,
                  windowRows ? 1 : undefined
                )}
                {initialLoading
                  ? this.renderSkeletonBody(model)
                  : initialError
                    ? this.renderStateBody('error', model.totalColumns)
                    : virtualViewportMissing
                      ? this.renderStateBody('virtual-viewport', model.totalColumns)
                      : model.hasData || hasGroupedStructure
                        ? this.renderDataBodies(model, virtualPlan)
                        : this.renderStateBody('empty', model.totalColumns)}
                {!initialLoading &&
                  !initialError &&
                  this.dataMode !== 'virtual' &&
                  this.renderLazyBody(model)}
              </table>
            </div>
          </div>
          {this.renderResultFooter()}
          {this.renderOverflowActionMenu()}
          {this.renderDataModeSwitcherMenu()}
          {this.renderColumnCustomizerMenu()}
          {this.renderTruncateTooltip()}
          <div class="ds-visually-hidden" role="status" aria-live="polite" aria-atomic="true">
            {this.announcement}
          </div>
        </div>
      </Host>
    );
  }
}

import type { MenuItemData, MenuItemsSection } from '../Menu/menu-types';
import type { TableCellAction, TableCellActionMenuEntry } from './table-types';

let actionMenuSeq = 0;

export function nextTableActionMenuElementId(): string {
  actionMenuSeq += 1;
  return `ds-table-action-menu-${actionMenuSeq}`;
}

export function isTableCellActionMenu(
  value: TableCellAction
): value is TableCellAction & { items: TableCellActionMenuEntry[]; ariaLabel: string } {
  return Array.isArray(value.items);
}

export function isRenderableTableActionMenu(
  value: TableCellAction
): value is TableCellAction & { items: TableCellActionMenuEntry[]; ariaLabel: string } {
  return isTableCellActionMenu(value) && tableActionMenuSections(value.items).length > 0;
}

/** Split divider entries into Menu sections. Empty runs (leading/repeated dividers) are dropped. */
export function tableActionMenuSections(items: TableCellActionMenuEntry[]): MenuItemsSection[] {
  const sections: MenuItemsSection[] = [];
  let current: MenuItemData[] = [];
  const flush = () => {
    if (!current.length) return;
    sections.push({ items: current });
    current = [];
  };

  for (const entry of items) {
    if ('kind' in entry) {
      flush();
      continue;
    }
    current.push({
      value: entry.actionId,
      label: entry.label,
      ...(entry.isInactive ? { isInactive: true } : {}),
      ...(entry.isDestructive ? { isDestructive: true } : {}),
    });
  }
  flush();
  return sections;
}

export function tableActionTriggerId(menuId: string, rowId: string, columnId: string): string {
  return `${menuId}-${sanitizeId(rowId)}-${sanitizeId(columnId)}`;
}

function sanitizeId(value: string): string {
  return value.replace(/[^A-Za-z0-9_-]+/g, '-');
}

import { h } from '@stencil/core';
import type { TableGroupRenderModel, TableRenderModel } from './table-render-model';
import type { TableGroup, TableRow } from './table-types';
import type { TableVirtualNode, TableVirtualPlan } from './table-virtual-model';

export interface TableVirtualRowPoolState {
  slotsByRowId: Map<string, number>;
  nextSlot: number;
}

export interface TableBodyRenderOptions {
  model: TableRenderModel;
  plan: TableVirtualPlan | null;
  rows: TableRow[];
  stickyHeader: boolean;
  documentStickyHeader: boolean;
  activeStickyGroupId: string | null;
  renderRow: (
    row: TableRow,
    model: TableRenderModel,
    ariaRowIndex?: number,
    variableVirtualSize?: boolean,
    rowKey?: string
  ) => unknown;
  renderGroupContent: (group: TableGroupRenderModel) => unknown;
  renderGroupLoadRow: (group: TableGroup, totalColumns: number) => unknown;
}

/**
 * Assign stable, bounded DOM keys to the rows currently occupying one virtual scope.
 * Departed rows release their slots so long scrolls recycle DOM instead of growing it.
 */
export function assignTableVirtualRowPoolKeys(
  nodes: readonly TableVirtualNode[],
  state: TableVirtualRowPoolState
): Map<number, string> {
  const rows = nodes.filter(
    (node): node is Extract<TableVirtualNode, { kind: 'row' }> => node.kind === 'row'
  );
  const desiredIds = new Set(rows.map(node => node.item.rowId ?? node.item.id));
  const freeSlots: number[] = [];
  for (const [rowId, slot] of state.slotsByRowId) {
    if (desiredIds.has(rowId)) continue;
    state.slotsByRowId.delete(rowId);
    freeSlots.push(slot);
  }
  freeSlots.sort((left, right) => left - right);

  const keys = new Map<number, string>();
  for (const node of rows) {
    const rowId = node.item.rowId ?? node.item.id;
    let slot = state.slotsByRowId.get(rowId);
    if (slot == null) {
      slot = freeSlots.shift() ?? state.nextSlot++;
      state.slotsByRowId.set(rowId, slot);
    }
    keys.set(node.index, `virtual-row-slot-${slot}`);
  }
  return keys;
}

/** Owns grouped and virtual tbody composition while Table remains the behavior orchestrator. */
export class TableBodyRenderer {
  private virtualLookupCache: {
    rows: TableRow[];
    groups: TableGroupRenderModel[];
    rowsById: Map<string, TableRow>;
    groupsById: Map<string, TableGroupRenderModel>;
  } | null = null;

  private readonly virtualRowPoolStates = new Map<string, TableVirtualRowPoolState>();

  resetVirtualState(): void {
    this.virtualLookupCache = null;
    this.virtualRowPoolStates.clear();
  }

  render(options: TableBodyRenderOptions) {
    if (options.plan) return this.renderVirtualBodies(options);

    const { model } = options;
    if (!model.grouped) {
      return (
        <tbody class="ds-table__body">
          {options.rows.map(row => options.renderRow(row, model))}
        </tbody>
      );
    }

    return model.groups.map(groupModel => {
      const { group, collapsed: isCollapsed, intent, intentClass } = groupModel;
      const stickySourceHidden =
        options.documentStickyHeader && options.activeStickyGroupId === group.id;
      return (
        <tbody
          class="ds-table__body ds-table__group"
          role="rowgroup"
          data-group-id={group.id}
          data-group-intent={intent}
          data-collapsed={isCollapsed ? 'true' : undefined}
          aria-busy={!isCollapsed && group.loadingMore ? 'true' : undefined}
          key={group.id}
        >
          <tr
            role="row"
            aria-hidden={stickySourceHidden ? 'true' : undefined}
            class={{
              'ds-table__group-row': true,
              'ds-table__group-row--native-sticky':
                options.stickyHeader && !options.documentStickyHeader,
            }}
          >
            <th
              class={{
                'ds-table__group-cell': true,
                'ds-table__group-cell--sticky-source-hidden': stickySourceHidden,
                [intentClass ?? '']: !!intentClass,
              }}
              role="rowheader"
              scope="rowgroup"
              colSpan={model.totalColumns}
            >
              {options.renderGroupContent(groupModel)}
            </th>
          </tr>
          {!isCollapsed && group.rows.map(row => options.renderRow(row, model))}
          {!isCollapsed && options.renderGroupLoadRow(group, model.totalColumns)}
        </tbody>
      );
    });
  }

  private renderVirtualSpacer(
    node: Extract<TableVirtualNode, { kind: 'spacer' }>,
    totalColumns: number
  ) {
    if (node.size <= 0) return null;
    return (
      <tr class="ds-table__virtual-spacer-row" key={node.key} aria-hidden="true">
        <td
          class="ds-table__virtual-spacer-cell"
          colSpan={totalColumns}
          style={
            { '--_table-virtual-spacer-block-size': `${node.size}px` } as Record<string, string>
          }
        />
      </tr>
    );
  }

  private renderVirtualRow(
    node: Extract<TableVirtualNode, { kind: 'row' }>,
    options: TableBodyRenderOptions,
    rowsById: Map<string, TableRow>,
    rowKey: string
  ) {
    const row = node.item.rowId ? rowsById.get(node.item.rowId) : undefined;
    if (!row) return null;
    return options.renderRow(row, options.model, node.index + 2, node.item.variableSize, rowKey);
  }

  private virtualRowPoolKeys(nodes: readonly TableVirtualNode[], scope: string) {
    const state = this.virtualRowPoolStates.get(scope) ?? {
      slotsByRowId: new Map<string, number>(),
      nextSlot: 0,
    };
    this.virtualRowPoolStates.set(scope, state);
    return assignTableVirtualRowPoolKeys(nodes, state);
  }

  private renderVirtualGroup(
    node: Extract<TableVirtualNode, { kind: 'group' }>,
    options: TableBodyRenderOptions,
    rowsById: Map<string, TableRow>,
    groupsById: Map<string, TableGroupRenderModel>
  ) {
    const groupModel = groupsById.get(node.groupId);
    if (!groupModel) return null;
    const { group, collapsed: isCollapsed, intent, intentClass } = groupModel;
    const rowKeys = this.virtualRowPoolKeys(node.nodes, `group:${group.id}`);
    return (
      <tbody
        class="ds-table__body ds-table__group"
        role="rowgroup"
        data-group-id={group.id}
        data-group-intent={intent}
        data-collapsed={isCollapsed ? 'true' : undefined}
        key={group.id}
      >
        <tr
          role="row"
          data-virtual-id={`group:${group.id}`}
          aria-rowindex={node.headerIndex + 2}
          class={{
            'ds-table__group-row': true,
            'ds-table__group-row--native-sticky':
              options.stickyHeader && !options.documentStickyHeader,
          }}
        >
          <th
            class={{
              'ds-table__group-cell': true,
              [intentClass ?? '']: !!intentClass,
            }}
            role="rowheader"
            scope="rowgroup"
            colSpan={options.model.totalColumns}
          >
            {options.renderGroupContent(groupModel)}
          </th>
        </tr>
        {node.nodes.map(child =>
          child.kind === 'spacer'
            ? this.renderVirtualSpacer(child, options.model.totalColumns)
            : this.renderVirtualRow(
                child,
                options,
                rowsById,
                rowKeys.get(child.index) ?? `virtual-row-${child.index}`
              )
        )}
      </tbody>
    );
  }

  private renderVirtualBodies(options: TableBodyRenderOptions) {
    const { model, plan } = options;
    if (!plan) return null;
    let lookup = this.virtualLookupCache;
    if (!lookup || lookup.rows !== model.loadedRows || lookup.groups !== model.groups) {
      lookup = {
        rows: model.loadedRows,
        groups: model.groups,
        rowsById: new Map(model.loadedRows.map(row => [row.id, row])),
        groupsById: new Map(model.groups.map(groupModel => [groupModel.group.id, groupModel])),
      };
      this.virtualLookupCache = lookup;
    }
    const { rowsById, groupsById } = lookup;
    if (!model.grouped) {
      for (const scope of this.virtualRowPoolStates.keys()) {
        if (scope !== 'flat') this.virtualRowPoolStates.delete(scope);
      }
      const rowKeys = this.virtualRowPoolKeys(plan.nodes, 'flat');
      return (
        <tbody class="ds-table__body">
          {plan.nodes.map(node =>
            node.kind === 'spacer'
              ? this.renderVirtualSpacer(node, model.totalColumns)
              : node.kind === 'row'
                ? this.renderVirtualRow(
                    node,
                    options,
                    rowsById,
                    rowKeys.get(node.index) ?? `virtual-row-${node.index}`
                  )
                : null
          )}
        </tbody>
      );
    }

    const activeGroupScopes = new Set(
      plan.nodes
        .filter(
          (node): node is Extract<TableVirtualNode, { kind: 'group' }> => node.kind === 'group'
        )
        .map(node => `group:${node.groupId}`)
    );
    for (const scope of this.virtualRowPoolStates.keys()) {
      if (!activeGroupScopes.has(scope)) this.virtualRowPoolStates.delete(scope);
    }
    return plan.nodes.map(node => {
      if (node.kind === 'spacer') {
        return (
          <tbody class="ds-table__body ds-table__virtual-pad" aria-hidden="true" key={node.key}>
            {this.renderVirtualSpacer(node, model.totalColumns)}
          </tbody>
        );
      }
      if (node.kind === 'group') {
        return this.renderVirtualGroup(node, options, rowsById, groupsById);
      }
      return null;
    });
  }
}

import {
  isTableCellAction,
  isTableCellBlank,
  isTableCellEmpty,
  isTableCellIcon,
  isTableCellIconText,
  isTableCellImage,
  isTableCellPrimaryText,
  isTableCellTag,
  isTableCellTags,
  isTableCellText,
} from './table-model';
import type {
  TableCellAction,
  TableCellBlank,
  TableCellEmpty,
  TableCellIcon,
  TableCellImage,
  TableCellImageTracks,
  TableCellTag,
  TableCellTags,
  TableCellTagVariant,
  TableCellTextRun,
  TableCellTextTrack,
  TableCellValue,
  TableCellLinkTarget,
  TableCellLineClamp,
  TableCellMaxLines,
  TableColumn,
} from './table-types';
import type { IconColor } from '../Icon/Icon';
import type { TextColor } from '../Text/text-types';

/** Maximum independently colored runs on one secondary or tertiary track. */
export const TABLE_CELL_TEXT_RUN_LIMIT = 3;

export interface ResolvedTableCellText {
  primary: string | number;
  secondary?: TableCellTextRun[];
  tertiary?: TableCellTextRun[];
  secondaryColor?: TextColor;
  tertiaryColor?: TextColor;
  href?: string;
  target?: TableCellLinkTarget;
  wrap?: boolean;
  fontFeature?: 'normal' | 'tabular-nums';
}

export type TableCellPresentation =
  | { kind: 'blank'; cellType: 'blank'; value: TableCellBlank }
  | { kind: 'empty'; cellType: 'empty'; value: TableCellEmpty | null | undefined }
  | { kind: 'icon'; cellType: 'icon'; value: TableCellIcon }
  | {
      kind: 'icon-text';
      cellType: 'icon-text';
      icon: string;
      iconColor?: IconColor;
      iconLabel?: string;
      value: ResolvedTableCellText;
      variant: 'single' | 'multi' | 'triple';
      wraps: boolean;
      lineClamp: TableCellLineClamp;
    }
  | {
      kind: 'image';
      cellType: 'image';
      value: TableCellImage;
      variant: 'single' | 'multi' | 'triple';
    }
  | { kind: 'action'; cellType: 'action'; value: TableCellAction }
  | {
      kind: 'tag';
      cellType: 'tag';
      value: TableCellTag;
      variant: TableCellTagVariant;
    }
  | {
      kind: 'tags';
      cellType: 'tags';
      value: TableCellTags;
      tracks: number;
      variant: `${number}-track`;
    }
  | {
      kind: 'text';
      cellType: 'text' | 'primary-text';
      value: ResolvedTableCellText;
      primaryText: boolean;
      singleLine: boolean;
      variant: 'single' | 'multi' | 'triple' | 'primary-pair';
      wraps: boolean;
      lineClamp: TableCellLineClamp;
    };

function trackText(value: string | number | TableCellTextRun): string | undefined {
  if (typeof value === 'string' || typeof value === 'number') {
    const text = String(value);
    return text.trim() === '' ? undefined : text;
  }
  const text = value.text?.trim();
  return text ? value.text : undefined;
}

/** Resolve an image cell's track stack; unknown values fall back to one track. */
export function resolveTableCellImageTracks(
  tracks: TableCellImage['tracks']
): TableCellImageTracks {
  return tracks === 2 || tracks === 3 ? tracks : 1;
}

/** Map an image track stack onto the shared single/multi/triple cell variant. */
export function tableCellImageVariant(tracks: TableCellImageTracks): 'single' | 'multi' | 'triple' {
  return tracks === 3 ? 'triple' : tracks === 2 ? 'multi' : 'single';
}

/** Normalize the declared line count used by wrapping multiple-Tag cells. */
export function resolveTableCellTagsTracks(tracks: number): number {
  return Number.isFinite(tracks) && tracks > 0 ? Math.floor(tracks) : 1;
}

/** Token-backed content height for any named number of body-row tracks. */
export function tableCellTrackStackBlockSize(tracks: number): string {
  const count = resolveTableCellTagsTracks(tracks);
  return `calc(${count} * var(--_table-cell-track-min-block-size))`;
}

/** Collapse a consumer track into at most three non-empty runs. */
export function normalizeTableCellTextTrack(
  track: TableCellTextTrack | number | undefined
): TableCellTextRun[] | undefined {
  if (track == null) return undefined;
  const items = Array.isArray(track) ? track : [track];
  const runs: TableCellTextRun[] = [];
  for (const item of items) {
    if (runs.length >= TABLE_CELL_TEXT_RUN_LIMIT) break;
    const text = trackText(item);
    if (text === undefined) continue;
    runs.push(
      typeof item === 'object' && item !== null && 'color' in item && item.color
        ? { text, color: item.color }
        : { text }
    );
  }
  return runs.length ? runs : undefined;
}

/** Map wrap / maxLines onto wrap-to-track geometry and a line clamp. */
export function resolveTableCellTextOverflow(
  source: { wrap?: boolean; maxLines?: TableCellMaxLines },
  column: TableColumn
): { wraps: boolean; lineClamp: TableCellLineClamp } {
  const wrap = source.wrap ?? column.wrap ?? false;
  const maxLines = source.maxLines ?? (source.wrap === true ? undefined : column.maxLines);
  if (maxLines != null) {
    return { wraps: maxLines > 1, lineClamp: maxLines };
  }
  if (wrap) return { wraps: true, lineClamp: 'none' };
  return { wraps: false, lineClamp: 1 };
}

/** ds-text overflow props for a resolved clamp. */
export function tableCellTextOverflowProps(lineClamp: TableCellLineClamp): {
  lineTruncation: TableCellLineClamp;
  wrap: 'wrap' | 'nowrap';
} {
  if (lineClamp === 'none') return { lineTruncation: 'none', wrap: 'wrap' };
  if (lineClamp === 1) return { lineTruncation: 1, wrap: 'nowrap' };
  return { lineTruncation: lineClamp, wrap: 'wrap' };
}

function resolveTextPresentation(
  source: {
    primary: string | number;
    secondary?: TableCellTextTrack | number;
    tertiary?: TableCellTextTrack;
    secondaryColor?: TextColor;
    tertiaryColor?: TextColor;
    href?: string;
    target?: TableCellLinkTarget;
    wrap?: boolean;
    maxLines?: TableCellMaxLines;
    fontFeature?: 'normal' | 'tabular-nums';
  },
  column: TableColumn,
  options: { primaryText: boolean; allowTertiary: boolean }
): {
  value: ResolvedTableCellText;
  singleLine: boolean;
  variant: 'single' | 'multi' | 'triple' | 'primary-pair';
  wraps: boolean;
  lineClamp: TableCellLineClamp;
} {
  const secondary = normalizeTableCellTextTrack(source.secondary);
  const tertiary = options.allowTertiary ? normalizeTableCellTextTrack(source.tertiary) : undefined;
  const value: ResolvedTableCellText = {
    primary: source.primary,
    ...(secondary ? { secondary } : {}),
    ...(tertiary ? { tertiary } : {}),
    ...(source.secondaryColor ? { secondaryColor: source.secondaryColor } : {}),
    ...(source.tertiaryColor ? { tertiaryColor: source.tertiaryColor } : {}),
    ...(source.href ? { href: source.href } : {}),
    ...(source.target ? { target: source.target } : {}),
    ...(source.wrap ? { wrap: source.wrap } : {}),
    ...(source.fontFeature ? { fontFeature: source.fontFeature } : {}),
  };
  const singleLine = !options.primaryText && !secondary && !tertiary;
  const overflow = resolveTableCellTextOverflow(source, column);
  return {
    value,
    singleLine,
    variant: options.primaryText
      ? 'primary-pair'
      : tertiary
        ? 'triple'
        : singleLine
          ? 'single'
          : 'multi',
    wraps: overflow.wraps,
    lineClamp: overflow.lineClamp,
  };
}

/** Resolve a cell's semantic and visual recipe once for both markup and classes. */
export function resolveTableCellPresentation(
  value: TableCellValue,
  column: TableColumn
): TableCellPresentation {
  if (isTableCellBlank(value)) return { kind: 'blank', cellType: 'blank', value };
  if (value == null || isTableCellEmpty(value)) {
    return { kind: 'empty', cellType: 'empty', value };
  }
  if (isTableCellIcon(value)) return { kind: 'icon', cellType: 'icon', value };
  if (isTableCellIconText(value)) {
    const text = resolveTextPresentation(value, column, {
      primaryText: false,
      allowTertiary: true,
    });
    return {
      kind: 'icon-text',
      cellType: 'icon-text',
      icon: value.icon,
      ...(value.iconColor ? { iconColor: value.iconColor } : {}),
      ...(value.iconLabel ? { iconLabel: value.iconLabel } : {}),
      value: text.value,
      variant: text.variant === 'primary-pair' ? 'single' : text.variant,
      wraps: text.wraps,
      lineClamp: text.lineClamp,
    };
  }
  if (isTableCellImage(value)) {
    return {
      kind: 'image',
      cellType: 'image',
      value,
      variant: tableCellImageVariant(resolveTableCellImageTracks(value.tracks)),
    };
  }
  if (isTableCellAction(value)) return { kind: 'action', cellType: 'action', value };
  if (isTableCellTag(value)) {
    return {
      kind: 'tag',
      cellType: 'tag',
      value,
      variant: value.variant ?? 'tag-only',
    };
  }
  if (isTableCellTags(value)) {
    const tracks = resolveTableCellTagsTracks(value.tracks);
    return {
      kind: 'tags',
      cellType: 'tags',
      value,
      tracks,
      variant: `${tracks}-track`,
    };
  }

  const primaryText = isTableCellPrimaryText(value);
  const source =
    isTableCellText(value) || primaryText
      ? value
      : {
          primary: value,
          fontFeature: typeof value === 'number' ? ('tabular-nums' as const) : ('normal' as const),
        };
  const text = resolveTextPresentation(isTableCellText(value) ? value : source, column, {
    primaryText,
    allowTertiary: isTableCellText(value),
  });
  return {
    kind: 'text',
    cellType: primaryText ? 'primary-text' : 'text',
    value: text.value,
    primaryText,
    singleLine: text.singleLine,
    variant: text.variant,
    wraps: text.wraps,
    lineClamp: text.lineClamp,
  };
}

import type { MenuItemData } from '../Menu/menu-types';
import type { TableColumn } from './table-types';

let columnCustomizerSeq = 0;

export function nextTableColumnCustomizerElementId(): string {
  columnCustomizerSeq += 1;
  return `ds-table-column-customizer-${columnCustomizerSeq}`;
}

export function isTableActionColumn(column: TableColumn): boolean {
  return column.kind === 'action';
}

export function tableColumnCustomizerLabel(column: TableColumn): string {
  return column.header.trim() || column.headerLabel?.trim() || column.id;
}

export function tableDataColumns(columns: TableColumn[]): TableColumn[] {
  return columns.filter(column => !isTableActionColumn(column));
}

/** Data-column ids in display order. Unknown, duplicate, and action ids are ignored. */
export function resolveTableColumnOrder(
  columns: TableColumn[],
  columnOrder: string[] | undefined
): string[] {
  const catalogIds = tableDataColumns(columns).map(column => column.id);
  const catalog = new Set(catalogIds);
  const seen = new Set<string>();
  const ordered: string[] = [];

  for (const id of columnOrder ?? []) {
    if (!catalog.has(id) || seen.has(id)) continue;
    seen.add(id);
    ordered.push(id);
  }

  for (const id of catalogIds) {
    if (seen.has(id)) continue;
    ordered.push(id);
  }

  return ordered;
}

/**
 * Hidden data-column ids. Action and unknown ids are dropped. At least one data
 * column remains visible when the catalog has any data columns.
 */
export function resolveTableHiddenColumnIds(
  columns: TableColumn[],
  hiddenColumnIds: string[] | undefined
): string[] {
  const dataIds = tableDataColumns(columns).map(column => column.id);
  const data = new Set(dataIds);
  const hidden = [...new Set((hiddenColumnIds ?? []).filter(id => data.has(id)))];
  if (dataIds.length === 0 || hidden.length < dataIds.length) return hidden;

  const keep = dataIds[0];
  return hidden.filter(id => id !== keep);
}

export function resolveTableVisibleColumns(
  columns: TableColumn[],
  options: {
    columnCustomizer?: boolean;
    hiddenColumnIds?: string[];
    columnOrder?: string[];
  } = {}
): TableColumn[] {
  if (!options.columnCustomizer) return columns;

  const byId = new Map(columns.map(column => [column.id, column]));
  const hidden = new Set(resolveTableHiddenColumnIds(columns, options.hiddenColumnIds));
  const visibleData = resolveTableColumnOrder(columns, options.columnOrder)
    .map(id => byId.get(id))
    .filter((column): column is TableColumn => !!column && !hidden.has(column.id));

  return [...visibleData, ...columns.filter(isTableActionColumn)];
}

export function canToggleTableColumnHidden(
  columns: TableColumn[],
  hiddenColumnIds: string[] | undefined,
  columnId: string
): boolean {
  const column = columns.find(candidate => candidate.id === columnId);
  if (!column || isTableActionColumn(column)) return false;

  const hidden = new Set(resolveTableHiddenColumnIds(columns, hiddenColumnIds));
  if (hidden.has(columnId)) return true;

  const visibleData = tableDataColumns(columns).filter(candidate => !hidden.has(candidate.id));
  return visibleData.length > 1;
}

export function toggleTableColumnHidden(
  columns: TableColumn[],
  hiddenColumnIds: string[] | undefined,
  columnId: string
): string[] {
  const resolved = resolveTableHiddenColumnIds(columns, hiddenColumnIds);
  if (!canToggleTableColumnHidden(columns, resolved, columnId)) return resolved;

  const hidden = new Set(resolved);
  if (hidden.has(columnId)) hidden.delete(columnId);
  else hidden.add(columnId);
  return resolveTableHiddenColumnIds(columns, [...hidden]);
}

export function moveTableColumnOrder(order: string[], fromId: string, toId: string): string[] {
  const from = order.indexOf(fromId);
  const to = order.indexOf(toId);
  if (from < 0 || to < 0 || from === to) return order;

  const next = [...order];
  next.splice(from, 1);
  next.splice(to, 0, fromId);
  return next;
}

export function moveTableColumnInOrder(
  order: string[],
  columnId: string,
  offset: number
): string[] {
  const from = order.indexOf(columnId);
  if (from < 0 || offset === 0) return order;
  return moveTableColumnOrder(order, columnId, order[from + offset] ?? columnId);
}

export interface TableColumnCustomizerItem {
  column: TableColumn;
  label: string;
  visible: boolean;
  hideable: boolean;
  reorderable: boolean;
}

export function tableColumnCustomizerItems(
  columns: TableColumn[],
  hiddenColumnIds: string[] | undefined,
  columnOrder: string[] | undefined
): TableColumnCustomizerItem[] {
  const byId = new Map(columns.map(column => [column.id, column]));
  const resolvedHidden = resolveTableHiddenColumnIds(columns, hiddenColumnIds);
  const hidden = new Set(resolvedHidden);
  const dataItems = resolveTableColumnOrder(columns, columnOrder).flatMap(id => {
    const column = byId.get(id);
    if (!column) return [];
    return [
      {
        column,
        label: tableColumnCustomizerLabel(column),
        visible: !hidden.has(id),
        hideable: canToggleTableColumnHidden(columns, resolvedHidden, id),
        reorderable: true,
      },
    ];
  });
  return dataItems;
}

/** Menu switch rows for the table-owned column customizer. */
export function tableColumnCustomizerMenuItems(
  columns: TableColumn[],
  hiddenColumnIds: string[] | undefined,
  columnOrder: string[] | undefined
): MenuItemData[] {
  return tableColumnCustomizerItems(columns, hiddenColumnIds, columnOrder).map(item => ({
    label: item.label,
    value: item.column.id,
    showSwitch: true,
    switchValue: item.visible,
    isInactive: !item.hideable,
    reorderable: item.reorderable,
  }));
}

import type { MenuItemData } from '../Menu/menu-types';
import type { TableDataMode } from './table-types';

let tableDataModeSwitcherSequence = 0;

export function nextTableDataModeSwitcherElementId(): string {
  tableDataModeSwitcherSequence += 1;
  return `ds-table-data-mode-${tableDataModeSwitcherSequence}`;
}

/** Menu of supported data-mode choices. */
export function tableDataModeMenuItems(
  dataMode: TableDataMode,
  labels: { infinite: string; pagination: string; virtual: string }
): MenuItemData[] {
  return [
    {
      label: labels.infinite,
      value: 'infinite',
      isSelected: dataMode === 'infinite',
    },
    {
      label: labels.pagination,
      value: 'pagination',
      isSelected: dataMode === 'pagination',
    },
    {
      label: labels.virtual,
      value: 'virtual',
      isSelected: dataMode === 'virtual',
    },
  ];
}

export function tableDataModeFromMenuItem(item: MenuItemData): TableDataMode | null {
  return item.value === 'infinite' || item.value === 'pagination' || item.value === 'virtual'
    ? item.value
    : null;
}

import type {
  TableGroup,
  TableGroupLoadMoreDetail,
  TableLoadMoreMode,
  TableLoadMoreReason,
} from './table-types';

export interface TableGroupLoadControllerState {
  enabled: boolean;
  loadMoreMode: TableLoadMoreMode;
  loadMoreThreshold: number;
  containedScroll: boolean;
  groups: TableGroup[];
  viewport: HTMLElement | null;
  sentinels: ReadonlyMap<string, HTMLElement>;
  loadingMoreLabel: string;
  endOfResultsLabel: string;
  rowsLoadedLabel: string;
}

export interface TableGroupLoadControllerOptions {
  state: () => TableGroupLoadControllerState;
  announce: (message: string) => void;
  request: (detail: TableGroupLoadMoreDetail) => void;
}

interface GroupSnapshot {
  count: number;
  hasMore: boolean;
  loading: boolean;
  error: string;
  identity: string | number;
}

function groupIdentity(group: TableGroup): string | number {
  return group.loadIdentity ?? group.id;
}

function formatGroupLabel(template: string, group: TableGroup, count?: number): string {
  return template
    .split('{group}')
    .join(group.label)
    .split('{count}')
    .join(String(count ?? group.rows.length))
    .split('{loaded}')
    .join(String(group.rows.length))
    .split('{total}')
    .join(String(group.totalCount ?? group.rows.length));
}

/** Owns request guards, announcements, and observation for independently loaded groups. */
export class TableGroupLoadController {
  readonly intersectionSupported = typeof IntersectionObserver !== 'undefined';

  private connected = false;
  private intersectionObserver: IntersectionObserver | null = null;
  private snapshots = new Map<string, GroupSnapshot>();
  private pending = new Map<string, { identity: string | number; count: number }>();

  constructor(private readonly options: TableGroupLoadControllerOptions) {}

  initialize(): void {
    this.snapshots = this.createSnapshots();
  }

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    this.disconnectObserver();
  }

  refresh(): void {
    if (!this.connected) return;
    const state = this.options.state();
    if (
      !state.enabled ||
      state.loadMoreMode !== 'auto' ||
      !this.intersectionSupported ||
      !state.viewport
    ) {
      this.disconnectObserver();
      return;
    }

    this.disconnectObserver();
    const threshold = Number.isFinite(state.loadMoreThreshold)
      ? Math.max(0, state.loadMoreThreshold)
      : 0;
    this.intersectionObserver = new IntersectionObserver(
      entries => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          const groupId = (entry.target as HTMLElement).dataset.groupId;
          if (groupId) this.request(groupId, 'auto');
        }
      },
      {
        root: state.containedScroll ? state.viewport : null,
        rootMargin: `0px 0px ${threshold}px 0px`,
      }
    );

    for (const [groupId, sentinel] of state.sentinels) {
      const group = state.groups.find(item => item.id === groupId);
      if (!group?.hasMore || group.loadingMore || group.loadMoreError?.trim()) continue;
      this.intersectionObserver.observe(sentinel);
    }
  }

  structureChanged(): void {
    this.pending.clear();
    this.snapshots = this.createSnapshots();
    this.disconnectObserver();
  }

  dataChanged(): void {
    const state = this.options.state();
    const nextSnapshots = new Map<string, GroupSnapshot>();

    for (const group of state.groups) {
      const next = this.snapshot(group);
      const previous = this.snapshots.get(group.id);
      const pending = this.pending.get(group.id);

      if (!previous || previous.identity !== next.identity) {
        this.pending.delete(group.id);
      } else {
        if (next.count > previous.count) {
          this.options.announce(
            formatGroupLabel(state.rowsLoadedLabel, group, next.count - previous.count)
          );
        }
        if (!previous.error && next.error) {
          this.pending.delete(group.id);
          this.options.announce(next.error);
        }
        if (previous.hasMore && !next.hasMore) {
          this.pending.delete(group.id);
          this.options.announce(formatGroupLabel(state.endOfResultsLabel, group));
        }
        if (pending && next.count > pending.count) this.pending.delete(group.id);
        if (pending && previous.loading && !next.loading && next.count === pending.count) {
          this.pending.delete(group.id);
        }
      }

      nextSnapshots.set(group.id, next);
    }

    this.snapshots = nextSnapshots;
    for (const groupId of this.pending.keys()) {
      if (!nextSnapshots.has(groupId)) this.pending.delete(groupId);
    }
    this.disconnectObserver();
  }

  configurationChanged(): void {
    this.disconnectObserver();
  }

  request(groupId: string, reason: TableLoadMoreReason): void {
    const state = this.options.state();
    const group = state.groups.find(item => item.id === groupId);
    if (
      !state.enabled ||
      !group?.hasMore ||
      group.loadingMore ||
      (reason !== 'retry' && !!group.loadMoreError?.trim()) ||
      this.pending.has(groupId)
    )
      return;

    const identity = groupIdentity(group);
    this.pending.set(groupId, { identity, count: group.rows.length });
    this.options.announce(formatGroupLabel(state.loadingMoreLabel, group));
    this.options.request({
      groupId,
      reason,
      loadIdentity: identity,
      loadedRowCount: group.rows.length,
    });
  }

  private createSnapshots(): Map<string, GroupSnapshot> {
    return new Map(this.options.state().groups.map(group => [group.id, this.snapshot(group)]));
  }

  private snapshot(group: TableGroup): GroupSnapshot {
    return {
      count: group.rows.length,
      hasMore: !!group.hasMore,
      loading: !!group.loadingMore,
      error: group.loadMoreError?.trim() ?? '',
      identity: groupIdentity(group),
    };
  }

  private disconnectObserver(): void {
    this.intersectionObserver?.disconnect();
    this.intersectionObserver = null;
  }
}

export interface TableHighlightSegment {
  text: string;
  match: boolean;
}

export type TableHighlightMatcher = (value: string | number) => TableHighlightSegment[];

export const TABLE_NO_HIGHLIGHT_MATCHER: TableHighlightMatcher = value => [
  { text: String(value), match: false },
];

const escapeRegExp = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * Creates one literal, case-insensitive matcher for table-owned text tracks.
 * Longer terms win when supplied terms overlap.
 */
export function createTableHighlightMatcher(terms: string[]): TableHighlightMatcher {
  const normalizedTerms = Array.from(
    new Map(
      terms
        .map(term => term.trim())
        .filter(Boolean)
        .map(term => [term.toLocaleLowerCase(), term])
    ).values()
  ).sort((left, right) => right.length - left.length);

  if (!normalizedTerms.length) {
    return TABLE_NO_HIGHLIGHT_MATCHER;
  }

  const expression = new RegExp(normalizedTerms.map(escapeRegExp).join('|'), 'giu');

  return value => {
    const text = String(value);
    const segments: TableHighlightSegment[] = [];
    let cursor = 0;

    expression.lastIndex = 0;
    for (const match of text.matchAll(expression)) {
      const index = match.index;
      if (index > cursor) segments.push({ text: text.slice(cursor, index), match: false });
      segments.push({ text: match[0], match: true });
      cursor = index + match[0].length;
    }

    if (!segments.length) return [{ text, match: false }];
    if (cursor < text.length) segments.push({ text: text.slice(cursor), match: false });
    return segments;
  };
}

export interface TableLayoutElements {
  viewport: HTMLElement | null;
  contentTable: HTMLTableElement | null;
  stickyHeaderTable: HTMLTableElement | null;
  collapseAllOverlay: HTMLElement | null;
  frame: HTMLElement | null;
  interactiveHead: HTMLTableSectionElement | null;
}

export interface TableLayoutMode {
  documentStickyHeader: boolean;
  floatingCollapseAll: boolean;
  clampVerticalOverscroll: boolean;
}

export interface TableOverflowState {
  start: boolean;
  end: boolean;
  scrollable: boolean;
}

export interface TableLayoutControllerOptions {
  elements: () => TableLayoutElements;
  mode: () => TableLayoutMode;
  overflowChanged: (state: TableOverflowState) => void;
  verticalEdgeWheel?: (deltaY: number) => boolean;
}

export interface TableLayoutMetricInput {
  viewportInlineSize: number;
  viewportBlockSize: number;
  scrollInlineSize: number;
  scrollBlockSize: number;
  scrollInlineOffset: number;
  collapseHeadBlockStart?: number;
  collapseFrameBlockStart?: number;
}

export interface TableLayoutMetrics {
  visibleInlineSize: number;
  overflow: TableOverflowState;
  inlineOffset: number;
  maxInlineOffset: number;
  collapseBlockOffset: number | null;
}

/** Pure geometry resolution shared by the controller and focused tests. */
export function resolveTableLayoutMetrics(input: TableLayoutMetricInput): TableLayoutMetrics {
  const horizontalOverflow = input.scrollInlineSize - input.viewportInlineSize > 1;
  return {
    visibleInlineSize: input.viewportInlineSize,
    overflow: {
      start: horizontalOverflow && input.scrollInlineOffset > 1,
      end:
        horizontalOverflow &&
        input.scrollInlineOffset + input.viewportInlineSize < input.scrollInlineSize - 1,
      scrollable: horizontalOverflow || input.scrollBlockSize - input.viewportBlockSize > 1,
    },
    inlineOffset: input.scrollInlineOffset,
    maxInlineOffset: Math.max(0, input.scrollInlineSize - input.viewportInlineSize),
    collapseBlockOffset:
      input.collapseHeadBlockStart == null || input.collapseFrameBlockStart == null
        ? null
        : Math.max(0, input.collapseHeadBlockStart - input.collapseFrameBlockStart),
  };
}

/**
 * Owns table viewport observation. It resolves newly rendered geometry
 * immediately so the first paint has the correct viewport-width chrome, then
 * batches observer-driven scroll and resize reads/writes into one animation frame.
 * The component remains responsible only for refs and reactive overflow state.
 */
export class TableLayoutController {
  private connected = false;
  private connectedViewport: HTMLElement | null = null;
  private connectedContentTable: HTMLTableElement | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private frame: number | null = null;
  private overflow: TableOverflowState | null = null;
  private inlineOffset = 0;
  private maxInlineOffset = 0;
  private maxBlockOffset = 0;
  private lastMode: TableLayoutMode | null = null;

  constructor(private readonly options: TableLayoutControllerOptions) {}

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    if (this.frame !== null) cancelAnimationFrame(this.frame);
    this.frame = null;
    this.connectedViewport?.removeEventListener('scroll', this.handleScroll);
    this.connectedViewport?.removeEventListener('wheel', this.handleWheel);
    this.connectedViewport = null;
    this.connectedContentTable = null;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
  }

  /** Reconcile newly rendered refs, observers, and pending geometry. */
  refresh(forceGeometry = true): void {
    if (!this.connected) return;
    const { viewport, contentTable } = this.options.elements();
    const elementsChanged =
      viewport !== this.connectedViewport || contentTable !== this.connectedContentTable;
    if (elementsChanged) {
      this.connectedViewport?.removeEventListener('scroll', this.handleScroll);
      this.connectedViewport?.removeEventListener('wheel', this.handleWheel);
      this.resizeObserver?.disconnect();
      this.connectedViewport = viewport;
      this.connectedContentTable = contentTable;
      viewport?.addEventListener('scroll', this.handleScroll, { passive: true });
      viewport?.addEventListener('wheel', this.handleWheel, { passive: false });

      if (typeof ResizeObserver !== 'undefined' && viewport) {
        this.resizeObserver ??= new ResizeObserver(this.schedule);
        this.resizeObserver.observe(viewport);
        if (contentTable) this.resizeObserver.observe(contentTable);
      }
    }
    const mode = this.options.mode();
    const modeChanged =
      !this.lastMode ||
      mode.documentStickyHeader !== this.lastMode.documentStickyHeader ||
      mode.floatingCollapseAll !== this.lastMode.floatingCollapseAll ||
      mode.clampVerticalOverscroll !== this.lastMode.clampVerticalOverscroll;
    this.lastMode = mode;
    // New refs and explicit refreshes resolve before paint. A recycled virtual
    // window keeps the same scroll geometry, so ResizeObserver owns later size
    // changes without forcing layout after every row patch.
    if (forceGeometry || elementsChanged || modeChanged) this.sync();
  }

  private schedule = (): void => {
    if (!this.connected || this.frame !== null) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = null;
      this.sync();
    });
  };

  private readonly handleScroll = (): void => {
    const viewport = this.connectedViewport;
    if (!viewport) return;
    const mode = this.options.mode();
    this.clampInlineOffset();
    if (mode.clampVerticalOverscroll) this.clampBlockOffset();
    if (
      viewport.scrollLeft !== this.inlineOffset ||
      (mode.floatingCollapseAll && !mode.documentStickyHeader)
    ) {
      this.schedule();
    }
  };

  private readonly handleWheel = (event: WheelEvent): void => {
    const viewport = this.connectedViewport;
    if (!viewport) return;

    if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) {
      const atStart = viewport.scrollLeft <= 0 && event.deltaX < 0;
      const atEnd = viewport.scrollLeft >= this.maxInlineOffset && event.deltaX > 0;
      if (atStart || atEnd) event.preventDefault();
      return;
    }

    if (!this.options.mode().clampVerticalOverscroll || event.deltaY === 0) return;
    const atStart = viewport.scrollTop <= 0 && event.deltaY < 0;
    const atEnd = viewport.scrollTop >= this.maxBlockOffset && event.deltaY > 0;
    if (!atStart && !atEnd) return;

    this.options.verticalEdgeWheel?.(event.deltaY);
    event.preventDefault();
  };

  private clampInlineOffset(): void {
    const viewport = this.connectedViewport;
    if (!viewport) return;
    const clamped = Math.min(this.maxInlineOffset, Math.max(0, viewport.scrollLeft));
    if (viewport.scrollLeft !== clamped) viewport.scrollLeft = clamped;
  }

  private clampBlockOffset(): void {
    const viewport = this.connectedViewport;
    if (!viewport) return;
    const clamped = Math.min(this.maxBlockOffset, Math.max(0, viewport.scrollTop));
    if (viewport.scrollTop !== clamped) viewport.scrollTop = clamped;
  }

  private sync(): void {
    const elements = this.options.elements();
    const viewport = elements.viewport;
    if (!viewport) return;

    // Read every layout value before writing styles or reactive state.
    const mode = this.options.mode();
    const measureCollapse =
      mode.floatingCollapseAll &&
      !mode.documentStickyHeader &&
      elements.collapseAllOverlay &&
      elements.frame &&
      elements.interactiveHead;
    const metrics = resolveTableLayoutMetrics({
      viewportInlineSize: viewport.clientWidth,
      viewportBlockSize: viewport.clientHeight,
      scrollInlineSize: viewport.scrollWidth,
      scrollBlockSize: viewport.scrollHeight,
      scrollInlineOffset: viewport.scrollLeft,
      collapseHeadBlockStart: measureCollapse
        ? elements.interactiveHead!.getBoundingClientRect().top
        : undefined,
      collapseFrameBlockStart: measureCollapse
        ? elements.frame!.getBoundingClientRect().top
        : undefined,
    });
    this.inlineOffset = metrics.inlineOffset;
    this.maxInlineOffset = metrics.maxInlineOffset;
    this.maxBlockOffset = Math.max(0, viewport.scrollHeight - viewport.clientHeight);

    this.setProperty(viewport, '--ds-table-visible-inline-size', `${metrics.visibleInlineSize}px`);
    if (elements.stickyHeaderTable) {
      this.setProperty(
        elements.stickyHeaderTable,
        '--ds-table-inline-scroll-offset',
        `${metrics.inlineOffset}px`
      );
      this.setProperty(
        elements.stickyHeaderTable,
        '--ds-table-inline-scroll-max-offset',
        `${metrics.maxInlineOffset}px`
      );
    }
    if (metrics.collapseBlockOffset !== null && elements.collapseAllOverlay) {
      this.setProperty(
        elements.collapseAllOverlay,
        '--ds-table-collapse-all-block-offset',
        `${metrics.collapseBlockOffset}px`
      );
    }

    if (
      !this.overflow ||
      this.overflow.start !== metrics.overflow.start ||
      this.overflow.end !== metrics.overflow.end ||
      this.overflow.scrollable !== metrics.overflow.scrollable
    ) {
      this.overflow = metrics.overflow;
      this.options.overflowChanged(metrics.overflow);
    }
  }

  private setProperty(element: HTMLElement, property: string, value: string): void {
    if (element.style.getPropertyValue(property) !== value) {
      element.style.setProperty(property, value);
    }
  }
}

import type { TableLoadMoreDetail, TableLoadMoreMode, TableLoadMoreReason } from './table-types';

export interface TableLoadControllerState {
  lazyLoading: boolean;
  loadMoreMode: TableLoadMoreMode;
  hasMore: boolean;
  loadingMore: boolean;
  loadMoreError: string | undefined;
  loadIdentity: string | number;
  loadMoreThreshold: number;
  containedScroll: boolean;
  loadingMoreLabel: string;
  endOfResultsLabel: string;
  rowsLoadedLabel: string;
  loadedRowCount: number;
  viewport: HTMLElement | null;
  sentinel: HTMLElement | null;
}

export interface TableLoadControllerOptions {
  state: () => TableLoadControllerState;
  announce: (message: string) => void;
  request: (detail: TableLoadMoreDetail) => void;
}

/** Owns incremental-loading request guards, announcements, and observation. */
export class TableLoadController {
  readonly intersectionSupported = typeof IntersectionObserver !== 'undefined';

  private connected = false;
  private intersectionObserver: IntersectionObserver | null = null;
  private observedSentinel: HTMLElement | null = null;
  private requestPending = false;
  private requestedRowCount = 0;
  private previousLoadedRowCount = 0;

  constructor(private readonly options: TableLoadControllerOptions) {}

  initialize(): void {
    this.previousLoadedRowCount = this.options.state().loadedRowCount;
  }

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    this.disconnectObserver();
  }

  refresh(): void {
    if (!this.connected) return;
    const state = this.options.state();
    if (
      !state.lazyLoading ||
      state.loadMoreMode !== 'auto' ||
      !state.hasMore ||
      !!state.loadMoreError?.trim() ||
      !this.intersectionSupported ||
      !state.viewport ||
      !state.sentinel
    ) {
      this.disconnectObserver();
      return;
    }

    if (this.intersectionObserver && this.observedSentinel === state.sentinel) return;
    this.disconnectObserver();
    const threshold = Number.isFinite(state.loadMoreThreshold)
      ? Math.max(0, state.loadMoreThreshold)
      : 0;
    this.intersectionObserver = new IntersectionObserver(
      entries => {
        if (entries.some(entry => entry.isIntersecting)) this.request('auto');
      },
      {
        root: state.containedScroll ? state.viewport : null,
        rootMargin: `0px 0px ${threshold}px 0px`,
      }
    );
    this.observedSentinel = state.sentinel;
    this.intersectionObserver.observe(state.sentinel);
  }

  structureChanged(): void {
    this.resetRequest();
  }

  dataChanged(): void {
    const state = this.options.state();
    const nextCount = state.loadedRowCount;
    if (!state.lazyLoading) {
      this.previousLoadedRowCount = nextCount;
      this.resetRequest();
      return;
    }
    if (nextCount > this.previousLoadedRowCount) {
      const added = nextCount - this.previousLoadedRowCount;
      this.options.announce(
        state.rowsLoadedLabel
          .replace('{count}', String(added))
          .replace('{total}', String(nextCount))
      );
    }
    if (nextCount > this.requestedRowCount) this.requestPending = false;
    this.previousLoadedRowCount = nextCount;
    this.disconnectObserver();
  }

  identityChanged(): void {
    this.previousLoadedRowCount = this.options.state().loadedRowCount;
    this.resetRequest();
  }

  configurationChanged(): void {
    this.disconnectObserver();
  }

  loadingChanged(loading: boolean): void {
    const state = this.options.state();
    if (!state.lazyLoading) {
      this.resetRequest();
      return;
    }
    if (loading) {
      this.requestPending = true;
      this.options.announce(state.loadingMoreLabel);
    } else if (state.loadMoreMode === 'manual') {
      // A completed manual request may append no rows; permit another explicit activation.
      this.requestPending = false;
    }
    this.disconnectObserver();
  }

  errorChanged(error: string | undefined): void {
    if (!this.options.state().lazyLoading) {
      this.resetRequest();
      return;
    }
    if (error?.trim()) {
      this.requestPending = false;
      this.options.announce(error);
    }
    this.disconnectObserver();
  }

  hasMoreChanged(hasMore: boolean, hadMore: boolean): void {
    if (!this.options.state().lazyLoading) {
      this.resetRequest();
      return;
    }
    if (!hasMore) {
      this.requestPending = false;
      if (hadMore) this.options.announce(this.options.state().endOfResultsLabel);
    }
    this.disconnectObserver();
  }

  request(reason: TableLoadMoreReason): void {
    const state = this.options.state();
    if (
      !state.lazyLoading ||
      !state.hasMore ||
      state.loadingMore ||
      (reason !== 'retry' && !!state.loadMoreError?.trim()) ||
      this.requestPending
    )
      return;

    this.requestPending = true;
    this.requestedRowCount = state.loadedRowCount;
    this.options.announce(state.loadingMoreLabel);
    this.options.request({
      reason,
      loadIdentity: state.loadIdentity,
      loadedRowCount: this.requestedRowCount,
    });
  }

  private resetRequest(): void {
    this.requestPending = false;
    this.requestedRowCount = this.options.state().loadedRowCount;
    this.disconnectObserver();
  }

  private disconnectObserver(): void {
    this.intersectionObserver?.disconnect();
    this.intersectionObserver = null;
    this.observedSentinel = null;
  }
}

import { h } from '@stencil/core';

interface TableLoadContentOptions {
  error?: string;
  loading: boolean;
  hasMore: boolean;
  manualFallback: boolean;
  retryLabel: string;
  loadingLabel: string;
  loadMoreLabel: string;
  loadMoreAriaLabel?: string;
  endOfResultsLabel?: string;
  onRetry: () => void;
  onLoadMore: () => void;
}

/** Shared visible state machine for top-level and per-group incremental loading bands. */
export function renderTableLoadContent(options: TableLoadContentOptions) {
  if (options.error) {
    return (
      <span class="ds-table__load-content ds-table__load-content--error">
        <span class="ds-table__load-copy">
          <ds-icon name="ErrorTriangle" size="md" color="secondary" aria-hidden="true" />
          <ds-text as="span" variant="text-body-medium" color="secondary">
            {options.error}
          </ds-text>
        </span>
        <ds-button-unfilled label={options.retryLabel} size="md" onDsClick={options.onRetry} />
      </span>
    );
  }

  if (options.loading) {
    return (
      <span class="ds-table__load-content">
        <ds-loader size="md" color="secondary" />
        <ds-text as="span" variant="text-body-medium" color="secondary">
          {options.loadingLabel}
        </ds-text>
      </span>
    );
  }

  if (options.hasMore && options.manualFallback) {
    return (
      <span class="ds-table__load-content">
        <ds-button-unfilled
          label={options.loadMoreLabel}
          aria-label={options.loadMoreAriaLabel}
          size="md"
          onDsClick={options.onLoadMore}
        />
      </span>
    );
  }

  if (options.hasMore) return <span class="ds-table__auto-sentinel" aria-hidden="true" />;
  if (!options.endOfResultsLabel) return null;
  return (
    <ds-text class="ds-table__load-content" as="span" variant="text-body-medium" color="secondary">
      {options.endOfResultsLabel}
    </ds-text>
  );
}

import type {
  TableCellBlank,
  TableCellAction,
  TableCellEmpty,
  TableCellIcon,
  TableCellIconText,
  TableCellImage,
  TableCellPrimaryText,
  TableCellText,
  TableCellTag,
  TableCellTags,
  TableCellValue,
  TableColumn,
  TableGroup,
  TableRow,
  TableSortState,
} from './table-types';

export interface TableSelectionState {
  selectableRowIds: string[];
  selectedLoadedCount: number;
  allSelected: boolean;
  indeterminate: boolean;
}

const TABLE_COLUMN_WIDTH_TOKENS = {
  xs: '--dimension-table-column-width-xs',
  sm: '--dimension-table-column-width-sm',
  md: '--dimension-table-column-width-md',
  lg: '--dimension-table-column-width-lg',
  xl: '--dimension-table-column-width-xl',
} as const;

const TABLE_IMAGE_COLUMN_WIDTH_VARIABLES = {
  1: '--_table-image-column-inline-size',
  2: '--_table-image-column-inline-size-multi',
  3: '--_table-image-column-inline-size-triple',
} as const;

export function isTableCellText(value: TableCellValue): value is TableCellText {
  return typeof value === 'object' && value !== null && 'primary' in value && !('kind' in value);
}

export function isTableCellPrimaryText(value: TableCellValue): value is TableCellPrimaryText {
  return (
    typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'primary-text'
  );
}

export function isTableCellTag(value: TableCellValue): value is TableCellTag {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'tag';
}

export function isTableCellTags(value: TableCellValue): value is TableCellTags {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'tags';
}

export function isTableCellIcon(value: TableCellValue): value is TableCellIcon {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'icon';
}

export function isTableCellIconText(value: TableCellValue): value is TableCellIconText {
  return (
    typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'icon-text'
  );
}

export function isTableCellImage(value: TableCellValue): value is TableCellImage {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'image';
}

export function isTableCellAction(value: TableCellValue): value is TableCellAction {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'action';
}

export function isTableCellEmpty(value: TableCellValue): value is TableCellEmpty {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'empty';
}

export function isTableCellBlank(value: TableCellValue): value is TableCellBlank {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'blank';
}

export function tableCellPrimary(value: TableCellValue): string | number | null {
  if (value == null) return null;
  if (isTableCellTag(value)) return value.label;
  if (isTableCellTags(value)) return value.items.map(item => item.label).join(', ');
  if (isTableCellIcon(value)) return null;
  if (isTableCellIconText(value)) return value.primary;
  if (isTableCellImage(value)) return value.alt;
  if (isTableCellAction(value)) return value.label ?? value.ariaLabel;
  if (isTableCellPrimaryText(value)) return value.primary;
  if (isTableCellEmpty(value) || isTableCellBlank(value)) return null;
  return isTableCellText(value) ? value.primary : value;
}

export function tableRowSelectionLabel(row: TableRow, columns: TableColumn[]): string {
  const explicit = row.selectionLabel?.trim();
  if (explicit) return explicit;

  for (const column of columns) {
    const primary = tableCellPrimary(row.cells[column.id]);
    if (primary != null && String(primary).trim()) return String(primary);
  }

  return row.id;
}

export function nextTableSortState(
  current: TableSortState | null | undefined,
  columnId: string
): TableSortState {
  if (current?.columnId !== columnId) return { columnId, direction: 'asc' };
  if (current.direction === 'asc') return { columnId, direction: 'desc' };
  return { columnId, direction: 'asc' };
}

export function toggleTableGroupCollapsed(collapsedGroupIds: string[], groupId: string): string[] {
  const next = new Set(collapsedGroupIds);
  if (next.has(groupId)) next.delete(groupId);
  else next.add(groupId);
  return [...next];
}

export function nextTableGroupsCollapsed(
  collapsedGroupIds: string[],
  groupIds: string[]
): string[] {
  if (groupIds.length === 0) return [];
  const collapsed = new Set(collapsedGroupIds);
  const allCollapsed = groupIds.every(id => collapsed.has(id));
  return allCollapsed ? [] : [...groupIds];
}

/** Host for grouped collapse-all: the trailing action lane or a scrollport-owned overlay. */
export type TableCollapseAllHost = { columnId: string; mode: 'action' } | { mode: 'floating' };

export function tableCollapseAllHost(columns: TableColumn[]): TableCollapseAllHost | undefined {
  if (columns.length === 0) return undefined;
  for (let index = columns.length - 1; index >= 0; index -= 1) {
    const column = columns[index]!;
    if (column.kind === 'action') return { columnId: column.id, mode: 'action' };
  }
  return { mode: 'floating' };
}

export function clampTableColumnSize(column: TableColumn): number | undefined {
  if (typeof column.size !== 'number' || !Number.isFinite(column.size) || column.size <= 0) {
    return undefined;
  }

  const minimum =
    Number.isFinite(column.minSize) && (column.minSize ?? 0) > 0 ? column.minSize! : 0;
  const maximum =
    Number.isFinite(column.maxSize) && (column.maxSize ?? 0) > 0
      ? Math.max(column.maxSize!, minimum)
      : Number.POSITIVE_INFINITY;

  return Math.min(Math.max(column.size!, minimum), maximum);
}

export function tableColumnSize(column: TableColumn): string | undefined {
  if (typeof column.size === 'string') {
    return `var(${TABLE_COLUMN_WIDTH_TOKENS[column.size]})`;
  }
  const width = clampTableColumnSize(column);
  if (width != null) return `${width}px`;
  if (column.imageTracks) {
    return `var(${TABLE_IMAGE_COLUMN_WIDTH_VARIABLES[column.imageTracks]})`;
  }
  return column.kind === 'action' ? 'var(--dimension-size-500)' : undefined;
}

/**
 * Fully sized tables add one internal lane that absorbs spare inline space and
 * collapses to zero at the explicit overflow width. Keep trailing action and
 * sticky-end lanes after it so those controls remain at the visible edge.
 */
export function tableElasticSpacerIndex(columns: TableColumn[]): number | undefined {
  if (columns.length === 0 || columns.some(column => !tableColumnSize(column))) return undefined;
  let index = columns.length;
  while (index > 0) {
    const column = columns[index - 1]!;
    if (column.kind !== 'action' && column.sticky !== 'end') break;
    index -= 1;
  }
  return index;
}

export function tableExplicitMinWidth(columns: TableColumn[]): string | undefined {
  const widths = columns.map(tableColumnSize).filter((width): width is string => !!width);
  if (widths.length === 0) return undefined;
  return widths.length === 1 ? widths[0] : `calc(${widths.join(' + ')})`;
}

export function tableRows(rows: TableRow[], groups: TableGroup[], grouped: boolean): TableRow[] {
  return grouped ? groups.flatMap(group => group.rows) : rows;
}

function canSelectRow(row: TableRow): boolean {
  return row.selectable !== false && !row.disabled;
}

export function deriveTableSelectionState(
  rows: TableRow[],
  selectedRowIds: readonly string[]
): TableSelectionState {
  const selected = new Set(selectedRowIds);
  const selectableRowIds = rows.filter(canSelectRow).map(row => row.id);
  const selectedLoadedCount = selectableRowIds.reduce(
    (count, id) => count + (selected.has(id) ? 1 : 0),
    0
  );

  return {
    selectableRowIds,
    selectedLoadedCount,
    allSelected: selectableRowIds.length > 0 && selectedLoadedCount === selectableRowIds.length,
    indeterminate: selectedLoadedCount > 0 && selectedLoadedCount < selectableRowIds.length,
  };
}

export function toggleTableRowSelection(
  selectedRowIds: readonly string[],
  row: TableRow
): string[] {
  if (!canSelectRow(row)) return [...selectedRowIds];
  const selected = new Set(selectedRowIds);
  if (selected.has(row.id)) selected.delete(row.id);
  else selected.add(row.id);
  return [...selected];
}

export function toggleAllLoadedTableRows(
  selectedRowIds: readonly string[],
  loadedRows: TableRow[]
): string[] {
  const selected = new Set(selectedRowIds);
  const state = deriveTableSelectionState(loadedRows, selectedRowIds);

  for (const id of state.selectableRowIds) {
    if (state.allSelected) selected.delete(id);
    else selected.add(id);
  }

  return [...selected];
}

/** Toggle every selectable loaded row that belongs to a group. */
export function toggleTableGroupSelection(
  selectedRowIds: readonly string[],
  groupRows: TableRow[]
): string[] {
  return toggleAllLoadedTableRows(selectedRowIds, groupRows);
}

export function resolvedTableGroupCount(group: TableGroup): number {
  const total = Number.isFinite(group.totalCount) ? Math.max(0, group.totalCount!) : 0;
  return Math.max(total, group.rows.length);
}

export const TABLE_GROUP_INTENTS = [
  'brand',
  'neutral',
  'negative',
  'warning',
  'caution',
  'positive',
] as const;

export function isTableGroupIntent(value: unknown): value is (typeof TABLE_GROUP_INTENTS)[number] {
  return typeof value === 'string' && (TABLE_GROUP_INTENTS as readonly string[]).includes(value);
}

export function tableGroupIntentClass(
  intent: (typeof TABLE_GROUP_INTENTS)[number] | undefined
): string | undefined {
  return isTableGroupIntent(intent) ? `ds-table__group-cell--intent-${intent}` : undefined;
}

/** Title color for an intentful group label; defaults to primary when unset. */
export function tableGroupLabelColor(
  intent: (typeof TABLE_GROUP_INTENTS)[number] | undefined
): 'primary' | 'brand' | 'negative' | 'warning' | 'caution' | 'positive' | `var(--${string})` {
  if (!isTableGroupIntent(intent)) return 'primary';
  if (intent === 'neutral') return 'var(--color-foreground-bold-neutral)';
  return intent;
}

/** Formats the optional table result footer. Returns null when either count is missing. */
export function formatTableResultSummary(
  displayed: number | null | undefined,
  total: number | null | undefined,
  label = 'Displaying {displayed} of {total}',
  locale?: string
): string | null {
  if (!Number.isFinite(displayed) || !Number.isFinite(total)) return null;
  const normalizedTotal = Math.max(0, Math.trunc(total as number));
  const normalizedDisplayed = Math.min(
    normalizedTotal,
    Math.max(0, Math.trunc(displayed as number))
  );
  const formatter = new Intl.NumberFormat(locale);
  return label
    .replace('{displayed}', formatter.format(normalizedDisplayed))
    .replace('{total}', formatter.format(normalizedTotal));
}

/** Formats the virtual-mode total-only result footer. */
export function formatTableTotalSummary(
  total: number | null | undefined,
  label = '{total} items',
  locale?: string
): string | null {
  if (!Number.isFinite(total)) return null;
  const normalizedTotal = Math.max(0, Math.trunc(total as number));
  return label.replace('{total}', new Intl.NumberFormat(locale).format(normalizedTotal));
}

/**
 * True when a footer slot belongs to the table itself: a light-DOM child of the
 * host, or a top-level node Stencil relocated into this table's footer. A
 * slotted ancestor marks a nested component boundary, so dialog action slots
 * inside footer-leading/footer-trailing content cannot replace the table copy.
 */
export function isOwnedTableFooterSlot(node: Element, host: Element): boolean {
  if (node.parentElement === host) return true;
  let insideTableFooter = false;
  for (
    let ancestor = node.parentElement;
    ancestor && ancestor !== host;
    ancestor = ancestor.parentElement
  ) {
    if (ancestor.hasAttribute('slot')) return false;
    if (ancestor.classList.contains('ds-table__footer')) insideTableFooter = true;
  }
  return insideTableFooter;
}

export function hasOwnedTableFooterSlot(host: Element, slotName: string): boolean {
  return [...host.querySelectorAll(`[slot="${slotName}"]`)].some(node =>
    isOwnedTableFooterSlot(node, host)
  );
}

export function tableModelIssues(
  columns: TableColumn[],
  rows: TableRow[],
  groups: TableGroup[],
  grouped: boolean
): string[] {
  const issues: string[] = [];
  const columnIds = new Set<string>();
  for (const column of columns) {
    if (!column.id.trim()) issues.push('Every column requires a non-empty id.');
    else if (columnIds.has(column.id)) issues.push(`Duplicate column id: ${column.id}`);
    if (!column.header.trim() && !column.headerLabel?.trim()) {
      issues.push(
        `Column ${column.id || '(missing id)'} requires a visible header or headerLabel.`
      );
    }
    columnIds.add(column.id);
  }

  const groupIds = new Set<string>();
  if (grouped) {
    for (const group of groups) {
      if (!group.id.trim()) issues.push('Every group requires a non-empty id.');
      else if (groupIds.has(group.id)) issues.push(`Duplicate group id: ${group.id}`);
      groupIds.add(group.id);
      if (group.totalCount != null && group.totalCount < group.rows.length) {
        issues.push(`Group ${group.id} totalCount is smaller than its loaded row count.`);
      }
      if (group.intent != null && !isTableGroupIntent(group.intent)) {
        issues.push(`Group ${group.id} has an unsupported intent.`);
      }
    }
  }

  const rowIds = new Set<string>();
  for (const row of tableRows(rows, groups, grouped)) {
    if (!row.id.trim()) issues.push('Every row requires a non-empty id.');
    else if (rowIds.has(row.id)) issues.push(`Duplicate row id: ${row.id}`);
    rowIds.add(row.id);
  }

  return [...new Set(issues)];
}

export interface TableFitPageSizeInput {
  viewportBlockSize: number;
  headerBlockSize: number;
  itemBlockSize: number;
}

/** Resolve how many complete top-level rows or group headers fit below the column header. */
export function resolveTableFitPageSize(input: TableFitPageSizeInput): number | undefined {
  if (
    !Number.isFinite(input.viewportBlockSize) ||
    !Number.isFinite(input.headerBlockSize) ||
    !Number.isFinite(input.itemBlockSize) ||
    input.viewportBlockSize <= 0 ||
    input.itemBlockSize <= 0
  ) {
    return undefined;
  }
  const availableBlockSize = Math.max(0, input.viewportBlockSize - input.headerBlockSize);
  return Math.max(1, Math.floor((availableBlockSize + 0.5) / input.itemBlockSize));
}

const DIRECTIONAL_TAGS = new Set([
  'DS-SELECT',
  'DS-MENU',
  'DS-FILTER-MENU',
  'INPUT',
  'SELECT',
  'TEXTAREA',
]);

const DIRECTIONAL_ROLES = new Set(['slider', 'combobox', 'listbox']);

interface ShortcutPathNode {
  tagName?: string;
  nodeType?: number;
  isContentEditable?: boolean;
  assignedSlot?: unknown;
  parentNode?: unknown;
  getRootNode?: () => unknown;
  getAttribute?: (name: string) => string | null;
}

/** True when Left/Right should stay with an editable or choice control. */
export function paginationShortcutBlockedByPath(path: readonly unknown[]): boolean {
  return path.some(node => {
    if (!node || typeof node !== 'object') return false;
    const element = node as ShortcutPathNode;
    if (element.tagName && DIRECTIONAL_TAGS.has(element.tagName)) return true;
    if (element.isContentEditable) return true;
    const role = element.getAttribute?.('role');
    return role != null && DIRECTIONAL_ROLES.has(role);
  });
}

export function isDocumentRootNode(node: unknown): boolean {
  if (!node || typeof node !== 'object') return false;
  const element = node as ShortcutPathNode;
  if (element.nodeType === 9) return true;
  return element.tagName === 'BODY' || element.tagName === 'HTML';
}

/** True when `ancestor` contains `descendant` in the composed tree, including slots. */
export function composedContains(ancestor: unknown, descendant: unknown): boolean {
  if (!ancestor || !descendant || ancestor === descendant) return false;
  const seen = new Set<unknown>();
  let current: unknown = descendant;
  while (current && !seen.has(current)) {
    seen.add(current);
    if (current === ancestor) return true;
    current = composedParent(current);
  }
  return false;
}

/**
 * Window-level pagination arrows apply when focus is inside the table or on a
 * containing page scroller (for example ShellApp's routed-content region).
 * Document body stays with the host app so it can forward a single event.
 */
export function shouldHandleContainingPagePaginationShortcut(input: {
  origin: unknown;
  table: unknown;
  eventPath: readonly unknown[];
}): boolean {
  if (isDocumentRootNode(input.origin)) return false;
  if (input.eventPath.includes(input.table) || composedContains(input.table, input.origin)) {
    return true;
  }
  return composedContains(input.origin, input.table);
}

function composedParent(node: unknown): unknown {
  if (!node || typeof node !== 'object') return null;
  if (typeof ShadowRoot !== 'undefined' && node instanceof ShadowRoot) {
    return node.host;
  }
  const element = node as ShortcutPathNode;
  if (element.assignedSlot) return element.assignedSlot;
  if (element.parentNode) return element.parentNode;
  const root = element.getRootNode?.();
  if (root && typeof root === 'object' && 'host' in root) {
    return (root as { host?: unknown }).host ?? null;
  }
  return null;
}

import {
  deriveTableSelectionState,
  isTableGroupIntent,
  resolvedTableGroupCount,
  tableCollapseAllHost,
  tableColumnSize,
  tableElasticSpacerIndex,
  tableExplicitMinWidth,
  tableGroupIntentClass,
  tableGroupLabelColor,
  tableRows,
  type TableCollapseAllHost,
  type TableSelectionState,
} from './table-model';
import type {
  TableColumn,
  TableGroup,
  TableGroupIntent,
  TableRow,
  TableSelectionMode,
} from './table-types';

export type TableGroupCountPresentation = 'loaded-progress' | 'total';

export interface TableGroupRenderModel {
  group: TableGroup;
  count: number;
  loadedCount: number;
  visibleCountText: string;
  countLabel: string;
  intent: TableGroupIntent | undefined;
  intentClass: string | undefined;
  labelColor: ReturnType<typeof tableGroupLabelColor>;
  collapsed: boolean;
  selection: TableSelectionState | null;
}

export interface TableRenderModel {
  grouped: boolean;
  selectable: boolean;
  loadedRows: TableRow[];
  hasData: boolean;
  selectedRowIds: ReadonlySet<string>;
  selection: TableSelectionState;
  collapsedGroupIds: ReadonlySet<string>;
  groups: TableGroupRenderModel[];
  totalColumns: number;
  allGroupsCollapsed: boolean;
  showCollapseAll: boolean;
  collapseAllHost: TableCollapseAllHost | undefined;
  elasticSpacerIndex: number | undefined;
  tableStyle: Record<string, string> | undefined;
}

export interface TableRenderModelInput {
  columns: TableColumn[];
  rows: TableRow[];
  groups: TableGroup[];
  grouped: boolean;
  selectionMode: TableSelectionMode;
  selectedRowIds: string[];
  collapsedGroupIds: string[];
  groupCountPresentation?: TableGroupCountPresentation;
}

/** Create one immutable snapshot of all derived state consumed during a render. */
export function createTableRenderModel(input: TableRenderModelInput): TableRenderModel {
  const selectable = input.selectionMode === 'multiple';
  const loadedRows = tableRows(input.rows, input.groups, input.grouped);
  const selectedRowIds = new Set(input.selectedRowIds);
  const collapsedGroupIds = new Set(input.collapsedGroupIds);
  const allGroupsCollapsed =
    input.grouped &&
    input.groups.length > 0 &&
    input.groups.every(group => collapsedGroupIds.has(group.id));
  const showCollapseAll = input.grouped && input.groups.length > 0 && !allGroupsCollapsed;
  const explicitMinWidth = tableExplicitMinWidth(input.columns);
  const elasticSpacerIndex = tableElasticSpacerIndex(input.columns);
  const columnTracks = input.columns.map(column => tableColumnSize(column) ?? 'minmax(0, 1fr)');
  if (elasticSpacerIndex != null) columnTracks.splice(elasticSpacerIndex, 0, 'minmax(0, 1fr)');
  const gridTracks = [
    ...(selectable ? ['var(--_table-selection-column-inline-size)'] : []),
    ...columnTracks,
  ].join(' ');
  const tableStyle: Record<string, string> = {
    '--_table-grid-template-columns': gridTracks || 'minmax(0, 1fr)',
  };
  if (explicitMinWidth != null) {
    tableStyle['--ds-table-explicit-min-inline-size'] = explicitMinWidth;
  }

  return {
    grouped: input.grouped,
    selectable,
    loadedRows,
    hasData: loadedRows.length > 0,
    selectedRowIds,
    selection: deriveTableSelectionState(loadedRows, input.selectedRowIds),
    collapsedGroupIds,
    groups: input.groups.map(group => {
      const loadedCount = group.rows.length;
      const collapsed = collapsedGroupIds.has(group.id);
      const count = resolvedTableGroupCount(group);
      const showTotalOnly =
        input.groupCountPresentation === 'total' || (collapsed && loadedCount === 0);
      const totalLabel = group.countLabel ?? `${count} ${count === 1 ? 'item' : 'items'}`;
      const intent = isTableGroupIntent(group.intent) ? group.intent : undefined;
      return {
        group,
        count,
        loadedCount,
        visibleCountText: showTotalOnly ? String(count) : `${loadedCount} of ${count}`,
        countLabel: showTotalOnly ? totalLabel : `${loadedCount} of ${totalLabel} loaded`,
        intent,
        intentClass: tableGroupIntentClass(intent),
        labelColor: tableGroupLabelColor(intent),
        collapsed,
        selection: selectable ? deriveTableSelectionState(group.rows, input.selectedRowIds) : null,
      };
    }),
    totalColumns:
      input.columns.length + (selectable ? 1 : 0) + (elasticSpacerIndex == null ? 0 : 1),
    allGroupsCollapsed,
    showCollapseAll,
    collapseAllHost: showCollapseAll ? tableCollapseAllHost(input.columns) : undefined,
    elasticSpacerIndex,
    tableStyle,
  };
}

import { h } from '@stencil/core';
import {
  resolveTableCellPresentation,
  tableCellTrackStackBlockSize,
  tableCellTextOverflowProps,
  type TableCellPresentation,
} from './table-cell-model';
import {
  isRenderableTableActionMenu,
  isTableCellActionMenu,
  tableActionTriggerId,
} from './table-action-menu';
import { tableRowSelectionLabel } from './table-model';
import type { TableRenderModel } from './table-render-model';
import { TABLE_NO_HIGHLIGHT_MATCHER, type TableHighlightMatcher } from './table-highlight';
import type { TableCellActionDetail, TableCellTextRun, TableColumn, TableRow } from './table-types';
import { resolveSafeUrl } from '../../utils/safe-url';

export interface TableRowViewOptions {
  row: TableRow;
  model: TableRenderModel;
  visibleColumns: TableColumn[];
  emptyCellLabel: string;
  actionMenuElementId: string;
  actionMenu: { rowId: string; columnId: string } | null;
  highlightMatcher: TableHighlightMatcher;
  highlightFieldIds: string[];
  ariaRowIndex?: number;
  variableVirtualSize?: boolean;
  intrinsicBlockSize?: number;
  rowKey?: string;
  renderSelectionControl: (
    label: string,
    checked: boolean,
    indeterminate: boolean,
    disabled: boolean,
    onActivate: () => void
  ) => unknown;
  renderStickyEdge: (sticky: TableColumn['sticky']) => unknown;
  onRowActivate: (row: TableRow, event: Event) => void;
  onRowKeyDown: (row: TableRow, event: KeyboardEvent) => void;
  onRowSelection: (row: TableRow) => void;
  onCellAction: (detail: TableCellActionDetail) => void;
  onActionMenuToggle: (row: TableRow, column: TableColumn, event: MouseEvent) => void;
}

/** Render one semantic body row and the complete declarative table-cell vocabulary. */
export function renderTableRow({
  row,
  model,
  visibleColumns,
  emptyCellLabel,
  actionMenuElementId,
  actionMenu,
  highlightMatcher,
  highlightFieldIds,
  ariaRowIndex,
  variableVirtualSize = false,
  intrinsicBlockSize,
  rowKey = row.id,
  renderSelectionControl,
  renderStickyEdge,
  onRowActivate,
  onRowKeyDown,
  onRowSelection,
  onCellAction,
  onActionMenuToggle,
}: TableRowViewOptions) {
  const selected = model.selectedRowIds.has(row.id);
  const rowSelectable = row.selectable !== false && !row.disabled;
  const beforeSpacer =
    model.elasticSpacerIndex == null
      ? visibleColumns
      : visibleColumns.slice(0, model.elasticSpacerIndex);
  const afterSpacer =
    model.elasticSpacerIndex == null ? [] : visibleColumns.slice(model.elasticSpacerIndex);
  const renderColumn = (column: TableColumn) =>
    renderTableCell({
      row,
      column,
      selected,
      emptyCellLabel,
      actionMenuElementId,
      actionMenu,
      highlightMatcher,
      highlightFieldIds,
      renderStickyEdge,
      onCellAction,
      onActionMenuToggle,
    });

  return (
    <tr
      key={rowKey}
      class={{
        'ds-table__row': true,
        'ds-table__row--selected': selected,
        'ds-table__row--disabled': !!row.disabled,
        'ds-table__row--interactive': !!row.interactive && !row.disabled,
        'ds-focus-ring': !!row.interactive && !row.disabled,
      }}
      data-row-id={row.id}
      data-virtual-id={ariaRowIndex != null ? `row:${row.id}` : undefined}
      data-virtual-pool-key={ariaRowIndex != null ? rowKey : undefined}
      data-virtual-measure={ariaRowIndex != null && variableVirtualSize ? 'true' : undefined}
      data-selected={selected ? 'true' : undefined}
      style={
        intrinsicBlockSize != null
          ? { '--_table-row-intrinsic-block-size': `${intrinsicBlockSize}px` }
          : undefined
      }
      aria-rowindex={ariaRowIndex}
      aria-disabled={row.disabled ? 'true' : undefined}
      tabIndex={row.interactive && !row.disabled ? 0 : undefined}
      onClick={event => onRowActivate(row, event)}
      onKeyDown={event => onRowKeyDown(row, event)}
    >
      {model.selectable && (
        <td
          class={{
            'ds-table__cell': true,
            'ds-table__selection-cell': true,
            'ds-table__cell--sticky-start': true,
            'ds-interaction-fill': true,
            'ds-interaction-fill--grouped': true,
            'ds-interaction-fill--selected': selected,
          }}
        >
          {renderSelectionControl(
            `${selected ? 'Deselect' : 'Select'} ${tableRowSelectionLabel(row, visibleColumns)}`,
            selected,
            false,
            !rowSelectable,
            () => onRowSelection(row)
          )}
          {renderStickyEdge('start')}
        </td>
      )}
      {beforeSpacer.map(renderColumn)}
      {model.elasticSpacerIndex != null && (
        <td
          class={{
            'ds-table__cell': true,
            'ds-table__elastic-spacer-cell': true,
            'ds-interaction-fill': true,
            'ds-interaction-fill--grouped': true,
            'ds-interaction-fill--selected': selected,
          }}
          aria-hidden="true"
          role="presentation"
          data-elastic-spacer="true"
        />
      )}
      {afterSpacer.map(renderColumn)}
    </tr>
  );
}

interface TableCellViewOptions {
  row: TableRow;
  column: TableColumn;
  selected: boolean;
  emptyCellLabel: string;
  actionMenuElementId: string;
  actionMenu: { rowId: string; columnId: string } | null;
  highlightMatcher: TableHighlightMatcher;
  highlightFieldIds: string[];
  renderStickyEdge: (sticky: TableColumn['sticky']) => unknown;
  onCellAction: (detail: TableCellActionDetail) => void;
  onActionMenuToggle: (row: TableRow, column: TableColumn, event: MouseEvent) => void;
}

function renderTableCell(options: TableCellViewOptions) {
  const { row, column, selected, renderStickyEdge } = options;
  const align = column.align ?? 'start';
  const cell = resolveTableCellPresentation(row.cells[column.id], column);
  const tagCell = cell.kind === 'tag';
  const tagsCell = cell.kind === 'tags';
  const iconCell = cell.kind === 'icon';
  const iconTextCell = cell.kind === 'icon-text';
  const imageCell = cell.kind === 'image';
  const actionCell = cell.kind === 'action';
  const actionMenuCell = actionCell && isRenderableTableActionMenu(cell.value);
  const textCell = cell.kind === 'text';
  const primaryTextCell = textCell && cell.primaryText;
  const singleTextCell = textCell && cell.singleLine;
  const emptyCell = cell.kind === 'empty';
  const blankCell = cell.kind === 'blank';
  const tagVariant = tagCell ? cell.variant : undefined;
  const tagsVariant = tagsCell ? cell.variant : undefined;
  const textVariant = textCell ? cell.variant : undefined;
  const imageVariant = imageCell ? cell.variant : undefined;
  const iconTextVariant = iconTextCell ? cell.variant : undefined;
  const wraps = (textCell || iconTextCell) && cell.wraps;

  return (
    <td
      key={`${row.id}:${column.id}`}
      class={{
        'ds-table__cell': true,
        [`ds-table__cell--align-${align}`]: true,
        'ds-table__cell--tag': tagCell,
        [`ds-table__cell--tag-${tagVariant}`]: tagCell,
        'ds-table__cell--tags': tagsCell,
        [`ds-table__cell--tags-${tagsVariant}`]: tagsCell,
        'ds-table__cell--icon': iconCell,
        'ds-table__cell--icon-text': iconTextCell,
        [`ds-table__cell--icon-text-${iconTextVariant}`]: iconTextCell,
        'ds-table__cell--icon-text-wrap': iconTextCell && wraps,
        'ds-table__cell--image': imageCell,
        [`ds-table__cell--image-${imageVariant}`]: imageCell,
        'ds-table__cell--action': actionCell,
        'ds-table__cell--action-menu': actionMenuCell,
        'ds-table__cell--primary-text': primaryTextCell,
        'ds-table__cell--text-single': singleTextCell,
        'ds-table__cell--text-multi': textCell && !singleTextCell && textVariant !== 'triple',
        'ds-table__cell--text-triple': textVariant === 'triple',
        'ds-table__cell--text-wrap': textCell && wraps,
        'ds-table__cell--empty': emptyCell,
        'ds-table__cell--blank': blankCell,
        'ds-table__cell--sticky-start': column.sticky === 'start',
        'ds-table__cell--sticky-end': column.sticky === 'end',
        'ds-interaction-fill': true,
        'ds-interaction-fill--grouped': true,
        'ds-interaction-fill--selected': selected,
      }}
      data-column-id={column.id}
      data-cell-type={cell.cellType}
      data-cell-variant={
        tagVariant ?? tagsVariant ?? textVariant ?? imageVariant ?? iconTextVariant
      }
      data-cell-tracks={tagsCell ? cell.tracks : undefined}
    >
      <span class="ds-table__cell-content ds-interaction-fill__content">
        {renderTableCellValue(cell, options)}
      </span>
      {renderStickyEdge(column.sticky)}
    </td>
  );
}

function renderTableCellValue(cell: TableCellPresentation, options: TableCellViewOptions) {
  const {
    row,
    column,
    emptyCellLabel,
    actionMenuElementId,
    actionMenu,
    onCellAction,
    onActionMenuToggle,
  } = options;
  if (cell.kind === 'blank') return null;

  if (cell.kind === 'empty') {
    return (
      <ds-text
        class="ds-table__cell-track ds-table__cell-track--text"
        as="span"
        variant="text-body-medium"
        color="tertiary"
      >
        <span aria-hidden="true">—</span>
        <span class="ds-visually-hidden">{emptyCellLabel}</span>
      </ds-text>
    );
  }

  if (cell.kind === 'icon') {
    const value = cell.value;
    return (
      <ds-icon name={value.icon} size="md" color={value.color ?? 'secondary'} label={value.label} />
    );
  }

  if (cell.kind === 'icon-text') {
    return (
      <span class="ds-table__cell-icon-text">
        <span class="ds-table__cell-icon-text-icon">
          <ds-icon
            name={cell.icon}
            size="md"
            color={cell.iconColor ?? 'secondary'}
            label={cell.iconLabel}
          />
        </span>
        {renderTextCopy(cell, options)}
      </span>
    );
  }

  if (cell.kind === 'image') {
    const value = cell.value;
    return (
      <span class="ds-table__cell-image">
        {value.src ? (
          <img
            class="ds-table__cell-image-content"
            src={value.src}
            alt={value.alt}
            loading="lazy"
          />
        ) : (
          <span class="ds-table__cell-image-placeholder" role="img" aria-label={value.alt} />
        )}
      </span>
    );
  }

  if (cell.kind === 'action') {
    const value = cell.value;
    const menu = isRenderableTableActionMenu(value);
    const triggerId = tableActionTriggerId(actionMenuElementId, row.id, column.id);
    const expanded = menu && actionMenu?.rowId === row.id && actionMenu?.columnId === column.id;
    return (
      <ds-button-unfilled
        id={menu ? triggerId : undefined}
        variant={menu ? 'icon' : (value.variant ?? 'label')}
        size="md"
        isInset={true}
        insetDepth="double"
        label={value.label ?? ''}
        icon={value.icon ?? (menu ? 'Ellipses' : '')}
        aria-label={value.ariaLabel ?? null}
        hasBorder={value.hasBorder ?? false}
        isInactive={value.isInactive ?? false}
        isLoading={value.isLoading ?? false}
        hasMenu={menu}
        expanded={menu ? expanded : undefined}
        controls={menu ? actionMenuElementId : undefined}
        onDsClick={event => {
          event.stopPropagation();
          if (menu) {
            onActionMenuToggle(row, column, event.detail);
            return;
          }
          if (isTableCellActionMenu(value)) return;
          onCellAction({ actionId: value.actionId, rowId: row.id, columnId: column.id });
        }}
      />
    );
  }

  if (cell.kind === 'tag') {
    const value = cell.value;
    const variant = cell.variant;
    const tag = (
      <ds-tag
        label={value.label}
        intent={value.intent ?? 'neutral'}
        contrast={value.contrast ?? 'faint'}
        size={variant === 'text-with-tag' ? 'sm' : 'md'}
        icon={value.icon ?? ''}
        rounded={value.rounded ?? false}
        isInset
        insetDepth={variant === 'text-with-tag' ? 'single' : 'double'}
      />
    );
    if (variant === 'tag-only') return tag;
    return (
      <span class={`ds-table__cell-tag-stack ds-table__cell-tag-stack--${variant}`}>
        {variant === 'tag-with-text' && tag}
        <ds-text
          class="ds-table__cell-tag-text ds-table__cell-track"
          as="span"
          variant={variant === 'tag-with-text' ? 'text-body-small' : 'text-body-medium'}
          color="secondary"
          lineTruncation={1}
          data-table-truncate=""
        >
          {renderHighlightedText(
            value.text,
            tableCellFieldMatcher(options, variant === 'tag-with-text' ? 1 : 0)
          )}
        </ds-text>
        {variant === 'text-with-tag' && <span class="ds-table__cell-tag-control-track">{tag}</span>}
      </span>
    );
  }

  if (cell.kind === 'tags') {
    return (
      <span
        class="ds-table__cell-tags"
        style={{ '--_table-cell-tags-min-block-size': tableCellTrackStackBlockSize(cell.tracks) }}
      >
        {cell.value.items.map((item, index) => (
          <ds-tag
            key={`${item.label}-${index}`}
            label={item.label}
            intent={item.intent ?? 'neutral'}
            contrast={item.contrast ?? 'faint'}
            size="sm"
            icon={item.icon ?? ''}
            rounded={item.rounded ?? false}
            isInset
            insetDepth="single"
          />
        ))}
      </span>
    );
  }

  if (cell.kind !== 'text') return null;
  return renderTextCopy(cell, options);
}

function renderTextCopy(
  cell: Extract<TableCellPresentation, { kind: 'text' | 'icon-text' }>,
  options: TableCellViewOptions
) {
  const text = cell.value;
  const overflow = tableCellTextOverflowProps(cell.lineClamp);
  const primaryText = cell.kind === 'text' && cell.primaryText;
  const href = resolveSafeUrl(text.href);
  const primary = (
    <ds-text
      class="ds-table__cell-primary ds-table__cell-track ds-table__cell-track--text"
      as="span"
      variant="text-body-medium"
      color={href ? 'inherit' : 'primary'}
      lineTruncation={overflow.lineTruncation}
      wrap={overflow.wrap}
      fontFeature={text.fontFeature ?? 'normal'}
      data-table-truncate={truncateAttr(cell.lineClamp)}
    >
      {renderHighlightedText(text.primary, tableCellFieldMatcher(options, 0))}
    </ds-text>
  );

  return (
    <span class={{ 'ds-table__cell-copy': true, 'ds-table__cell-copy--wrap': cell.wraps }}>
      {href ? (
        <a
          class="ds-table__cell-link ds-text-action ds-focus-ring"
          href={href}
          target={text.target === '_blank' ? '_blank' : undefined}
          rel={text.target === '_blank' ? 'noopener noreferrer' : undefined}
        >
          {primary}
        </a>
      ) : (
        primary
      )}
      {renderTextTrack(text.secondary, {
        track: 'secondary',
        variant: primaryText ? 'text-body-medium' : 'text-body-small',
        defaultColor: primaryText ? 'primary' : 'secondary',
        wholeColor: text.secondaryColor,
        lineClamp: cell.lineClamp,
        highlightMatcherForRun: runIndex => tableCellFieldMatcher(options, 1 + runIndex),
      })}
      {renderTextTrack(text.tertiary, {
        track: 'tertiary',
        variant: 'text-body-small',
        defaultColor: 'secondary',
        wholeColor: text.tertiaryColor,
        lineClamp: cell.lineClamp,
        highlightMatcherForRun: runIndex =>
          tableCellFieldMatcher(options, 1 + (text.secondary?.length ?? 0) + runIndex),
      })}
    </span>
  );
}

function renderTextTrack(
  runs: TableCellTextRun[] | undefined,
  options: {
    track: 'secondary' | 'tertiary';
    variant: 'text-body-medium' | 'text-body-small';
    defaultColor: 'primary' | 'secondary';
    wholeColor?: TableCellTextRun['color'];
    lineClamp: Extract<TableCellPresentation, { kind: 'text' | 'icon-text' }>['lineClamp'];
    highlightMatcherForRun: (runIndex: number) => TableHighlightMatcher;
  }
) {
  if (!runs?.length) return null;
  const trackClass = `ds-table__cell-${options.track} ds-table__cell-track ds-table__cell-track--text`;
  const overflow = tableCellTextOverflowProps(options.lineClamp);
  const colorFor = (run: TableCellTextRun) =>
    run.color ?? options.wholeColor ?? options.defaultColor;
  if (runs.length === 1) {
    return (
      <ds-text
        class={trackClass}
        as="span"
        variant={options.variant}
        color={colorFor(runs[0])}
        lineTruncation={overflow.lineTruncation}
        wrap={overflow.wrap}
        data-table-truncate={truncateAttr(options.lineClamp)}
      >
        {renderHighlightedText(runs[0].text, options.highlightMatcherForRun(0))}
      </ds-text>
    );
  }

  return (
    <span class={`${trackClass} ds-table__cell-track--runs`}>
      {runs.map((run, index) => [
        index > 0 && (
          <ds-text
            key={`${options.track}-sep-${index}`}
            class="ds-table__cell-run-separator"
            as="span"
            variant={options.variant}
            color="secondary"
            aria-hidden="true"
          >
            ·
          </ds-text>
        ),
        <ds-text
          key={`${options.track}-run-${index}`}
          class="ds-table__cell-run"
          as="span"
          variant={options.variant}
          color={colorFor(run)}
          lineTruncation={overflow.lineTruncation}
          wrap={overflow.wrap}
          data-table-truncate={truncateAttr(options.lineClamp)}
        >
          {renderHighlightedText(run.text, options.highlightMatcherForRun(index))}
        </ds-text>,
      ])}
    </span>
  );
}

function renderHighlightedText(value: string | number | undefined, matcher: TableHighlightMatcher) {
  if (value === undefined) return null;
  return matcher(value).map((segment, index) =>
    segment.match ? (
      <mark class="ds-table__match" key={`match-${index}`}>
        {segment.text}
      </mark>
    ) : (
      <span key={`text-${index}`}>{segment.text}</span>
    )
  );
}

function tableCellFieldMatcher(
  options: TableCellViewOptions,
  fieldIndex: number
): TableHighlightMatcher {
  const selected = options.highlightFieldIds;
  if (selected.length === 0 || selected.includes(options.column.id)) {
    return options.highlightMatcher;
  }
  const fieldId = options.column.headerSegments?.[fieldIndex]?.sortKey;
  return fieldId && selected.includes(fieldId)
    ? options.highlightMatcher
    : TABLE_NO_HIGHLIGHT_MATCHER;
}

function truncateAttr(
  lineClamp: Extract<TableCellPresentation, { kind: 'text' | 'icon-text' }>['lineClamp']
) {
  return lineClamp === 'none' ? undefined : '';
}

import { h } from '@stencil/core';
import { resolveTableCellImageTracks, tableCellImageVariant } from './table-cell-model';
import type { TableRenderModel } from './table-render-model';
import type { TableCellSkeleton, TableColumn } from './table-types';

interface TableSkeletonViewOptions {
  model: TableRenderModel;
  visibleColumns: TableColumn[];
  skeletonRows: number;
  renderStickyEdge: (sticky: TableColumn['sticky']) => unknown;
}

/** Render the loading body from the same cell recipes used by loaded rows. */
export function renderTableSkeletonBody(options: TableSkeletonViewOptions) {
  const { model, visibleColumns, renderStickyEdge } = options;
  const count = Math.min(20, Math.max(1, Math.round(options.skeletonRows) || 1));
  const beforeSpacer =
    model.elasticSpacerIndex == null
      ? visibleColumns
      : visibleColumns.slice(0, model.elasticSpacerIndex);
  const afterSpacer =
    model.elasticSpacerIndex == null ? [] : visibleColumns.slice(model.elasticSpacerIndex);
  return (
    <tbody class="ds-table__body ds-table__skeleton-body">
      {Array.from({ length: count }, (_, index) => (
        <tr class="ds-table__row ds-table__skeleton-row" key={`skeleton-${index}`}>
          {model.selectable && (
            <td
              class="ds-table__cell ds-table__selection-cell ds-table__cell--sticky-start ds-table__skeleton-cell ds-interaction-fill ds-interaction-fill--grouped"
              data-skeleton-kind="checkbox"
            >
              <span class="ds-table__skeleton-checkbox-canvas ds-interaction-fill__content">
                <ds-skeleton
                  class="ds-table__skeleton-checkbox"
                  variant="control"
                  controlSize="xs"
                  width="var(--dimension-iconography-sm)"
                />
              </span>
              {renderStickyEdge('start')}
            </td>
          )}
          {beforeSpacer.map(column => renderSkeletonCell(column, index, renderStickyEdge))}
          {model.elasticSpacerIndex != null && (
            <td
              class="ds-table__cell ds-table__elastic-spacer-cell ds-table__skeleton-cell ds-interaction-fill ds-interaction-fill--grouped"
              aria-hidden="true"
              role="presentation"
              data-elastic-spacer="true"
            />
          )}
          {afterSpacer.map(column => renderSkeletonCell(column, index, renderStickyEdge))}
        </tr>
      ))}
    </tbody>
  );
}

function renderSkeletonCell(
  column: TableColumn,
  rowIndex: number,
  renderStickyEdge: TableSkeletonViewOptions['renderStickyEdge']
) {
  const skeleton =
    column.skeleton ??
    ((column.kind === 'action'
      ? { kind: 'action', variant: 'icon' }
      : { kind: 'text', lines: 1 }) satisfies TableCellSkeleton);
  const align = column.align ?? 'start';
  const text = skeleton.kind === 'text';
  const iconText = skeleton.kind === 'icon-text';
  const lines = text || iconText ? (skeleton.lines ?? 1) : 1;
  const tag = skeleton.kind === 'tag';
  const icon = skeleton.kind === 'icon';
  const image = skeleton.kind === 'image';
  const imageVariant = image
    ? tableCellImageVariant(resolveTableCellImageTracks(skeleton.tracks))
    : undefined;
  const iconTextVariant = iconText
    ? lines === 3
      ? 'triple'
      : lines === 2
        ? 'multi'
        : 'single'
    : undefined;
  const action = skeleton.kind === 'action';
  const blank = skeleton.kind === 'blank';

  return (
    <td
      class={{
        'ds-table__cell': true,
        [`ds-table__cell--align-${align}`]: true,
        'ds-table__skeleton-cell': true,
        'ds-table__cell--text-single': text && lines === 1,
        'ds-table__cell--text-multi': text && lines === 2,
        'ds-table__cell--text-triple': text && lines === 3,
        'ds-table__cell--tag': tag,
        'ds-table__cell--tag-tag-only': tag,
        'ds-table__cell--icon': icon,
        'ds-table__cell--icon-text': iconText,
        [`ds-table__cell--icon-text-${iconTextVariant}`]: iconText,
        'ds-table__cell--image': image,
        [`ds-table__cell--image-${imageVariant}`]: image,
        'ds-table__cell--action': action,
        'ds-table__cell--blank': blank,
        'ds-table__cell--sticky-start': column.sticky === 'start',
        'ds-table__cell--sticky-end': column.sticky === 'end',
        'ds-interaction-fill': true,
        'ds-interaction-fill--grouped': true,
      }}
      data-column-id={column.id}
      data-skeleton-kind={skeleton.kind}
      data-cell-variant={imageVariant ?? iconTextVariant}
      key={`skeleton-${rowIndex}:${column.id}`}
    >
      <span class="ds-table__cell-content ds-interaction-fill__content">
        {renderSkeletonCellContent(skeleton)}
      </span>
      {renderStickyEdge(column.sticky)}
    </td>
  );
}

function renderSkeletonCellContent(skeleton: TableCellSkeleton) {
  if (skeleton.kind === 'blank') return null;

  if (skeleton.kind === 'image') {
    return (
      <span class="ds-table__cell-image ds-table__skeleton-image">
        <ds-skeleton
          class="ds-table__skeleton-image-shape"
          variant="control"
          controlSize="md"
          width="100%"
        />
      </span>
    );
  }

  if (skeleton.kind === 'icon') {
    return <ds-skeleton variant="icon" iconSize="md" rounded={skeleton.rounded ?? false} />;
  }

  if (skeleton.kind === 'tag') {
    return <ds-skeleton variant="control" controlSize="sm" width={skeleton.width ?? '64%'} />;
  }

  if (skeleton.kind === 'action') {
    const iconOnly = (skeleton.variant ?? 'icon') === 'icon';
    return (
      <ds-skeleton
        variant="control"
        controlSize="sm"
        width={skeleton.width ?? (iconOnly ? '24px' : '72%')}
      />
    );
  }

  const lines = skeleton.lines ?? 1;
  const copy = (
    <span class="ds-table__cell-copy">
      <span class="ds-table__cell-primary ds-table__cell-track ds-table__cell-track--text">
        <ds-skeleton
          variant="text"
          textVariant="text-body-medium"
          width={skeleton.primaryWidth ?? '100%'}
        />
      </span>
      {lines >= 2 && (
        <span class="ds-table__cell-secondary ds-table__cell-track ds-table__cell-track--text">
          <ds-skeleton
            variant="text"
            textVariant="text-body-small"
            width={skeleton.secondaryWidth ?? '72%'}
          />
        </span>
      )}
      {lines === 3 && (
        <span class="ds-table__cell-tertiary ds-table__cell-track ds-table__cell-track--text">
          <ds-skeleton
            variant="text"
            textVariant="text-body-small"
            width={skeleton.tertiaryWidth ?? '56%'}
          />
        </span>
      )}
    </span>
  );
  if (skeleton.kind === 'icon-text') {
    return (
      <span class="ds-table__cell-icon-text">
        <span class="ds-table__cell-icon-text-icon">
          <ds-skeleton variant="icon" iconSize="md" />
        </span>
        {copy}
      </span>
    );
  }
  return copy;
}

/** Marks text tracks that may present the table-owned truncation tooltip. */
export const TABLE_TRUNCATE_ATTR = 'data-table-truncate';

function isValidTruncateTrack(track: HTMLElement): boolean {
  return !track.closest('.ds-table__row--disabled, thead, .ds-table__header-row');
}

/** Resolve the overflowing text track under a pointer or focus target. */
export function resolveTableTruncateTrack(target: EventTarget | null): HTMLElement | null {
  const element =
    target instanceof Element ? target : target instanceof Node ? target.parentElement : null;
  if (!element) return null;

  const fromAncestor = element.closest<HTMLElement>(`[${TABLE_TRUNCATE_ATTR}]`);
  if (fromAncestor && isValidTruncateTrack(fromAncestor)) return fromAncestor;

  const link = element.closest('a.ds-table__cell-link');
  const nested = link?.querySelector<HTMLElement>(`[${TABLE_TRUNCATE_ATTR}]`);
  if (nested && isValidTruncateTrack(nested)) return nested;
  return null;
}

export function tableTruncateLabel(track: HTMLElement): string {
  return (track.textContent ?? '').replace(/\s+/g, ' ').trim();
}

import type { TagContrast, TagIntent } from '../Tag/Tag';
import type { IconColor } from '../Icon/Icon';
import type { TextColor } from '../Text/text-types';
import type { PaginationState } from '../Pagination/pagination-types';

export type TableSortDirection = 'asc' | 'desc';
export type TableSelectionMode = 'none' | 'multiple';
export type TableCellAlign = 'start' | 'center' | 'end';
export type TableCellLinkTarget = '_self' | '_blank';
export type TableColumnSticky = 'start' | 'end';
export type TableCaptionVisibility = 'visible' | 'hidden';
export type TableLoadMoreMode = 'auto' | 'manual';
export type TableDataMode = 'infinite' | 'pagination' | 'virtual';
export interface TableDataModeChangeDetail {
  dataMode: TableDataMode;
}
export type TableLoadMoreReason = 'auto' | 'manual' | 'retry';
export type TableColumnWidth = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
/** Visible line budget before a text track ellipsizes. */
export type TableCellMaxLines = 1 | 2 | 3;
/** Resolved clamp, including unlimited wrapping. */
export type TableCellLineClamp = TableCellMaxLines | 'none';
/** Semantic color for a group section header (faint surface + bold title). */
export type TableGroupIntent =
  | 'brand'
  | 'neutral'
  | 'negative'
  | 'warning'
  | 'caution'
  | 'positive';

/** Independently sortable label within a compound column header. */
export interface TableHeaderSegment {
  /** Compact label rendered inside the table header. */
  label: string;
  /** Complete data-point label used when the segment is named outside the table header. */
  dataLabel?: string;
  /** Whether this data point is offered by TableSearch. Defaults to true. */
  searchable?: boolean;
  /** Stable key emitted through TableSortState.columnId. */
  sortKey: string;
  /** Visible separator rendered after this label when another segment follows. */
  separator?: string;
}

/** Controlled member-row sort state. Group order is controlled separately. */
export interface TableSortState {
  columnId: string;
  direction: TableSortDirection;
}

/** One controlled grouping level. Applications supply groups in their final fixed order. */
export interface TableGroupingState {
  columnId: string;
  direction: TableSortDirection;
}

/** One independently colored run inside a secondary or tertiary track. */
export interface TableCellTextRun {
  text: string;
  /** Defaults to the track’s standard color. */
  color?: TextColor;
}

/** A secondary or tertiary track: one string, or up to three colorable runs. */
export type TableCellTextTrack = string | TableCellTextRun[];

/** Standard two- or three-line cell content owned by the table renderer. */
export interface TableCellText {
  primary: string | number;
  secondary?: TableCellTextTrack;
  /** Third subdued track; ignored on dual-primary cells. */
  tertiary?: TableCellTextTrack;
  /** Optional semantic foreground for a string secondary track. */
  secondaryColor?: TextColor;
  /** Optional semantic foreground for a string tertiary track. */
  tertiaryColor?: TextColor;
  /** Application-owned URL for the primary track only. Scalars stay unlinked. */
  href?: string;
  /** Native anchor target for a resolved primary link. */
  target?: TableCellLinkTarget;
  /** Allow this cell to wrap even when its column truncates by default. */
  wrap?: boolean;
  /** Clamp wrapping text after 1, 2, or 3 lines. Overrides column wrap. */
  maxLines?: TableCellMaxLines;
  fontFeature?: 'normal' | 'tabular-nums';
}

/** Two-line text content where both tracks use primary body text. */
export interface TableCellPrimaryText {
  kind: 'primary-text';
  primary: string | number;
  secondary: string | number;
  /** Application-owned URL for the primary track only. */
  href?: string;
  /** Native anchor target for a resolved primary link. */
  target?: TableCellLinkTarget;
  /** Allow this cell to wrap even when its column truncates by default. */
  wrap?: boolean;
  /** Clamp wrapping text after 1, 2, or 3 lines. Overrides column wrap. */
  maxLines?: TableCellMaxLines;
  fontFeature?: 'normal' | 'tabular-nums';
}

/** Applicable data point whose value is currently unavailable. */
export interface TableCellEmpty {
  kind: 'empty';
}

/** Data point that is intentionally not applicable to this row. */
export interface TableCellBlank {
  kind: 'blank';
}

/** Declarative icon-only content rendered by the table's standard cell primitive. */
export interface TableCellIcon {
  kind: 'icon';
  /** Exact canonical IcoMo export name. */
  icon: string;
  color?: IconColor;
  /** Accessible label for informative icons. Omit only when the icon is decorative. */
  label?: string;
  /** Application-owned value used when this icon column participates in sorting. */
  sortValue?: string | number | boolean;
}

/**
 * Prefix icon beside a text copy stack. Independent of icon-only and plain
 * text cells so those recipes stay unchanged.
 */
export interface TableCellIconText {
  kind: 'icon-text';
  /** Exact canonical IcoMo export name. */
  icon: string;
  iconColor?: IconColor;
  /** Accessible name. Omit when the glyph is decorative. */
  iconLabel?: string;
  primary: string | number;
  secondary?: TableCellTextTrack;
  tertiary?: TableCellTextTrack;
  secondaryColor?: TextColor;
  tertiaryColor?: TextColor;
  href?: string;
  target?: TableCellLinkTarget;
  wrap?: boolean;
  maxLines?: TableCellMaxLines;
  fontFeature?: 'normal' | 'tabular-nums';
}

/** Body-row track stack an image preview occupies. */
export type TableCellImageTracks = 1 | 2 | 3;

/** Declarative 16:9 image preview rendered by the table's standard cell primitive. */
export interface TableCellImage {
  kind: 'image';
  /** Optional image source. Omit it to render the standard bordered placeholder. */
  src?: string;
  /** Accessible description for either the image or its placeholder. */
  alt: string;
  /**
   * Which body-row contract the preview fills. The thumbnail height is that
   * cell height minus 8px padding; width follows 16:9. Defaults to 1.
   */
  tracks?: TableCellImageTracks;
}

interface TableCellActionBase {
  kind: 'action';
  /** Add the ButtonUnfilled resting border. Action cells are unbordered by default. */
  hasBorder?: boolean;
  isInactive?: boolean;
  isLoading?: boolean;
}

/** One command inside an overflow action menu. */
export interface TableCellActionMenuItem {
  /** Stable application-owned action identity emitted with dsCellAction. */
  actionId: string;
  label: string;
  isInactive?: boolean;
  isDestructive?: boolean;
}

/** Visual separator between overflow action-menu commands. */
export interface TableCellActionDivider {
  kind: 'divider';
}

export type TableCellActionMenuEntry = TableCellActionMenuItem | TableCellActionDivider;

/** Declarative ButtonUnfilled content rendered by the table's standard action cell. */
export type TableCellAction = TableCellActionBase &
  (
    | {
        variant?: 'label';
        /** Stable application-owned action identity emitted with dsCellAction. */
        actionId: string;
        label: string;
        icon?: never;
        ariaLabel?: string;
        items?: never;
      }
    | {
        variant: 'icon-label';
        actionId: string;
        label: string;
        icon: string;
        ariaLabel?: string;
        items?: never;
      }
    | {
        variant: 'icon';
        actionId: string;
        label?: never;
        icon: string;
        ariaLabel: string;
        items?: never;
      }
    | {
        variant?: 'icon';
        /** Overflow commands. The Ellipses trigger opens ds-menu instead of emitting on click. */
        items: TableCellActionMenuEntry[];
        ariaLabel: string;
        icon?: string;
        actionId?: never;
        label?: never;
      }
  );

/** Declarative Tag content rendered by the table's standard cell primitive. */
export type TableCellTagVariant = 'tag-only' | 'tag-with-text' | 'text-with-tag';

/** One Tag inside a single- or multiple-Tag table cell. */
export interface TableCellTagItem {
  label: string;
  intent?: TagIntent;
  contrast?: TagContrast;
  icon?: string;
  rounded?: boolean;
}

export type TableCellTag = TableCellTagItem & { kind: 'tag' } & (
    | {
        variant?: 'tag-only';
        text?: never;
      }
    | {
        variant: Exclude<TableCellTagVariant, 'tag-only'>;
        text: string;
      }
  );

/** Multiple Tags that wrap inline while retaining the table's named track rhythm. */
export interface TableCellTags {
  kind: 'tags';
  items: TableCellTagItem[];
  /** Expected positive wrapped-line count used for row geometry and virtual estimates. */
  tracks: number;
}

export type TableCellValue =
  | string
  | number
  | null
  | undefined
  | TableCellText
  | TableCellPrimaryText
  | TableCellTag
  | TableCellTags
  | TableCellIcon
  | TableCellIconText
  | TableCellImage
  | TableCellAction
  | TableCellEmpty
  | TableCellBlank;

export type TableSkeletonWidth = string | number;

/** Representative loading geometry for one table column. */
export type TableCellSkeleton =
  | {
      kind: 'text';
      /** One track for scalar content, two for primary and secondary, three when tertiary is present. */
      lines?: 1 | 2 | 3;
      primaryWidth?: TableSkeletonWidth;
      secondaryWidth?: TableSkeletonWidth;
      tertiaryWidth?: TableSkeletonWidth;
    }
  | {
      kind: 'image';
      /** Match the loaded image cell's track stack. Defaults to 1. */
      tracks?: TableCellImageTracks;
    }
  | {
      kind: 'tag';
      width?: TableSkeletonWidth;
    }
  | {
      kind: 'icon';
      rounded?: boolean;
    }
  | {
      kind: 'icon-text';
      lines?: 1 | 2 | 3;
      primaryWidth?: TableSkeletonWidth;
      secondaryWidth?: TableSkeletonWidth;
      tertiaryWidth?: TableSkeletonWidth;
    }
  | {
      kind: 'action';
      /** Icon actions use a square control canvas; labeled actions may provide a wider width. */
      variant?: 'icon' | 'label' | 'icon-label';
      width?: TableSkeletonWidth;
    }
  | {
      kind: 'blank';
    };

export interface TableColumn {
  /** Stable column identity. */
  id: string;
  /** Visible column label. May be empty when headerLabel supplies a non-visual name. */
  header: string;
  /** Complete data-point label used by controls such as Sort and Search. */
  dataLabel?: string;
  /** Whether this data point is offered by TableSearch. Defaults to true for data columns. */
  searchable?: boolean;
  /** Screen-reader-only column name for an intentionally blank visual header. */
  headerLabel?: string;
  /** Supplementary header help. Does not replace the visible or accessible column name. */
  help?: string;
  /** Optional labels for columns that present and sort multiple related data points. */
  headerSegments?: TableHeaderSegment[];
  align?: TableCellAlign;
  sortable?: boolean;
  /** Preferred TokoMo table-column width. Numbers remain available for exceptional custom pixel widths. */
  size?: TableColumnWidth | number;
  /** Derive a fixed image-column width from the matching 1, 2, or 3 track cell geometry. Ignored when size is set. */
  imageTracks?: TableCellImageTracks;
  /** Minimum accepted preferred width in CSS pixels. */
  minSize?: number;
  /** Maximum accepted preferred width in CSS pixels. */
  maxSize?: number;
  /** Wrap cell text instead of truncating it to one line. */
  wrap?: boolean;
  /** Clamp wrapping text after 1, 2, or 3 lines. Omit with wrap for unlimited wrap. */
  maxLines?: TableCellMaxLines;
  /** Pin one application column to either inline edge during horizontal scrolling. */
  sticky?: TableColumnSticky;
  /**
   * Declare a trailing application-action lane. Action columns keep fixed
   * geometry and may host grouped table-level controls in their header.
   */
  kind?: 'data' | 'action';
  /** Representative loading geometry for this column. Defaults to one text line. */
  skeleton?: TableCellSkeleton;
}

export interface TableRow {
  /** Stable identity, unique across all groups. */
  id: string;
  cells: Record<string, TableCellValue>;
  /** Accessible row name used by its selection control. Falls back to the first cell. */
  selectionLabel?: string;
  /** Exclude this row from selection without muting its content. */
  selectable?: boolean;
  /** Keep the row visible while disabling its selection control and styling it as inactive. */
  disabled?: boolean;
  /** Make the complete row a keyboard- and pointer-activatable application target. */
