import { resolveCssLengthPx } from '../../utils/resolve-css-length-px';

export interface TableViewportFitMetricInput {
  scrollportBlockStart: number;
  scrollportBlockSize: number;
  hostBlockStart: number;
  insetBlockStart: number;
  insetBlockEnd: number;
}

export interface TableViewportFitMetrics {
  reservedBlockSize: number;
  currentBlockSize: number;
  settled: boolean;
}

export interface TableViewportFitElements {
  host: HTMLElement | null;
  surface: HTMLElement | null;
}

export interface TableViewportFitControllerOptions {
  enabled: () => boolean;
  elements: () => TableViewportFitElements;
  insets: () => { blockStart: string | number; blockEnd: string | number };
  fitChanged: (metrics: TableViewportFitMetrics | null) => void;
}

/** Resolve the reserved compact-state height and the height currently visible. */
export function resolveTableViewportFitMetrics(
  input: TableViewportFitMetricInput
): TableViewportFitMetrics {
  const insetBlockStart = Math.max(0, input.insetBlockStart);
  const insetBlockEnd = Math.max(0, input.insetBlockEnd);
  const scrollportBlockEnd = input.scrollportBlockStart + input.scrollportBlockSize;
  const settledBlockStart = input.scrollportBlockStart + insetBlockStart;
  const reservedBlockSize = Math.max(
    0,
    input.scrollportBlockSize - insetBlockStart - insetBlockEnd
  );
  const currentBlockStart = Math.max(input.hostBlockStart, settledBlockStart);
  const currentBlockSize = Math.min(
    reservedBlockSize,
    Math.max(0, scrollportBlockEnd - insetBlockEnd - currentBlockStart)
  );

  return {
    reservedBlockSize,
    currentBlockSize,
    settled: input.hostBlockStart <= settledBlockStart + 0.5,
  };
}

/**
 * Fits the complete table chrome to its nearest vertical scrollport. The host
 * reserves its compact-state height so the outer page can consume collapsing
 * header travel without changing document height. The visible table surface
 * grows into that reservation until it reaches the supplied sticky inset.
 */
export class TableViewportFitController {
  private connected = false;
  private connectedHost: HTMLElement | null = null;
  private connectedSurface: HTMLElement | null = null;
  private scrollRoot: HTMLElement | Window | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private metrics: TableViewportFitMetrics | null = null;
  private insetBlockStart: string | number | null = null;
  private insetBlockEnd: string | number | null = null;

  constructor(private readonly options: TableViewportFitControllerOptions) {}

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    this.disconnectRuntime();
    this.clearGeometry();
  }

  refresh(forceGeometry = true): void {
    if (!this.connected) return;
    if (!this.options.enabled()) {
      this.disconnectRuntime();
      this.clearGeometry();
      return;
    }

    const { host, surface } = this.options.elements();
    if (!host) return;
    const elementsChanged = host !== this.connectedHost || surface !== this.connectedSurface;
    const nextScrollRoot =
      elementsChanged || !this.scrollRoot ? this.findScrollRoot(host) : this.scrollRoot;
    const rootChanged = nextScrollRoot !== this.scrollRoot;
    if (nextScrollRoot !== this.scrollRoot) {
      this.disconnectRuntime();
      this.scrollRoot = nextScrollRoot;
      this.scrollRoot.addEventListener('scroll', this.sync, { passive: true });
      window.addEventListener('resize', this.sync, { passive: true });
      if (typeof ResizeObserver !== 'undefined' && this.scrollRoot instanceof HTMLElement) {
        this.resizeObserver = new ResizeObserver(this.sync);
        this.resizeObserver.observe(this.scrollRoot);
      }
    }
    this.connectedHost = host;
    this.connectedSurface = surface;
    const insets = this.options.insets();
    const insetsChanged =
      insets.blockStart !== this.insetBlockStart || insets.blockEnd !== this.insetBlockEnd;
    this.insetBlockStart = insets.blockStart;
    this.insetBlockEnd = insets.blockEnd;
    if (forceGeometry || elementsChanged || rootChanged || insetsChanged) this.sync();
  }

  /** Pass a fitted table's boundary wheel delta to its owning page scrollport. */
  scrollOuterBy(delta: number): boolean {
    if (!this.scrollRoot || delta === 0) return false;
    if (this.scrollRoot instanceof HTMLElement) {
      const previous = this.scrollRoot.scrollTop;
      const max = Math.max(0, this.scrollRoot.scrollHeight - this.scrollRoot.clientHeight);
      this.scrollRoot.scrollTop = Math.min(max, Math.max(0, previous + delta));
      return this.scrollRoot.scrollTop !== previous;
    }

    const scrollingElement = document.scrollingElement;
    const previous = window.scrollY;
    const max = Math.max(
      0,
      (scrollingElement?.scrollHeight ?? document.documentElement.scrollHeight) - window.innerHeight
    );
    const next = Math.min(max, Math.max(0, previous + delta));
    if (next !== previous) window.scrollTo({ top: next, behavior: 'auto' });
    return next !== previous;
  }

  private disconnectRuntime(): void {
    this.scrollRoot?.removeEventListener('scroll', this.sync);
    window.removeEventListener('resize', this.sync);
    this.scrollRoot = null;
    this.connectedHost = null;
    this.connectedSurface = null;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.insetBlockStart = null;
    this.insetBlockEnd = null;
  }

  private clearGeometry(): void {
    const { host, surface } = this.options.elements();
    host?.style.removeProperty('--_table-viewport-fit-reserved-block-size');
    surface?.style.removeProperty('--_table-viewport-fit-current-block-size');
    if (this.metrics !== null) {
      this.metrics = null;
      this.options.fitChanged(null);
    }
  }

  private readonly sync = (): void => {
    if (!this.connected || !this.options.enabled() || !this.scrollRoot) return;
    const { host, surface } = this.options.elements();
    if (!host) return;

    const hostRect = host.getBoundingClientRect();
    const scrollportRect =
      this.scrollRoot instanceof HTMLElement
        ? this.scrollRoot.getBoundingClientRect()
        : { top: 0, height: window.innerHeight };
    const insets = this.options.insets();
    const next = resolveTableViewportFitMetrics({
      scrollportBlockStart: scrollportRect.top,
      scrollportBlockSize: scrollportRect.height,
      hostBlockStart: hostRect.top,
      insetBlockStart: resolveCssLengthPx(insets.blockStart, 0, host),
      insetBlockEnd: resolveCssLengthPx(insets.blockEnd, 0, host),
    });

    this.setProperty(
      host,
      '--_table-viewport-fit-reserved-block-size',
      `${next.reservedBlockSize}px`
    );
    if (surface) {
      this.setProperty(
        surface,
        '--_table-viewport-fit-current-block-size',
        `${next.currentBlockSize}px`
      );
    }
    if (
      !this.metrics ||
      this.metrics.reservedBlockSize !== next.reservedBlockSize ||
      this.metrics.currentBlockSize !== next.currentBlockSize ||
      this.metrics.settled !== next.settled
    ) {
      this.metrics = next;
      this.options.fitChanged(next);
    }
  };

  private findScrollRoot(host: HTMLElement): HTMLElement | Window {
    let ancestor = this.composedParent(host);
    while (ancestor && ancestor !== document.documentElement) {
      const overflow = getComputedStyle(ancestor).overflowY;
      if (overflow === 'auto' || overflow === 'scroll' || overflow === 'overlay') {
        return ancestor as HTMLElement;
      }
      ancestor = this.composedParent(ancestor);
    }
    return window;
  }

  private composedParent(element: Element): Element | null {
    return (element as HTMLElement).assignedSlot?.parentElement ?? element.parentElement;
  }

  private setProperty(element: HTMLElement, property: string, value: string): void {
    if (element.style.getPropertyValue(property) !== value) {
      element.style.setProperty(property, value);
    }
  }
}

import {
  createTableVirtualIndex,
  findTableVirtualIndexAtOffset,
  resolveTableVirtualPlanFromIndex,
  sameTableVirtualPlan,
  tableVirtualItemSizes,
  type TableVirtualItem,
  type TableVirtualIndex,
  type TableVirtualPlan,
} from './table-virtual-model';

export interface TableVirtualControllerState {
  enabled: boolean;
  items: readonly TableVirtualItem[];
  pinnedRowIds: ReadonlySet<string>;
  viewport: HTMLElement | null;
  viewportSize: number;
}

export interface TableVirtualControllerOptions {
  state: () => TableVirtualControllerState;
  windowChanged: (plan: TableVirtualPlan | null) => void;
  requestAnimationFrame?: (callback: FrameRequestCallback) => number;
  cancelAnimationFrame?: (handle: number) => void;
}

const MEASURE_EPSILON_PX = 0.5;

/** Binds viewport scroll/resize to a recycled row window. Scroll offset stays off render state. */
export class TableVirtualController {
  private connected = false;
  private connectedViewport: HTMLElement | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private measurementObserver: ResizeObserver | null = null;
  private measurementTargets = new Set<HTMLElement>();
  private viewportWidth = 0;
  private viewportSize = 0;
  private frame: number | null = null;
  private measures = new Map<string, number>();
  private measuredIds = new Set<string>();
  private plan: TableVirtualPlan | null = null;
  private index: TableVirtualIndex | null = null;
  private indexedItems: readonly TableVirtualItem[] | null = null;
  private indexDirty = true;
  private scrollOffset = 0;
  private scrollDirection: 'backward' | 'forward' | 'none' = 'none';
  private pendingReset = false;
  private readonly raf: (callback: FrameRequestCallback) => number;
  private readonly caf: (handle: number) => void;

  constructor(private readonly options: TableVirtualControllerOptions) {
    this.raf =
      options.requestAnimationFrame ??
      (typeof requestAnimationFrame === 'function'
        ? callback => requestAnimationFrame(callback)
        : callback => setTimeout(callback, 16) as unknown as number);
    this.caf =
      options.cancelAnimationFrame ??
      (typeof cancelAnimationFrame === 'function'
        ? handle => cancelAnimationFrame(handle)
        : handle => clearTimeout(handle));
  }

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    this.cancelFrame();
    this.unbindViewport();
  }

  refresh(): void {
    if (!this.connected) return;
    const { viewport, enabled } = this.options.state();
    if (!enabled || !viewport) {
      this.unbindViewport();
      this.emit(null);
      return;
    }
    if (viewport !== this.connectedViewport) {
      this.unbindViewport();
      this.connectedViewport = viewport;
      this.viewportWidth = viewport.clientWidth;
      this.viewportSize = viewport.clientHeight;
      this.scrollOffset = viewport.scrollTop;
      viewport.addEventListener('scroll', this.handleScroll, { passive: true });
      if (typeof ResizeObserver !== 'undefined') {
        this.resizeObserver = new ResizeObserver(this.handleViewportResize);
        this.resizeObserver.observe(viewport);
      }
    }
    this.sync();
  }

  schedule = (): void => {
    if (!this.connected || this.frame !== null) return;
    this.frame = this.raf(() => {
      this.frame = null;
      this.sync();
    });
  };

  /** Drop cached heights after column, density, or wrap geometry changes. */
  invalidateMeasures(): void {
    this.measures.clear();
    this.measuredIds.clear();
    this.indexDirty = true;
    this.schedule();
  }

  /** Rebuild from a new index and pin the viewport to the start. */
  resetToTop(): void {
    this.pendingReset = true;
    this.measures.clear();
    this.measuredIds.clear();
    this.indexDirty = true;
    this.scrollOffset = 0;
    this.scrollDirection = 'none';
    const viewport = this.connectedViewport ?? this.options.state().viewport;
    if (viewport) viewport.scrollTop = 0;
    this.schedule();
  }

  sizeFor(item: TableVirtualItem): number {
    if (!item.variableSize) return item.estimatedSize;
    return this.measures.get(item.id) ?? item.estimatedSize;
  }

  currentPlan(): TableVirtualPlan | null {
    return this.plan;
  }

  currentViewportSize(): number {
    return this.viewportSize;
  }

  /** Measure painted rows and correct scroll when estimates were wrong. */
  collectMeasurements(root: ParentNode | null): void {
    if (!root || !this.connected || !this.options.state().enabled) return;
    const painted = root.querySelectorAll<HTMLElement>('[data-virtual-measure="true"]');
    this.syncMeasurementTargets(painted);
    if (painted.length === 0) return;

    const state = this.options.state();
    const measurements: Array<{ id: string; height: number }> = [];
    painted.forEach(element => {
      const id = element.getAttribute('data-virtual-id');
      if (!id || this.measuredIds.has(id)) return;
      measurements.push({ id, height: element.getBoundingClientRect().height });
    });
    this.applyMeasurements(state.items, measurements);
  }

  private applyMeasurements(
    items: readonly TableVirtualItem[],
    measurements: readonly { id: string; height: number }[]
  ): void {
    if (measurements.length === 0) return;
    const currentIndex = this.ensureIndex(items);
    const prefixBefore = currentIndex.prefix;
    const viewport = this.connectedViewport;
    const scrollTop = viewport?.scrollTop ?? this.scrollOffset;
    const anchorIndex = findTableVirtualIndexAtOffset(prefixBefore, scrollTop);
    const anchorOffset = prefixBefore[anchorIndex] ?? 0;
    let changed = false;
    for (const { id, height } of measurements) {
      if (!Number.isFinite(height) || height <= 0) continue;
      const itemIndex = currentIndex.itemIndexById.get(id);
      const item = itemIndex == null ? undefined : items[itemIndex];
      if (!item?.variableSize) continue;
      this.measuredIds.add(id);
      const previous = this.measures.get(id);
      if (Math.abs(item.estimatedSize - height) < MEASURE_EPSILON_PX) {
        if (previous != null) {
          this.measures.delete(id);
          changed = true;
        }
        continue;
      }
      if (previous != null && Math.abs(previous - height) < MEASURE_EPSILON_PX) continue;
      this.measures.set(id, height);
      changed = true;
    }
    if (!changed) return;
    this.indexDirty = true;
    const prefixAfter = this.ensureIndex(items).prefix;
    const nextAnchor = prefixAfter[anchorIndex] ?? 0;
    const delta = nextAnchor - anchorOffset;
    if (viewport && Math.abs(delta) >= MEASURE_EPSILON_PX) {
      viewport.scrollTop = Math.max(0, viewport.scrollTop + delta);
      this.scrollOffset = viewport.scrollTop;
    }
    this.sync();
  }

  private syncMeasurementTargets(elements: NodeListOf<HTMLElement>): void {
    if (typeof ResizeObserver === 'undefined') return;
    if (!this.measurementObserver) {
      this.measurementObserver = new ResizeObserver(entries => {
        const state = this.options.state();
        const measurements = entries.map(entry => ({
          id: (entry.target as HTMLElement).getAttribute('data-virtual-id') ?? '',
          height: entry.borderBoxSize[0]?.blockSize ?? entry.contentRect.height,
        }));
        this.applyMeasurements(state.items, measurements);
      });
    }
    const next = new Set(elements);
    for (const element of this.measurementTargets) {
      if (!next.has(element)) this.measurementObserver.unobserve(element);
    }
    for (const element of next) {
      if (!this.measurementTargets.has(element)) this.measurementObserver.observe(element);
    }
    this.measurementTargets = next;
  }

  private readonly handleViewportResize = (entries: ResizeObserverEntry[]): void => {
    const entry = entries.find(candidate => candidate.target === this.connectedViewport);
    const width = entry?.contentRect.width ?? this.connectedViewport?.clientWidth ?? 0;
    const size = entry?.contentRect.height ?? this.connectedViewport?.clientHeight ?? 0;
    const sizeChanged = size !== this.viewportSize;
    this.viewportSize = size;
    if (width !== this.viewportWidth) {
      this.viewportWidth = width;
      const items = this.options.state().items;
      const hasVariableSize =
        this.indexedItems === items && this.index
          ? this.index.hasVariableSize
          : items.some(item => item.variableSize);
      if (hasVariableSize) this.invalidateMeasures();
      else if (sizeChanged) this.schedule();
      return;
    }
    if (sizeChanged) this.schedule();
  };

  private readonly handleScroll = (): void => {
    const viewport = this.connectedViewport;
    if (viewport) {
      const nextOffset = viewport.scrollTop;
      this.scrollDirection =
        nextOffset > this.scrollOffset
          ? 'forward'
          : nextOffset < this.scrollOffset
            ? 'backward'
            : this.scrollDirection;
      this.scrollOffset = nextOffset;
    }
    this.schedule();
  };

  private sync(): void {
    if (!this.connected) return;
    const state = this.options.state();
    if (!state.enabled) {
      this.emit(null);
      return;
    }

    if (this.pendingReset) {
      this.scrollOffset = 0;
      if (state.viewport) state.viewport.scrollTop = 0;
      this.pendingReset = false;
    }
    const index = this.ensureIndex(state.items);
    const plan = resolveTableVirtualPlanFromIndex(index, {
      scrollOffset: this.scrollOffset,
      viewportSize: this.viewportSize || state.viewportSize,
      scrollDirection: this.scrollDirection,
      pinnedRowIds: state.pinnedRowIds,
    });
    this.emit(plan);
  }

  private emit(plan: TableVirtualPlan | null): void {
    if (sameTableVirtualPlan(this.plan, plan)) return;
    this.plan = plan;
    this.options.windowChanged(plan);
  }

  private ensureIndex(items: readonly TableVirtualItem[]): TableVirtualIndex {
    if (!this.indexDirty && this.index && this.indexedItems === items) return this.index;
    if (this.indexedItems !== items && (this.measures.size > 0 || this.measuredIds.size > 0)) {
      const itemIds = new Set(items.map(item => item.id));
      for (const id of this.measures.keys()) {
        if (!itemIds.has(id)) this.measures.delete(id);
      }
      for (const id of this.measuredIds) {
        if (!itemIds.has(id)) this.measuredIds.delete(id);
      }
    }
    this.indexedItems = items;
    this.index = createTableVirtualIndex(items, tableVirtualItemSizes(items, this.measures));
    this.indexDirty = false;
    return this.index;
  }

  private unbindViewport(): void {
    this.connectedViewport?.removeEventListener('scroll', this.handleScroll);
    this.connectedViewport = null;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.measurementObserver?.disconnect();
    this.measurementObserver = null;
    this.measurementTargets.clear();
    this.viewportWidth = 0;
    this.viewportSize = 0;
  }

  private cancelFrame(): void {
    if (this.frame === null) return;
    this.caf(this.frame);
    this.frame = null;
  }
}

import { resolveTableCellPresentation } from './table-cell-model';
import type { TableColumn, TableGroup, TableRow } from './table-types';

/**
 * Token-aligned body-row track contracts: 40 / 64 / 88, plus wrapping-secondary
 * 112. Every track is 24px with no stack gap. Estimates only; measured heights
 * replace these after paint.
 */
export const TABLE_VIRTUAL_ROW_TRACK_SIZE = {
  1: 40,
  2: 64,
  3: 88,
  4: 112,
} as const;

const TABLE_VIRTUAL_LATER_TRACK_INCREMENT =
  TABLE_VIRTUAL_ROW_TRACK_SIZE[2] - TABLE_VIRTUAL_ROW_TRACK_SIZE[1];

/** Estimated row height for any positive named track count. */
export function tableVirtualRowTrackSize(tracks: number): number {
  const count = Number.isFinite(tracks) && tracks > 0 ? Math.floor(tracks) : 1;
  return TABLE_VIRTUAL_ROW_TRACK_SIZE[1] + (count - 1) * TABLE_VIRTUAL_LATER_TRACK_INCREMENT;
}

export const TABLE_VIRTUAL_GROUP_HEADER_SIZE = TABLE_VIRTUAL_ROW_TRACK_SIZE[1];
export const TABLE_VIRTUAL_MIN_OVERSCAN_ROWS = 8;

export const TABLE_VIRTUAL_VIEWPORT_REQUIRED_HEADING = 'Bounded height required';
export const TABLE_VIRTUAL_VIEWPORT_REQUIRED_BODY =
  'Virtual mode requires height, maxHeight, or fitViewport.';

export const TABLE_VIRTUAL_TOTAL_SUMMARY_LABEL = '{total} items';

export type TableVirtualItemKind = 'group' | 'row';

export interface TableVirtualItem {
  kind: TableVirtualItemKind;
  id: string;
  groupId?: string;
  rowId?: string;
  estimatedSize: number;
  variableSize: boolean;
}

export type TableVirtualNode =
  | { kind: 'spacer'; size: number; key: string }
  | { kind: 'row'; index: number; item: TableVirtualItem }
  | {
      kind: 'group';
      groupId: string;
      headerIndex: number;
      nodes: Array<Extract<TableVirtualNode, { kind: 'spacer' | 'row' }>>;
    };

export interface TableVirtualPlan {
  totalSize: number;
  itemCount: number;
  start: number;
  end: number;
  nodes: TableVirtualNode[];
  mountedIds: ReadonlySet<string>;
  mountedIndexes: ReadonlySet<number>;
}

export interface FlattenTableVirtualItemsInput {
  grouped: boolean;
  rows: TableRow[];
  groups: TableGroup[];
  collapsedGroupIds: ReadonlySet<string> | readonly string[];
  columns: TableColumn[];
}

export interface ResolveTableVirtualPlanInput {
  items: readonly TableVirtualItem[];
  sizes: readonly number[];
  scrollOffset: number;
  viewportSize: number;
  pinnedRowIds?: ReadonlySet<string>;
}

export interface TableVirtualIndex {
  items: readonly TableVirtualItem[];
  sizes: readonly number[];
  prefix: readonly number[];
  itemCount: number;
  totalSize: number;
  hasVariableSize: boolean;
  grouped: boolean;
  groupHeaderIndexes: readonly number[];
  headerIndexByGroup: ReadonlyMap<string, number>;
  groupEndByHeader: ReadonlyMap<number, number>;
  rowIndexById: ReadonlyMap<string, number>;
  itemIndexById: ReadonlyMap<string, number>;
}

export interface ResolveTableVirtualIndexedPlanInput {
  scrollOffset: number;
  viewportSize: number;
  scrollDirection?: 'backward' | 'forward' | 'none';
  pinnedRowIds?: ReadonlySet<string>;
}

/** Map a cell recipe onto the named track stack used for first-paint estimates. */
export function estimateTableCellTrackCount(
  value: TableRow['cells'][string],
  column: TableColumn
): number {
  return tableCellTrackCount(resolveTableCellPresentation(value, column));
}

function tableCellTrackCount(
  presentation: ReturnType<typeof resolveTableCellPresentation>
): number {
  if (presentation.kind === 'image') {
    return presentation.variant === 'triple' ? 3 : presentation.variant === 'multi' ? 2 : 1;
  }
  if (presentation.kind === 'tag') {
    return presentation.variant === 'text-with-tag' ? 2 : 1;
  }
  if (presentation.kind === 'tags') return presentation.tracks;
  if (presentation.kind !== 'text' && presentation.kind !== 'icon-text') return 1;

  const variantTracks =
    presentation.variant === 'triple'
      ? 3
      : presentation.variant === 'multi' || presentation.variant === 'primary-pair'
        ? 2
        : 1;
  if (!presentation.wraps) return variantTracks;
  if (presentation.lineClamp === 'none') {
    return presentation.kind === 'text' && !presentation.singleLine ? 4 : 3;
  }
  if (presentation.lineClamp === 3 && variantTracks >= 2) return 4;
  return Math.max(variantTracks, presentation.lineClamp);
}

/** Tallest named track stack across the row's visible cells. */
export function estimateTableRowBlockSize(row: TableRow, columns: readonly TableColumn[]): number {
  return tableVirtualRowMetrics(row, columns).estimatedSize;
}

function tableVirtualRowMetrics(
  row: TableRow,
  columns: readonly TableColumn[]
): Pick<TableVirtualItem, 'estimatedSize' | 'variableSize'> {
  let tracks = 1;
  let variableSize = false;
  for (const column of columns) {
    const value = row.cells[column.id];
    const presentation = resolveTableCellPresentation(value, column);
    if (
      (presentation.kind === 'text' || presentation.kind === 'icon-text') &&
      presentation.wraps &&
      presentation.lineClamp === 'none'
    ) {
      variableSize = true;
    }
    if (presentation.kind === 'tags') variableSize = true;
    const count = tableCellTrackCount(presentation);
    if (count > tracks) tracks = count;
  }
  return { estimatedSize: tableVirtualRowTrackSize(tracks), variableSize };
}

export function flattenTableVirtualItems(input: FlattenTableVirtualItemsInput): TableVirtualItem[] {
  const collapsed =
    input.collapsedGroupIds instanceof Set
      ? input.collapsedGroupIds
      : new Set(input.collapsedGroupIds);
  if (!input.grouped) {
    return input.rows.map(row => {
      const metrics = tableVirtualRowMetrics(row, input.columns);
      return {
        kind: 'row' as const,
        id: `row:${row.id}`,
        rowId: row.id,
        ...metrics,
      };
    });
  }

  const items: TableVirtualItem[] = [];
  for (const group of input.groups) {
    items.push({
      kind: 'group',
      id: `group:${group.id}`,
      groupId: group.id,
      estimatedSize: TABLE_VIRTUAL_GROUP_HEADER_SIZE,
      variableSize: false,
    });
    if (collapsed.has(group.id)) continue;
    for (const row of group.rows) {
      const metrics = tableVirtualRowMetrics(row, input.columns);
      items.push({
        kind: 'row',
        id: `row:${row.id}`,
        rowId: row.id,
        groupId: group.id,
        ...metrics,
      });
    }
  }
  return items;
}

export function tableVirtualOverscanPx(viewportSize: number): number {
  const min = TABLE_VIRTUAL_MIN_OVERSCAN_ROWS * TABLE_VIRTUAL_ROW_TRACK_SIZE[1];
  return Math.max(0, viewportSize / 2, min);
}

export function buildTableVirtualPrefixSums(sizes: readonly number[]): number[] {
  const prefix = new Array<number>(sizes.length + 1);
  prefix[0] = 0;
  for (let index = 0; index < sizes.length; index += 1) {
    prefix[index + 1] = prefix[index] + Math.max(0, sizes[index] ?? 0);
  }
  return prefix;
}

/** Largest item index whose start offset is <= `offset`. */
export function findTableVirtualIndexAtOffset(prefix: readonly number[], offset: number): number {
  const lastIndex = prefix.length - 2;
  if (lastIndex < 0) return 0;
  const target = Math.max(0, offset);
  let low = 0;
  let high = lastIndex;
  while (low < high) {
    const mid = (low + high + 1) >> 1;
    if ((prefix[mid] ?? 0) <= target) low = mid;
    else high = mid - 1;
  }
  return low;
}

export function tableVirtualItemSizes(
  items: readonly TableVirtualItem[],
  measures: ReadonlyMap<string, number>
): number[] {
  return items.map(item => measures.get(item.id) ?? item.estimatedSize);
}

export function sameTableVirtualPlan(
  left: TableVirtualPlan | null | undefined,
  right: TableVirtualPlan | null | undefined
): boolean {
  if (left === right) return true;
  if (!left || !right) return false;
  if (
    left.start !== right.start ||
    left.end !== right.end ||
    left.totalSize !== right.totalSize ||
    left.itemCount !== right.itemCount ||
    left.mountedIndexes.size !== right.mountedIndexes.size
  ) {
    return false;
  }
  for (const index of left.mountedIndexes) {
    if (!right.mountedIndexes.has(index)) return false;
  }
  return sameVirtualNodes(left.nodes, right.nodes);
}

function sameVirtualNodes(
  left: readonly TableVirtualNode[],
  right: readonly TableVirtualNode[]
): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index += 1) {
    const a = left[index];
    const b = right[index];
    if (!a || !b || a.kind !== b.kind) return false;
    if (a.kind === 'spacer' && b.kind === 'spacer') {
      if (a.size !== b.size || a.key !== b.key) return false;
      continue;
    }
    if (a.kind === 'row' && b.kind === 'row') {
      if (a.index !== b.index || a.item.id !== b.item.id) return false;
      continue;
    }
    if (a.kind === 'group' && b.kind === 'group') {
      if (a.groupId !== b.groupId || a.headerIndex !== b.headerIndex) return false;
      if (!sameVirtualNodes(a.nodes, b.nodes)) return false;
    }
  }
  return true;
}

/** Precompute dataset-wide lookup state. Rebuild only when items or their sizes change. */
export function createTableVirtualIndex(
  items: readonly TableVirtualItem[],
  sizes: readonly number[]
): TableVirtualIndex {
  const prefix = buildTableVirtualPrefixSums(sizes);
  const itemCount = items.length;
  const groupHeaderIndexes: number[] = [];
  const headerIndexByGroup = new Map<string, number>();
  const groupEndByHeader = new Map<number, number>();
  const rowIndexById = new Map<string, number>();
  const itemIndexById = new Map<string, number>();
  let activeHeaderIndex: number | null = null;
  let hasVariableSize = false;

  for (let itemIndex = 0; itemIndex < itemCount; itemIndex += 1) {
    const item = items[itemIndex];
    if (item) {
      itemIndexById.set(item.id, itemIndex);
      hasVariableSize ||= item.variableSize;
    }
    if (item?.kind === 'group' && item.groupId) {
      if (activeHeaderIndex != null) groupEndByHeader.set(activeHeaderIndex, itemIndex);
      activeHeaderIndex = itemIndex;
      groupHeaderIndexes.push(itemIndex);
      headerIndexByGroup.set(item.groupId, itemIndex);
    } else if (item?.kind === 'row' && item.rowId) {
      rowIndexById.set(item.rowId, itemIndex);
    }
  }
  if (activeHeaderIndex != null) groupEndByHeader.set(activeHeaderIndex, itemCount);

  return {
    items,
    sizes,
    prefix,
    itemCount,
    totalSize: prefix[itemCount] ?? 0,
    hasVariableSize,
    grouped: groupHeaderIndexes.length > 0,
    groupHeaderIndexes,
    headerIndexByGroup,
    groupEndByHeader,
    rowIndexById,
    itemIndexById,
  };
}

/** Resolve the mounted slice from cached dataset-wide lookup state. */
export function resolveTableVirtualPlanFromIndex(
  index: TableVirtualIndex,
  input: ResolveTableVirtualIndexedPlanInput
): TableVirtualPlan {
  const { items, prefix, itemCount, totalSize } = index;
  const empty: TableVirtualPlan = {
    totalSize,
    itemCount,
    start: 0,
    end: 0,
    nodes: totalSize > 0 ? [{ kind: 'spacer', size: totalSize, key: 'pad-empty' }] : [],
    mountedIds: new Set(),
    mountedIndexes: new Set(),
  };
  if (itemCount === 0) return empty;

  const viewportSize = Math.max(0, input.viewportSize);
  const overscan = tableVirtualOverscanPx(viewportSize);
  const trailingOverscan = (TABLE_VIRTUAL_MIN_OVERSCAN_ROWS * TABLE_VIRTUAL_ROW_TRACK_SIZE[1]) / 4;
  const before = input.scrollDirection === 'forward' ? trailingOverscan : overscan;
  const after = input.scrollDirection === 'backward' ? trailingOverscan : overscan;
  const scrollOffset = Math.max(0, Math.min(input.scrollOffset, Math.max(0, totalSize)));
  const rangeStart = Math.max(0, scrollOffset - before);
  const rangeEnd = scrollOffset + viewportSize + after;
  const start = findTableVirtualIndexAtOffset(prefix, rangeStart);
  let end = start;
  while (end < itemCount && (prefix[end] ?? 0) < rangeEnd) end += 1;
  if (end === start) end = Math.min(itemCount, start + 1);

  const mounted = new Set<number>();
  for (let itemIndex = start; itemIndex < end; itemIndex += 1) mounted.add(itemIndex);

  const pinHeader = (groupId: string | undefined) => {
    if (!groupId) return;
    const headerIndex = index.headerIndexByGroup.get(groupId);
    if (headerIndex != null) mounted.add(headerIndex);
  };
  for (const mountedIndex of [...mounted]) pinHeader(items[mountedIndex]?.groupId);

  const nextHeader = firstTableVirtualIndexAfter(index.groupHeaderIndexes, end - 1);
  if (nextHeader != null) mounted.add(nextHeader);

  if (input.pinnedRowIds) {
    for (const rowId of input.pinnedRowIds) {
      const rowIndex = index.rowIndexById.get(rowId);
      if (rowIndex == null) continue;
      mounted.add(rowIndex);
      pinHeader(items[rowIndex]?.groupId);
    }
  }

  const mountedSorted = [...mounted].sort((left, right) => left - right);
  const nodes = index.grouped
    ? buildGroupedVirtualNodes(index, mounted, mountedSorted)
    : buildFlatVirtualNodes(index, mountedSorted);
  const mountedIds = new Set<string>();
  for (const mountedIndex of mounted) {
    const id = items[mountedIndex]?.id;
    if (id) mountedIds.add(id);
  }

  return {
    totalSize,
    itemCount,
    start: mountedSorted[0] ?? start,
    end: mountedSorted.length > 0 ? mountedSorted[mountedSorted.length - 1]! + 1 : end,
    nodes,
    mountedIds,
    mountedIndexes: mounted,
  };
}

/** Resolve a one-off plan. Controllers retain and reuse a prepared index. */
export function resolveTableVirtualPlan(input: ResolveTableVirtualPlanInput): TableVirtualPlan {
  return resolveTableVirtualPlanFromIndex(createTableVirtualIndex(input.items, input.sizes), input);
}

function firstTableVirtualIndexAfter(
  indexes: readonly number[],
  target: number
): number | undefined {
  let low = 0;
  let high = indexes.length;
  while (low < high) {
    const middle = (low + high) >> 1;
    if ((indexes[middle] ?? 0) <= target) low = middle + 1;
    else high = middle;
  }
  return indexes[low];
}

function buildFlatVirtualNodes(
  index: TableVirtualIndex,
  mounted: readonly number[]
): TableVirtualNode[] {
  const { items, prefix, itemCount } = index;
  const nodes: TableVirtualNode[] = [];
  let cursor = 0;
  for (const mountedIndex of mounted) {
    const item = items[mountedIndex];
    if (!item) continue;
    const spacerSize = (prefix[mountedIndex] ?? 0) - (prefix[cursor] ?? 0);
    if (spacerSize > 0) {
      nodes.push({ kind: 'spacer', size: spacerSize, key: `pad-${cursor}-${mountedIndex}` });
    }
    nodes.push({ kind: 'row', index: mountedIndex, item });
    cursor = mountedIndex + 1;
  }
  const trailingSize = (prefix[itemCount] ?? 0) - (prefix[cursor] ?? 0);
  if (trailingSize > 0) {
    nodes.push({ kind: 'spacer', size: trailingSize, key: `pad-${cursor}-${itemCount}` });
  }
  return nodes;
}

function buildGroupedVirtualNodes(
  index: TableVirtualIndex,
  mounted: ReadonlySet<number>,
  mountedSorted: readonly number[]
): TableVirtualNode[] {
  const { items, prefix, itemCount } = index;
  const nodes: TableVirtualNode[] = [];
  const selectedHeaders = new Set<number>();
  for (const mountedIndex of mountedSorted) {
    const item = items[mountedIndex];
    const headerIndex =
      item?.kind === 'group'
        ? mountedIndex
        : item?.groupId
          ? index.headerIndexByGroup.get(item.groupId)
          : undefined;
    if (headerIndex != null) selectedHeaders.add(headerIndex);
  }

  let cursor = 0;
  for (const headerIndex of [...selectedHeaders].sort((left, right) => left - right)) {
    const header = items[headerIndex];
    if (header?.kind !== 'group' || !header.groupId) continue;
    const groupId = header.groupId;
    const groupEnd = index.groupEndByHeader.get(headerIndex) ?? headerIndex + 1;
    const leadingSize = (prefix[headerIndex] ?? 0) - (prefix[cursor] ?? 0);
    if (leadingSize > 0) {
      nodes.push({ kind: 'spacer', size: leadingSize, key: `pad-${cursor}-${headerIndex}` });
    }

    const groupNodes: Array<Extract<TableVirtualNode, { kind: 'spacer' | 'row' }>> = [];
    const mountedMembers = mountedSorted.filter(
      mountedIndex => mountedIndex > headerIndex && mountedIndex < groupEnd
    );
    let memberCursor = headerIndex + 1;
    for (const memberIndex of mountedMembers) {
      const item = items[memberIndex];
      const spacerSize = (prefix[memberIndex] ?? 0) - (prefix[memberCursor] ?? 0);
      if (spacerSize > 0) {
        groupNodes.push({
          kind: 'spacer',
          size: spacerSize,
          key: `group-${groupId}-pad-${memberCursor}-${memberIndex}`,
        });
      }
      if (item?.kind === 'row' && mounted.has(memberIndex)) {
        groupNodes.push({ kind: 'row', index: memberIndex, item });
      }
      memberCursor = memberIndex + 1;
    }
    const trailingSize = (prefix[groupEnd] ?? 0) - (prefix[memberCursor] ?? 0);
    if (trailingSize > 0) {
      groupNodes.push({
        kind: 'spacer',
        size: trailingSize,
        key: `group-${groupId}-pad-${memberCursor}-${groupEnd}`,
      });
    }

    nodes.push({ kind: 'group', groupId, headerIndex, nodes: groupNodes });
    cursor = groupEnd;
  }

  const trailingSize = (prefix[itemCount] ?? 0) - (prefix[cursor] ?? 0);
  if (trailingSize > 0) {
    nodes.push({ kind: 'spacer', size: trailingSize, key: `pad-${cursor}-${itemCount}` });
  }
  return nodes;
}
